-- Imobdesk · parte 2 de 4 (20261007171000_imobdesk_tickets.sql … 20261009180000_imobdesk_gerencial.sql).
-- Cole no SQL Editor do ikvj e rode. Tudo numa transação.
begin;

-- ======================================== 20261007171000_imobdesk_tickets.sql
-- Ticket único (docs/PLANO-tickets-unificados.md, aprovado em 07/10/2026): ch_tickets é a fonte única dos
-- tickets de todos os canais. Ações (conversa), eventos (histórico), seguidores, prazo de SLA em horas úteis
-- pelo horário do setor (D6), pausa nos status pendentes (T9), visibilidade (D7), regras para exibição e
-- obrigatórios conferidos no banco (cadastros D7) e as RPCs que as telas usam. Só aditiva.

-- ---------- Tabelas ----------
create table if not exists imobdesk.ch_tickets (
  id                    bigint      generated by default as identity (start with 1000) primary key,
  assunto               text        not null check (length(btrim(assunto)) between 1 and 300),
  origem                text        not null check (origem in ('email', 'whatsapp', 'intranet', 'agente')),
  recebido_em           text        not null default 'Agente' check (length(recebido_em) <= 160),  -- conta, número ou "Intranet"/"Agente"
  solicitante_pessoa_id bigint      references imobdesk.at_pessoas (id) on delete set null,
  solicitante_nome      text        not null check (length(btrim(solicitante_nome)) between 1 and 160),
  solicitante_contato   text        check (length(solicitante_contato) <= 160),                    -- e-mail ou telefone de retorno
  email_conta_id        bigint      references imobdesk.at_email_contas (id) on delete set null,
  email_thread_id       text,                                                                         -- Message-ID raiz da conversa
  numero_id             bigint      references imobdesk.at_numeros (id) on delete set null,
  conversa_id           bigint      references imobdesk.at_conversas (id) on delete set null,
  setor_id              bigint      not null references imobdesk.at_setores (id),
  equipe_id             bigint      references imobdesk.at_equipes (id) on delete set null,
  responsavel_id        uuid        references imobdesk.usuarios (id) on delete set null,
  servico_id            bigint      references imobdesk.ch_servicos (id),
  categoria_id          bigint      references imobdesk.ch_categorias (id),
  urgencia_id           bigint      not null references imobdesk.ch_urgencias (id),
  status_id             bigint      not null references imobdesk.ch_status (id),
  justificativa_id      bigint      references imobdesk.ch_status_justificativas (id),
  tags                  text[]      not null default '{}',
  cc                    text[]      not null default '{}',
  campos                jsonb       not null default '{}',                                            -- valores dos campos adicionais, por chave
  solucao_aplicada      text        check (length(solucao_aplicada) <= 20000),
  criado_em             timestamptz not null default now(),
  criado_por            uuid,
  assumido_em           timestamptz,
  primeira_resposta_em  timestamptz,
  sla_resposta_ate      timestamptz,
  sla_solucao_ate       timestamptz,
  sla_manual            boolean     not null default false,                                           -- prazo alterado à mão (T9)
  sla_pausado_desde     timestamptz,
  encerrado_em          timestamptz,                                                                  -- resolvido, fechado ou cancelado
  mesclado_em_id        bigint      references imobdesk.ch_tickets (id),
  clonado_de_id         bigint      references imobdesk.ch_tickets (id),
  excluido_em           timestamptz,
  excluido_por          uuid,
  atualizado_em         timestamptz not null default now()
);
create index if not exists ch_tickets_setor_idx on imobdesk.ch_tickets (setor_id, encerrado_em);
create index if not exists ch_tickets_equipe_idx on imobdesk.ch_tickets (equipe_id);
create index if not exists ch_tickets_resp_idx on imobdesk.ch_tickets (responsavel_id);
create index if not exists ch_tickets_conversa_idx on imobdesk.ch_tickets (conversa_id);
create index if not exists ch_tickets_thread_idx on imobdesk.ch_tickets (email_thread_id);

create table if not exists imobdesk.ch_ticket_acoes (
  id               bigint      generated always as identity primary key,
  ticket_id        bigint      not null references imobdesk.ch_tickets (id) on delete cascade,
  numero           int         not null,
  tipo             text        not null check (tipo in ('publica', 'interna')),
  canal            text        not null check (canal in ('email', 'whatsapp', 'portal')),
  direcao          text        not null default 'saida' check (direcao in ('entrada', 'saida')),         -- entrada = veio do solicitante
  autor_id         uuid        references imobdesk.usuarios (id) on delete set null,
  autor_nome       text        not null,
  texto            text        not null default '' check (length(texto) <= 100000),
  html             text,
  anexos           jsonb       not null default '[]',
  envio_status     text        check (envio_status in ('pendente', 'enviado', 'falhou', 'nao_se_aplica')),
  envio_erro       text,
  email_message_id text,
  mensagem_id      bigint,                                                                               -- at_mensagens (WhatsApp)
  criado_em        timestamptz not null default now(),
  unique (ticket_id, numero)
);

create table if not exists imobdesk.ch_ticket_eventos (
  id         bigint      generated always as identity primary key,
  ticket_id  bigint      not null references imobdesk.ch_tickets (id) on delete cascade,
  tipo       text        not null,
  descricao  text        not null,
  de         jsonb,
  para       jsonb,
  autor_id   uuid,
  autor_nome text        not null default 'Sistema',
  criado_em  timestamptz not null default now()
);
create index if not exists ch_ticket_eventos_idx on imobdesk.ch_ticket_eventos (ticket_id, criado_em);

create table if not exists imobdesk.ch_ticket_seguidores (
  ticket_id  bigint not null references imobdesk.ch_tickets (id) on delete cascade,
  usuario_id uuid   not null references imobdesk.usuarios (id) on delete cascade,
  primary key (ticket_id, usuario_id)
);

do $$
declare
  t text;
begin
  foreach t in array array['ch_tickets', 'ch_ticket_acoes', 'ch_ticket_eventos', 'ch_ticket_seguidores'] loop
    execute format('alter table imobdesk.%I enable row level security', t);
    execute format('revoke all on imobdesk.%I from anon, public, authenticated', t);
    execute format('grant all on imobdesk.%I to service_role', t);
  end loop;
end;
$$;

-- ---------- Prazo em horas úteis (D6) ----------
/**
 * Soma horas úteis a partir de um instante, no horário do setor (at_horarios, fuso de São Paulo).
 * Setor sem horário cadastrado = horas corridas.
 */
create or replace function imobdesk.ch_somar_horas_uteis(p_setor bigint, p_inicio timestamptz, p_horas numeric)
returns timestamptz
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_restante numeric := p_horas * 60;   -- minutos
  v_cursor timestamp := (p_inicio at time zone 'America/Sao_Paulo');
  v_dia date;
  h record;
  v_ini timestamp;
  v_fim timestamp;
  v_disp numeric;
  i int := 0;
begin
  if p_horas is null or p_inicio is null then return null; end if;
  if not exists (select 1 from imobdesk.at_horarios x where x.setor_id = p_setor and x.aberto) then
    return p_inicio + make_interval(mins => round(v_restante)::int);
  end if;
  loop
    i := i + 1;
    exit when i > 800;
    v_dia := v_cursor::date;
    select x.aberto, x.abre, x.fecha into h from imobdesk.at_horarios x where x.setor_id = p_setor and x.dia = extract(dow from v_dia)::int;
    if found and h.aberto then
      v_ini := greatest(v_cursor, v_dia + h.abre);
      v_fim := v_dia + h.fecha;
      if v_ini < v_fim then
        v_disp := extract(epoch from (v_fim - v_ini)) / 60;
        if v_restante <= v_disp then
          return (v_ini + make_interval(mins => round(v_restante)::int)) at time zone 'America/Sao_Paulo';
        end if;
        v_restante := v_restante - v_disp;
      end if;
    end if;
    v_cursor := (v_dia + 1)::timestamp;
  end loop;
  return null;
end;
$$;

/** Horas de 1ª resposta e de solução: serviço × urgência (subindo pelos pais); sem prazo, o SLA padrão do setor. */
create or replace function imobdesk.ch_sla_horas(p_servico bigint, p_urgencia bigint, p_setor bigint)
returns table (resposta numeric, solucao numeric)
language sql
stable
security definer
set search_path = ''
as $$
  with recursive cadeia as (
    select s.id, s.pai_id, 0 as prof from imobdesk.ch_servicos s where s.id = p_servico
    union all
    select s.id, s.pai_id, c.prof + 1 from imobdesk.ch_servicos s join cadeia c on s.id = c.pai_id
  ), achado as (
    select l.resposta_horas, l.solucao_horas from cadeia c
    join imobdesk.ch_servicos_sla l on l.servico_id = c.id and l.urgencia_id = p_urgencia
    order by c.prof limit 1
  )
  select coalesce((select a.resposta_horas from achado a), (select st.sla_padrao_horas / 2 from imobdesk.at_setores st where st.id = p_setor)),
         coalesce((select a.solucao_horas from achado a), (select st.sla_padrao_horas from imobdesk.at_setores st where st.id = p_setor));
$$;

/** Equipe do serviço (o próprio ou o pai mais próximo que tenha equipe). */
create or replace function imobdesk.ch_servico_equipe(p_servico bigint)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  with recursive cadeia as (
    select s.id, s.pai_id, s.equipe_id, 0 as prof from imobdesk.ch_servicos s where s.id = p_servico
    union all
    select s.id, s.pai_id, s.equipe_id, c.prof + 1 from imobdesk.ch_servicos s join cadeia c on s.id = c.pai_id
  )
  select c.equipe_id from cadeia c where c.equipe_id is not null order by c.prof limit 1;
$$;

-- ---------- Visibilidade (D7) ----------
create or replace function imobdesk.ch_pode_ver_ticket(p_setor bigint, p_equipe bigint, p_responsavel uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  -- coalesce: com responsável vazio a comparação daria NULL, e "not NULL" deixaria passar (achado no ensaio).
  select coalesce(
         imobdesk.ch_eh_admin()
      or imobdesk.at_supervisor()
      or p_responsavel = (select auth.uid())
      or imobdesk.at_gestor_de(p_setor)
      or (imobdesk.tem_permissao('gestao_chamados_tickets')
          and ((p_equipe is not null and exists (select 1 from imobdesk.at_equipe_membros m where m.equipe_id = p_equipe and m.usuario_id = (select auth.uid())))
               or exists (select 1 from imobdesk.at_equipe_membros m join imobdesk.at_equipes e on e.id = m.equipe_id
                          where m.usuario_id = (select auth.uid()) and e.setor_id = p_setor and p_equipe is null)
               or imobdesk.at_membro_de(p_setor))), false);
$$;

create or replace function imobdesk.ch_ticket_visivel(p_id bigint)
returns imobdesk.ch_tickets
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets;
begin
  select * into t from imobdesk.ch_tickets x where x.id = p_id and (x.excluido_em is null or imobdesk.eh_super_admin());
  if t.id is null or not imobdesk.ch_pode_ver_ticket(t.setor_id, t.equipe_id, t.responsavel_id) then
    perform imobdesk.erro('NOT_FOUND', 'Ticket não encontrado.');
  end if;
  return t;
end;
$$;

-- ---------- Regras para exibição no banco ----------
/** O ticket atende a esta condição de regra? */
create or replace function imobdesk.ch_regra_condicao(t imobdesk.ch_tickets, c jsonb)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_campo text := c ->> 'campo';
  v_op text := c ->> 'operador';
  v_valores text[] := array(select jsonb_array_elements_text(coalesce(c -> 'valores', '[]')));
  v_atual text[];
begin
  if v_campo = 'servico' then
    -- O serviço do ticket ou qualquer serviço acima dele.
    with recursive cadeia as (
      select s.id, s.pai_id from imobdesk.ch_servicos s where s.id = t.servico_id
      union all select s.id, s.pai_id from imobdesk.ch_servicos s join cadeia c2 on s.id = c2.pai_id)
    select coalesce(array_agg(id::text), '{}') into v_atual from cadeia;
  elsif v_campo = 'categoria' then v_atual := array_remove(array[t.categoria_id::text], null);
  elsif v_campo = 'urgencia' then v_atual := array[t.urgencia_id::text];
  elsif v_campo = 'setor' then v_atual := array[t.setor_id::text];
  elsif v_campo = 'origem' then v_atual := array[t.origem];
  elsif v_campo like 'campo:%' then
    v_atual := case jsonb_typeof(t.campos -> substr(v_campo, 7))
                 when 'array' then array(select jsonb_array_elements_text(t.campos -> substr(v_campo, 7)))
                 when 'null' then '{}'
                 else array_remove(array[nullif(btrim(t.campos ->> substr(v_campo, 7)), '')], null) end;
  else
    return false;
  end if;
  return case v_op
    when 'um_de' then v_atual && v_valores
    when 'nao_um_de' then not (v_atual && v_valores)
    when 'preenchido' then cardinality(v_atual) > 0
    when 'vazio' then cardinality(v_atual) = 0
    else false end;
end;
$$;

/** Estado de cada campo adicional para este ticket: visível e obrigatório (regras de cima para baixo; a última vence). */
create or replace function imobdesk.ch_campos_estado(t imobdesk.ch_tickets)
returns table (chave text, visivel boolean, obrigatorio boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_vis jsonb := '{}';
  v_obr jsonb := '{}';
  c record;
  r record;
  a jsonb;
begin
  for c in select x.chave, x.obrigatorio from imobdesk.ch_campos x where x.ativo loop
    v_vis := v_vis || jsonb_build_object(c.chave, c.obrigatorio <> 'regra');
    v_obr := v_obr || jsonb_build_object(c.chave, c.obrigatorio = 'sempre');
  end loop;
  for r in select x.condicoes, x.acoes from imobdesk.ch_regras_exibicao x where x.ativa order by x.ordem, x.id loop
    if not exists (select 1 from jsonb_array_elements(r.condicoes) cc where not imobdesk.ch_regra_condicao(t, cc)) then
      for a in select * from jsonb_array_elements(r.acoes) loop
        continue when not (v_vis ? (a ->> 'campo'));
        if a ->> 'acao' = 'exibir' then v_vis := v_vis || jsonb_build_object(a ->> 'campo', true);
        elsif a ->> 'acao' = 'ocultar' then v_vis := v_vis || jsonb_build_object(a ->> 'campo', false); v_obr := v_obr || jsonb_build_object(a ->> 'campo', false);
        elsif a ->> 'acao' = 'obrigar' then v_vis := v_vis || jsonb_build_object(a ->> 'campo', true); v_obr := v_obr || jsonb_build_object(a ->> 'campo', true);
        elsif a ->> 'acao' = 'liberar' then v_obr := v_obr || jsonb_build_object(a ->> 'campo', false);
        end if;
      end loop;
    end if;
  end loop;
  return query select k, (v_vis ->> k)::boolean, (v_obr ->> k)::boolean from jsonb_object_keys(v_vis) k;
end;
$$;

/** Rótulos dos campos obrigatórios que estão vazios (bloqueiam resolver/fechar). */
create or replace function imobdesk.ch_campos_pendentes(t imobdesk.ch_tickets)
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(c.rotulo order by c.ordem), '{}')
  from imobdesk.ch_campos_estado(t) e
  join imobdesk.ch_campos c on c.chave = e.chave
  where e.obrigatorio and e.visivel
    and (t.campos -> e.chave is null or jsonb_typeof(t.campos -> e.chave) = 'null'
         or btrim(t.campos ->> e.chave) = '' or (jsonb_typeof(t.campos -> e.chave) = 'array' and jsonb_array_length(t.campos -> e.chave) = 0));
$$;

-- ---------- Gatilhos: SLA, pausa, encerramento e histórico ----------
create or replace function imobdesk.ch_tickets_antes()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cat text := (select s.categoria from imobdesk.ch_status s where s.id = new.status_id);
  v_cat_antes text;
  h record;
begin
  new.atualizado_em := now();
  if tg_op = 'UPDATE' then
    v_cat_antes := (select s.categoria from imobdesk.ch_status s where s.id = old.status_id);
  end if;
  -- Equipe: a do serviço; sem serviço, a padrão do setor.
  if new.equipe_id is null and (tg_op = 'INSERT' or new.servico_id is distinct from old.servico_id) then
    new.equipe_id := coalesce(imobdesk.ch_servico_equipe(new.servico_id), (select st.equipe_padrao_id from imobdesk.at_setores st where st.id = new.setor_id));
  end if;
  -- Prazos: na criação e quando muda serviço, urgência ou setor (se não foi alterado à mão).
  if not new.sla_manual and (tg_op = 'INSERT' or new.servico_id is distinct from old.servico_id or new.urgencia_id is distinct from old.urgencia_id or new.setor_id is distinct from old.setor_id) then
    select * into h from imobdesk.ch_sla_horas(new.servico_id, new.urgencia_id, new.setor_id);
    new.sla_resposta_ate := imobdesk.ch_somar_horas_uteis(new.setor_id, new.criado_em, h.resposta);
    new.sla_solucao_ate := imobdesk.ch_somar_horas_uteis(new.setor_id, new.criado_em, h.solucao);
  end if;
  -- Pausa nos pendentes (T9): ao sair, o prazo anda o tempo que ficou pausado.
  if v_cat = 'pendente' and new.sla_pausado_desde is null then
    new.sla_pausado_desde := now();
  elsif v_cat <> 'pendente' and new.sla_pausado_desde is not null then
    new.sla_solucao_ate := new.sla_solucao_ate + (now() - new.sla_pausado_desde);
    new.sla_pausado_desde := null;
  end if;
  -- Encerramento e reabertura.
  if v_cat in ('resolvido', 'fechado', 'cancelado') then
    if new.encerrado_em is null or tg_op = 'UPDATE' and v_cat_antes not in ('resolvido', 'fechado', 'cancelado') then
      new.encerrado_em := now();
    end if;
  else
    new.encerrado_em := null;
  end if;
  if v_cat = 'andamento' and new.assumido_em is null then new.assumido_em := now(); end if;
  -- Justificativa precisa ser do status.
  if new.justificativa_id is not null and not exists (select 1 from imobdesk.ch_status_justificativas j where j.id = new.justificativa_id and j.status_id = new.status_id) then
    new.justificativa_id := null;
  end if;
  return new;
end;
$$;

drop trigger if exists ch_tickets_antes on imobdesk.ch_tickets;
create trigger ch_tickets_antes before insert or update on imobdesk.ch_tickets
for each row execute function imobdesk.ch_tickets_antes();

/** Iniciais do avatar: primeira letra do primeiro e do último nome ("Ana Lima" → "AL"; "Wagner" → "W"). */
create or replace function imobdesk.ch_iniciais(p_nome text)
returns text
language sql
immutable
set search_path = ''
as $$
  select upper(left(btrim(p_nome), 1) ||
         case when array_length(regexp_split_to_array(btrim(p_nome), '\s+'), 1) > 1
              then left((regexp_split_to_array(btrim(p_nome), '\s+'))[array_length(regexp_split_to_array(btrim(p_nome), '\s+'), 1)], 1) else '' end);
$$;

create or replace function imobdesk.ch_nome_usuario(p uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select u.nome from imobdesk.usuarios u where u.id = p), 'Sistema');
$$;

create or replace function imobdesk.ch_tickets_historico()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_autor uuid := (select auth.uid());
  v_nome text := imobdesk.ch_nome_usuario((select auth.uid()));
begin
  if tg_op = 'INSERT' then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_id, autor_nome)
    values (new.id, 'criado', format('Ticket criado (%s)', new.origem), v_autor, v_nome);
    return null;
  end if;
  if new.status_id is distinct from old.status_id or new.justificativa_id is distinct from old.justificativa_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'status', 'Status alterado',
            jsonb_build_object('statusId', old.status_id, 'justificativaId', old.justificativa_id), jsonb_build_object('statusId', new.status_id, 'justificativaId', new.justificativa_id), v_autor, v_nome);
  end if;
  if new.responsavel_id is distinct from old.responsavel_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'responsavel', format('Responsável: %s', coalesce((select u.nome from imobdesk.usuarios u where u.id = new.responsavel_id), 'ninguém')),
            to_jsonb(old.responsavel_id), to_jsonb(new.responsavel_id), v_autor, v_nome);
  end if;
  if new.equipe_id is distinct from old.equipe_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'equipe', format('Equipe: %s', coalesce((select e.nome from imobdesk.at_equipes e where e.id = new.equipe_id), 'sem equipe')), to_jsonb(old.equipe_id), to_jsonb(new.equipe_id), v_autor, v_nome);
  end if;
  if new.servico_id is distinct from old.servico_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'servico', format('Serviço: %s', coalesce((select s.nome from imobdesk.ch_servicos s where s.id = new.servico_id), '—')), to_jsonb(old.servico_id), to_jsonb(new.servico_id), v_autor, v_nome);
  end if;
  if new.categoria_id is distinct from old.categoria_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'categoria', format('Categoria: %s', coalesce((select c.nome from imobdesk.ch_categorias c where c.id = new.categoria_id), '—')), to_jsonb(old.categoria_id), to_jsonb(new.categoria_id), v_autor, v_nome);
  end if;
  if new.urgencia_id is distinct from old.urgencia_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'urgencia', format('Urgência: %s', (select u.nome from imobdesk.ch_urgencias u where u.id = new.urgencia_id)), to_jsonb(old.urgencia_id), to_jsonb(new.urgencia_id), v_autor, v_nome);
  end if;
  if new.campos is distinct from old.campos then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'campos', 'Campos adicionais alterados', old.campos, new.campos, v_autor, v_nome);
  end if;
  if new.tags is distinct from old.tags then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'tags', 'Tags alteradas', to_jsonb(old.tags), to_jsonb(new.tags), v_autor, v_nome);
  end if;
  if new.sla_manual and (new.sla_solucao_ate is distinct from old.sla_solucao_ate) then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'sla', 'Previsão de solução alterada à mão', to_jsonb(old.sla_solucao_ate), to_jsonb(new.sla_solucao_ate), v_autor, v_nome);
  end if;
  return null;
end;
$$;

drop trigger if exists ch_tickets_historico on imobdesk.ch_tickets;
create trigger ch_tickets_historico after insert or update on imobdesk.ch_tickets
for each row execute function imobdesk.ch_tickets_historico();

-- ---------- RPCs ----------

/** Cria ticket pelo portal (agente ou intranet). Canais e-mail e WhatsApp criam pelas Edge Functions. */
create or replace function imobdesk.ch_ticket_criar(p jsonb)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := (select auth.uid());
  v_servico bigint := nullif(p ->> 'servicoId', '')::bigint;
  v_setor bigint := nullif(p ->> 'setorId', '')::bigint;
  v_id bigint;
  v_pessoa bigint := nullif(p ->> 'solicitantePessoaId', '')::bigint;
  v_nome text := btrim(coalesce(p ->> 'solicitanteNome', ''));
  v_contato text;
  v_texto text := coalesce(p ->> 'descricao', '');
begin
  if not (imobdesk.ch_eh_admin() or imobdesk.tem_permissao('gestao_chamados_tickets')) then
    perform imobdesk.erro('FORBIDDEN', 'Sem acesso para abrir tickets.');
  end if;
  if length(btrim(coalesce(p ->> 'assunto', ''))) = 0 then perform imobdesk.erro('INVALID_INPUT', 'Informe o assunto.', 'assunto'); end if;
  if length(btrim(v_texto)) = 0 then perform imobdesk.erro('INVALID_INPUT', 'Descreva a solicitação.', 'descricao'); end if;
  if v_servico is not null then
    select s.setor_id into v_setor from imobdesk.ch_servicos s where s.id = v_servico and s.ativo;
    if v_setor is null then perform imobdesk.erro('INVALID_INPUT', 'Serviço inválido.', 'servicoId'); end if;
  end if;
  if v_setor is null or not exists (select 1 from imobdesk.at_setores s where s.id = v_setor and s.ativo) then
    perform imobdesk.erro('INVALID_INPUT', 'Escolha o serviço ou o setor.', 'servicoId');
  end if;
  if v_pessoa is not null then
    select pe.nome, (select c.valor from imobdesk.at_pessoa_contatos c where c.pessoa_id = pe.id and c.tipo = 'email' order by c.principal desc limit 1)
      into v_nome, v_contato from imobdesk.at_pessoas pe where pe.id = v_pessoa;
  end if;
  if length(coalesce(v_nome, '')) = 0 then perform imobdesk.erro('INVALID_INPUT', 'Informe o solicitante.', 'solicitante'); end if;

  insert into imobdesk.ch_tickets (assunto, origem, recebido_em, solicitante_pessoa_id, solicitante_nome, solicitante_contato, setor_id, servico_id,
                                             categoria_id, urgencia_id, status_id, equipe_id, responsavel_id, tags, cc, campos, criado_por)
  values (btrim(p ->> 'assunto'), coalesce(nullif(p ->> 'origem', ''), 'agente'), case when p ->> 'origem' = 'intranet' then 'Intranet' else 'Agente' end,
          v_pessoa, v_nome, coalesce(v_contato, nullif(btrim(p ->> 'solicitanteContato'), '')), v_setor, v_servico,
          coalesce(nullif(p ->> 'categoriaId', '')::bigint, (select s.categoria_padrao_id from imobdesk.ch_servicos s where s.id = v_servico), (select c.id from imobdesk.ch_categorias c where c.padrao)),
          coalesce(nullif(p ->> 'urgenciaId', '')::bigint, (select s.urgencia_padrao_id from imobdesk.ch_servicos s where s.id = v_servico), (select u.id from imobdesk.ch_urgencias u where u.padrao)),
          coalesce((select s.id from imobdesk.ch_status s where s.categoria = 'novo' and s.ativo order by s.ordem limit 1), 1),
          nullif(p ->> 'equipeId', '')::bigint, nullif(p ->> 'responsavelId', '')::uuid,
          coalesce(array(select jsonb_array_elements_text(p -> 'tags')), '{}'), coalesce(array(select jsonb_array_elements_text(p -> 'cc')), '{}'),
          coalesce(p -> 'campos', '{}'), v_ator)
  returning id into v_id;

  insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_id, autor_nome, texto, envio_status)
  values (v_id, 1, 'publica', 'portal', 'entrada', v_ator, imobdesk.ch_nome_usuario(v_ator), v_texto, 'nao_se_aplica');
  return v_id;
end;
$$;

/**
 * Altera o ticket. Só as chaves enviadas mudam. Resolver ou fechar exige os campos obrigatórios e a
 * "Solução aplicada" (plano de IA, D2). Alterar o prazo à mão: gestor do setor, Admin ou Super admin, com justificativa.
 */
create or replace function imobdesk.ch_ticket_atualizar(p_id bigint, p jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets := imobdesk.ch_ticket_visivel(p_id);
  n imobdesk.ch_tickets;
  v_cat text;
  v_pend text[];
begin
  if t.excluido_em is not null then perform imobdesk.erro('INVALID_INPUT', 'Ticket excluído.'); end if;
  if t.mesclado_em_id is not null then perform imobdesk.erro('INVALID_INPUT', format('Este ticket foi mesclado em #%s.', t.mesclado_em_id)); end if;
  n := t;
  if p ? 'servicoId' then n.servico_id := nullif(p ->> 'servicoId', '')::bigint;
    if n.servico_id is not null then
      n.setor_id := (select s.setor_id from imobdesk.ch_servicos s where s.id = n.servico_id and s.ativo);
      if n.setor_id is null then perform imobdesk.erro('INVALID_INPUT', 'Serviço inválido.', 'servicoId'); end if;
      if not (p ? 'equipeId') then n.equipe_id := null; end if;   -- o gatilho põe a equipe do serviço
    end if;
  end if;
  if p ? 'categoriaId' then n.categoria_id := nullif(p ->> 'categoriaId', '')::bigint; end if;
  if p ? 'urgenciaId' then n.urgencia_id := coalesce(nullif(p ->> 'urgenciaId', '')::bigint, n.urgencia_id); end if;
  if p ? 'equipeId' then n.equipe_id := nullif(p ->> 'equipeId', '')::bigint; end if;
  if p ? 'responsavelId' then n.responsavel_id := nullif(p ->> 'responsavelId', '')::uuid; end if;
  if p ? 'statusId' then n.status_id := (p ->> 'statusId')::bigint; n.justificativa_id := nullif(p ->> 'justificativaId', '')::bigint; end if;
  if p ? 'tags' then n.tags := coalesce(array(select distinct btrim(x) from jsonb_array_elements_text(p -> 'tags') x where btrim(x) <> ''), '{}'); end if;
  if p ? 'cc' then n.cc := coalesce(array(select distinct lower(btrim(x)) from jsonb_array_elements_text(p -> 'cc') x where btrim(x) <> ''), '{}'); end if;
  if p ? 'campos' then n.campos := t.campos || coalesce(p -> 'campos', '{}'); end if;
  if p ? 'assunto' and length(btrim(p ->> 'assunto')) > 0 then n.assunto := btrim(p ->> 'assunto'); end if;
  if p ? 'solucaoAplicada' then n.solucao_aplicada := nullif(btrim(p ->> 'solucaoAplicada'), ''); end if;
  if p ? 'solicitantePessoaId' then
    n.solicitante_pessoa_id := nullif(p ->> 'solicitantePessoaId', '')::bigint;
    select pe.nome into n.solicitante_nome from imobdesk.at_pessoas pe where pe.id = n.solicitante_pessoa_id;
    if n.solicitante_nome is null then perform imobdesk.erro('INVALID_INPUT', 'Solicitante não encontrado.', 'solicitante'); end if;
  end if;
  if p ? 'slaSolucaoAte' then
    if not (imobdesk.ch_eh_admin() or imobdesk.at_gestor_de(t.setor_id)) then
      perform imobdesk.erro('FORBIDDEN', 'Só o gestor do setor, Admin ou Super admin alteram o prazo.');
    end if;
    if length(btrim(coalesce(p ->> 'slaJustificativa', ''))) < 5 then perform imobdesk.erro('INVALID_INPUT', 'Explique por que o prazo mudou.', 'slaJustificativa'); end if;
    n.sla_solucao_ate := (p ->> 'slaSolucaoAte')::timestamptz;
    n.sla_manual := true;
  end if;

  v_cat := (select s.categoria from imobdesk.ch_status s where s.id = n.status_id and s.ativo);
  if v_cat is null then perform imobdesk.erro('INVALID_INPUT', 'Status inválido.', 'statusId'); end if;
  if v_cat in ('resolvido', 'fechado') then
    v_pend := imobdesk.ch_campos_pendentes(n);
    if cardinality(v_pend) > 0 then
      perform imobdesk.erro('INVALID_INPUT', 'Preencha antes de resolver: ' || array_to_string(v_pend, ', ') || '.', 'campos');
    end if;
    if n.servico_id is null then perform imobdesk.erro('INVALID_INPUT', 'Escolha o serviço antes de resolver.', 'servicoId'); end if;
    if n.solucao_aplicada is null then perform imobdesk.erro('INVALID_INPUT', 'Descreva a solução aplicada antes de resolver.', 'solucaoAplicada'); end if;
  end if;

  update imobdesk.ch_tickets set
    servico_id = n.servico_id, setor_id = n.setor_id, categoria_id = n.categoria_id, urgencia_id = n.urgencia_id, equipe_id = n.equipe_id,
    responsavel_id = n.responsavel_id, status_id = n.status_id, justificativa_id = n.justificativa_id, tags = n.tags, cc = n.cc, campos = n.campos,
    assunto = n.assunto, solucao_aplicada = n.solucao_aplicada, solicitante_pessoa_id = n.solicitante_pessoa_id, solicitante_nome = n.solicitante_nome,
    sla_solucao_ate = n.sla_solucao_ate, sla_manual = n.sla_manual
  where id = p_id;

  if p ? 'slaSolucaoAte' then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_id, autor_nome)
    values (p_id, 'sla_justificativa', 'Motivo: ' || btrim(p ->> 'slaJustificativa'), (select auth.uid()), imobdesk.ch_nome_usuario((select auth.uid())));
  end if;
end;
$$;

/**
 * Adiciona uma ação: pública (resposta ao solicitante pelo canal do ticket) ou nota interna. A resposta pública
 * entra como "pendente" de envio; o envio por e-mail e WhatsApp é da Etapa 4 (Edge Functions).
 * Opcional: statusDepois {statusId, justificativaId} e as mesmas chaves de ch_ticket_atualizar em "campos".
 */
create or replace function imobdesk.ch_ticket_acao(p_id bigint, p jsonb)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets := imobdesk.ch_ticket_visivel(p_id);
  v_tipo text := coalesce(p ->> 'tipo', 'publica');
  v_texto text := coalesce(p ->> 'texto', '');
  v_num int;
  v_canal text;
  v_ator uuid := (select auth.uid());
begin
  if t.excluido_em is not null or t.mesclado_em_id is not null then perform imobdesk.erro('INVALID_INPUT', 'Este ticket não recebe mais ações.'); end if;
  if v_tipo not in ('publica', 'interna') then perform imobdesk.erro('INVALID_INPUT', 'Tipo de ação inválido.', 'tipo'); end if;
  if length(btrim(v_texto)) = 0 then perform imobdesk.erro('INVALID_INPUT', 'Escreva o texto da ação.', 'texto'); end if;
  v_canal := case when v_tipo = 'interna' then 'portal' when t.origem in ('email', 'whatsapp') then t.origem else 'portal' end;
  perform 1 from imobdesk.ch_tickets x where x.id = p_id for update;
  v_num := coalesce((select max(a.numero) from imobdesk.ch_ticket_acoes a where a.ticket_id = p_id), 0) + 1;
  insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_id, autor_nome, texto, html, anexos, envio_status)
  values (p_id, v_num, v_tipo, v_canal, 'saida', v_ator, imobdesk.ch_nome_usuario(v_ator), v_texto, p ->> 'html', coalesce(p -> 'anexos', '[]'),
          case when v_tipo = 'publica' and v_canal in ('email', 'whatsapp') then 'pendente' else 'nao_se_aplica' end);
  if v_tipo = 'publica' and t.primeira_resposta_em is null then
    update imobdesk.ch_tickets set primeira_resposta_em = now() where id = p_id;
  end if;
  if jsonb_typeof(p -> 'campos') = 'object' or jsonb_typeof(p -> 'statusDepois') = 'object' then
    perform imobdesk.ch_ticket_atualizar(p_id, coalesce(p -> 'campos', '{}') || coalesce(p -> 'statusDepois', '{}'));
  end if;
  return v_num;
end;
$$;

/** Detalhe completo para a tela do ticket. */
create or replace function imobdesk.ch_ticket_detalhe(p_id bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets := imobdesk.ch_ticket_visivel(p_id);
begin
  return jsonb_build_object(
    'id', t.id, 'assunto', t.assunto, 'origem', t.origem, 'recebidoEm', t.recebido_em,
    'solicitante', jsonb_build_object('pessoaId', t.solicitante_pessoa_id, 'nome', t.solicitante_nome, 'contato', t.solicitante_contato,
       'departamento', (select d.nome from imobdesk.at_pessoa_relacoes r join imobdesk.at_pessoas d on d.id = r.empresa_id and d.tipo = 'departamento'
                        where r.pessoa_id = t.solicitante_pessoa_id limit 1)),
    'setorId', t.setor_id, 'equipeId', t.equipe_id, 'responsavelId', t.responsavel_id, 'servicoId', t.servico_id, 'categoriaId', t.categoria_id,
    'urgenciaId', t.urgencia_id, 'statusId', t.status_id, 'justificativaId', t.justificativa_id, 'tags', to_jsonb(t.tags), 'cc', to_jsonb(t.cc), 'campos', t.campos,
    'solucaoAplicada', t.solucao_aplicada, 'criadoEm', t.criado_em, 'assumidoEm', t.assumido_em, 'primeiraRespostaEm', t.primeira_resposta_em,
    'slaRespostaAte', t.sla_resposta_ate, 'slaSolucaoAte', t.sla_solucao_ate, 'slaManual', t.sla_manual, 'slaPausadoDesde', t.sla_pausado_desde,
    'encerradoEm', t.encerrado_em, 'mescladoEmId', t.mesclado_em_id, 'clonadoDeId', t.clonado_de_id, 'excluidoEm', t.excluido_em,
    'clones', coalesce((select jsonb_agg(c.id order by c.id) from imobdesk.ch_tickets c where c.clonado_de_id = t.id), '[]'),
    'mesclados', coalesce((select jsonb_agg(c.id order by c.id) from imobdesk.ch_tickets c where c.mesclado_em_id = t.id), '[]'),
    'campoEstado', coalesce((select jsonb_object_agg(e.chave, jsonb_build_object('visivel', e.visivel, 'obrigatorio', e.obrigatorio)) from imobdesk.ch_campos_estado(t) e), '{}'),
    'seguindo', exists (select 1 from imobdesk.ch_ticket_seguidores s where s.ticket_id = t.id and s.usuario_id = (select auth.uid())),
    'acoes', coalesce((select jsonb_agg(jsonb_build_object('numero', a.numero, 'tipo', a.tipo, 'canal', a.canal, 'direcao', a.direcao, 'autorId', a.autor_id, 'autorNome', a.autor_nome,
                         'texto', a.texto, 'html', a.html, 'anexos', a.anexos, 'envioStatus', a.envio_status, 'criadoEm', a.criado_em) order by a.numero desc)
                       from imobdesk.ch_ticket_acoes a where a.ticket_id = t.id), '[]'),
    'eventos', coalesce((select jsonb_agg(jsonb_build_object('tipo', e.tipo, 'descricao', e.descricao, 'autorNome', e.autor_nome, 'criadoEm', e.criado_em) order by e.criado_em desc, e.id desc)
                         from imobdesk.ch_ticket_eventos e where e.ticket_id = t.id), '[]'),
    'podeAlterarPrazo', imobdesk.ch_eh_admin() or imobdesk.at_gestor_de(t.setor_id),
    'podeExcluir', imobdesk.eh_super_admin()
  );
end;
$$;

create or replace function imobdesk.ch_ticket_seguir(p_id bigint, p_seguir boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform imobdesk.ch_ticket_visivel(p_id);
  if p_seguir then
    insert into imobdesk.ch_ticket_seguidores (ticket_id, usuario_id) values (p_id, (select auth.uid())) on conflict do nothing;
  else
    delete from imobdesk.ch_ticket_seguidores where ticket_id = p_id and usuario_id = (select auth.uid());
  end if;
end;
$$;

/** Clonar (T6): ticket novo com os campos; opcionalmente as ações. */
create or replace function imobdesk.ch_ticket_clonar(p_id bigint, p jsonb)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets := imobdesk.ch_ticket_visivel(p_id);
  v_novo bigint;
  v_ator uuid := (select auth.uid());
begin
  insert into imobdesk.ch_tickets (assunto, origem, recebido_em, solicitante_pessoa_id, solicitante_nome, solicitante_contato, email_conta_id, setor_id,
                                             servico_id, categoria_id, urgencia_id, status_id, tags, cc, campos, clonado_de_id, criado_por)
  select t.assunto, t.origem, t.recebido_em,
         coalesce(nullif(p ->> 'solicitantePessoaId', '')::bigint, t.solicitante_pessoa_id), t.solicitante_nome, t.solicitante_contato, t.email_conta_id,
         t.setor_id, coalesce(nullif(p ->> 'servicoId', '')::bigint, t.servico_id),
         case when coalesce((p ->> 'copiarCampos')::boolean, true) then t.categoria_id end, t.urgencia_id,
         coalesce((select s.id from imobdesk.ch_status s where s.categoria = 'novo' and s.ativo order by s.ordem limit 1), 1),
         case when coalesce((p ->> 'copiarCampos')::boolean, true) then t.tags else '{}' end, t.cc,
         case when coalesce((p ->> 'copiarCampos')::boolean, true) then t.campos else '{}' end, t.id, v_ator
  returning id into v_novo;
  if nullif(p ->> 'servicoId', '') is not null then
    update imobdesk.ch_tickets n set setor_id = s.setor_id from imobdesk.ch_servicos s where n.id = v_novo and s.id = n.servico_id;
  end if;
  if coalesce((p ->> 'copiarAcoes')::boolean, false) then
    insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_id, autor_nome, texto, html, anexos, envio_status, criado_em)
    select v_novo, a.numero, a.tipo, a.canal, a.direcao, a.autor_id, a.autor_nome, a.texto, a.html, a.anexos, 'nao_se_aplica', a.criado_em
    from imobdesk.ch_ticket_acoes a where a.ticket_id = t.id;
  else
    insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_id, autor_nome, texto, envio_status)
    values (v_novo, 1, 'interna', 'portal', 'saida', v_ator, imobdesk.ch_nome_usuario(v_ator), format('Clonado do ticket #%s.', t.id), 'nao_se_aplica');
  end if;
  insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_id, autor_nome)
  values (t.id, 'clonado', format('Clonado para #%s', v_novo), v_ator, imobdesk.ch_nome_usuario(v_ator));
  return v_novo;
end;
$$;

/** Mesclar (T7): as ações vão para o destino; a origem fica Cancelado com "mesclado em". */
create or replace function imobdesk.ch_ticket_mesclar(p_origem bigint, p_destino bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  o imobdesk.ch_tickets := imobdesk.ch_ticket_visivel(p_origem);
  d imobdesk.ch_tickets := imobdesk.ch_ticket_visivel(p_destino);
  v_base int;
  v_ator uuid := (select auth.uid());
  v_cancelado bigint := (select s.id from imobdesk.ch_status s where s.categoria = 'cancelado' and s.ativo order by s.ordem limit 1);
begin
  if p_origem = p_destino then perform imobdesk.erro('INVALID_INPUT', 'Escolha outro ticket como destino.', 'destino'); end if;
  if o.mesclado_em_id is not null or d.mesclado_em_id is not null or o.excluido_em is not null or d.excluido_em is not null then
    perform imobdesk.erro('INVALID_INPUT', 'Um dos tickets já foi mesclado ou excluído.');
  end if;
  perform 1 from imobdesk.ch_tickets x where x.id in (p_origem, p_destino) order by x.id for update;
  v_base := coalesce((select max(a.numero) from imobdesk.ch_ticket_acoes a where a.ticket_id = p_destino), 0);
  update imobdesk.ch_ticket_acoes a set ticket_id = p_destino, numero = v_base + a.numero where a.ticket_id = p_origem;
  update imobdesk.ch_tickets set cc = (select coalesce(array_agg(distinct x), '{}') from unnest(d.cc || o.cc ||
           case when o.solicitante_contato is not null and o.solicitante_contato is distinct from d.solicitante_contato then array[o.solicitante_contato] else '{}'::text[] end) x)
   where id = p_destino;
  -- Conversas e e-mails que apontavam para a origem passam a cair no destino (Etapa 4 usa estes vínculos).
  update imobdesk.ch_tickets set mesclado_em_id = p_destino, status_id = coalesce(v_cancelado, status_id), justificativa_id = null where id = p_origem;
  insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_id, autor_nome, texto, envio_status)
  values (p_destino, (select max(a.numero) from imobdesk.ch_ticket_acoes a where a.ticket_id = p_destino) + 1,
          'interna', 'portal', 'saida', v_ator, imobdesk.ch_nome_usuario(v_ator), format('Ticket #%s mesclado neste ticket.', p_origem), 'nao_se_aplica');
  insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_id, autor_nome) values
    (p_origem, 'mesclado', format('Mesclado em #%s', p_destino), v_ator, imobdesk.ch_nome_usuario(v_ator)),
    (p_destino, 'mesclado', format('Recebeu as ações de #%s', p_origem), v_ator, imobdesk.ch_nome_usuario(v_ator));
end;
$$;

/** Excluir (T8): só Super admin, exclusão lógica. */
create or replace function imobdesk.ch_ticket_excluir(p_id bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := imobdesk.ch_exigir_super();
begin
  update imobdesk.ch_tickets set excluido_em = now(), excluido_por = v_ator where id = p_id and excluido_em is null;
  if not found then perform imobdesk.erro('NOT_FOUND', 'Ticket não encontrado.'); end if;
  insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_id, autor_nome)
  values (p_id, 'excluido', 'Ticket excluído', v_ator, imobdesk.ch_nome_usuario(v_ator));
  perform imobdesk.registrar_auditoria(v_ator, 'atendimento', 'delete', format('Ticket #%s excluído', p_id), null, null, p_id::text);
end;
$$;

/**
 * Painel (rpc_dashboard): o mesmo formato de src/features/dashboard/types.ts. Tickets visíveis para o usuário:
 * abertos e os encerrados nos últimos 30 dias.
 */
create or replace function imobdesk.ch_painel()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_eu uuid := (select auth.uid());
  v_admin boolean := imobdesk.ch_eh_admin() or imobdesk.at_supervisor();
  v_agora timestamptz := now();
  v_tokens text[] := array['--ds-team-sistemas', '--ds-team-infra', '--ds-ai', '--ds-triage-ai', '--ds-warning', '--ds-success'];
begin
  if not (imobdesk.ch_eh_admin() or imobdesk.tem_permissao('gestao_chamados_visao_geral') or imobdesk.tem_permissao('gestao_chamados_tickets')) then
    perform imobdesk.erro('FORBIDDEN', 'Sem acesso à Gestão de Chamados.');
  end if;
  return (
    with vis as (
      select t.* from imobdesk.ch_tickets t
      where t.excluido_em is null and t.mesclado_em_id is null
        and (t.encerrado_em is null or t.encerrado_em >= v_agora - interval '30 days')
        and imobdesk.ch_pode_ver_ticket(t.setor_id, t.equipe_id, t.responsavel_id)
    ), eq as (
      select e.id, e.nome, row_number() over (order by e.nome) as n from imobdesk.at_equipes e where e.ativa
    )
    select jsonb_build_object(
      'generated_at', v_agora,
      'current_user', jsonb_build_object('id', v_eu, 'name', imobdesk.ch_nome_usuario(v_eu),
                        'initials', imobdesk.ch_iniciais(imobdesk.ch_nome_usuario(v_eu))),
      'my_teams', coalesce((select jsonb_agg(e.nome order by e.nome) from eq e
                            where v_admin or exists (select 1 from imobdesk.at_equipe_membros m where m.equipe_id = e.id and m.usuario_id = v_eu)), '[]'),
      'teams', coalesce((select jsonb_agg(jsonb_build_object('name', e.nome, 'color_token', v_tokens[1 + ((e.n - 1) % 6)]) order by e.nome) from eq e), '[]'),
      'services', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'name', s.nome,
                              'team', coalesce((select e.nome from imobdesk.at_equipes e where e.id = imobdesk.ch_servico_equipe(s.id)), ''),
                              'sla_hours', coalesce((select h.solucao from imobdesk.ch_sla_horas(s.id, (select u.id from imobdesk.ch_urgencias u where u.padrao), s.setor_id) h), 0)) order by s.nome)
                            from imobdesk.ch_servicos s where s.ativo and not exists (select 1 from imobdesk.ch_servicos f where f.pai_id = s.id)), '[]'),
      'tickets', coalesce((select jsonb_agg(jsonb_build_object(
          'id', t.id, 'subject', t.assunto, 'requester', t.solicitante_nome,
          'description', coalesce((select a.texto from imobdesk.ch_ticket_acoes a where a.ticket_id = t.id order by a.numero limit 1), ''),
          'service_id', t.servico_id,
          'team', coalesce((select e.nome from imobdesk.at_equipes e where e.id = t.equipe_id), ''),
          'origin', case t.origem when 'email' then 'E-mail' when 'whatsapp' then 'WhatsApp' when 'intranet' then 'Intranet' else 'Agente' end,
          'owner', case when t.responsavel_id is null then null else jsonb_build_object('id', t.responsavel_id, 'name', imobdesk.ch_nome_usuario(t.responsavel_id),
                     'initials', imobdesk.ch_iniciais(imobdesk.ch_nome_usuario(t.responsavel_id))) end,
          'status_id', t.status_id, 'status', st.nome, 'status_categoria', st.categoria,
          'justificativa_id', t.justificativa_id, 'justificativa', (select j.nome from imobdesk.ch_status_justificativas j where j.id = t.justificativa_id),
          'prioridade', (select u.nome from imobdesk.ch_urgencias u where u.id = t.urgencia_id),
          'tags', to_jsonb(t.tags), 'recebido_em', t.recebido_em, 'criado_em', t.criado_em,
          'sla_due_minutes', coalesce(round(extract(epoch from (t.sla_solucao_ate - coalesce(t.sla_pausado_desde, v_agora))) / 60), 0),
          'opened_today', (t.criado_em at time zone 'America/Sao_Paulo')::date = (v_agora at time zone 'America/Sao_Paulo')::date,
          'closed_at', t.encerrado_em) order by t.id)
        from vis t join imobdesk.ch_status st on st.id = t.status_id), '[]'),
      'triage', jsonb_build_object('period', 'Hoje', 'automatic', 0, 'total',
                  (select count(*) from vis t where (t.criado_em at time zone 'America/Sao_Paulo')::date = (v_agora at time zone 'America/Sao_Paulo')::date),
                  'by_intranet_form', 0, 'by_email_rule', 0, 'by_ai', 0, 'manual', 0, 'pending_review', 0),
      'sla_health', jsonb_build_object('period', '7 dias',
                  'first_response_percent', coalesce((select round(100.0 * count(*) filter (where t.primeira_resposta_em <= t.sla_resposta_ate) / nullif(count(*), 0))
                                                      from vis t where t.primeira_resposta_em >= v_agora - interval '7 days'), 100),
                  'resolution_percent', coalesce((select round(100.0 * count(*) filter (where t.encerrado_em <= t.sla_solucao_ate) / nullif(count(*), 0))
                                                  from vis t join imobdesk.ch_status st on st.id = t.status_id
                                                  where st.categoria in ('resolvido', 'fechado') and t.encerrado_em >= v_agora - interval '7 days'), 100)),
      'inbound', (select jsonb_agg(jsonb_build_object('hour', h,
                     'today', (select count(*) from vis t where (t.criado_em at time zone 'America/Sao_Paulo')::date = (v_agora at time zone 'America/Sao_Paulo')::date
                                 and extract(hour from t.criado_em at time zone 'America/Sao_Paulo') = h),
                     'yesterday', (select count(*) from vis t where (t.criado_em at time zone 'America/Sao_Paulo')::date = (v_agora at time zone 'America/Sao_Paulo')::date - 1
                                 and extract(hour from t.criado_em at time zone 'America/Sao_Paulo') = h)) order by h)
                  from generate_series(8, 18) h)
    )
  );
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'ch_somar_horas_uteis(bigint, timestamptz, numeric)', 'ch_sla_horas(bigint, bigint, bigint)', 'ch_servico_equipe(bigint)',
    'ch_pode_ver_ticket(bigint, bigint, uuid)', 'ch_ticket_visivel(bigint)', 'ch_regra_condicao(imobdesk.ch_tickets, jsonb)',
    'ch_campos_estado(imobdesk.ch_tickets)', 'ch_campos_pendentes(imobdesk.ch_tickets)', 'ch_nome_usuario(uuid)', 'ch_iniciais(text)',
    'ch_ticket_criar(jsonb)', 'ch_ticket_atualizar(bigint, jsonb)', 'ch_ticket_acao(bigint, jsonb)', 'ch_ticket_detalhe(bigint)', 'ch_ticket_seguir(bigint, boolean)',
    'ch_ticket_clonar(bigint, jsonb)', 'ch_ticket_mesclar(bigint, bigint)', 'ch_ticket_excluir(bigint)', 'ch_painel()'
  ] loop
    execute format('revoke execute on function imobdesk.%s from public, anon', f);
    execute format('grant execute on function imobdesk.%s to authenticated, service_role', f);
  end loop;
end;
$$;

notify pgrst, 'reload schema';

-- ======================================== 20261007190000_imobdesk_ticket_tela.sql
-- Tela do ticket (docs/PLANO-tela-ticket.md, aprovado em 07/10/2026). Só aditiva: duas leituras que a tela usa.
--   ch_ticket_solucoes(p_id): a última solução dada a uma demanda parecida (mesmo serviço; sem serviço, mesma
--     equipe e setor), para o agente usar ou não (T4). Sem IA: a IA melhora a escolha depois (plano de IA).
--   ch_responsaveis(): quem pode ser responsável (membros de equipes ativas), para o seletor "Equipe › Pessoa".

create or replace function imobdesk.ch_ticket_solucoes(p_id bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets := imobdesk.ch_ticket_visivel(p_id);
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', q.id, 'assunto', q.assunto, 'solucao', q.solucao_aplicada, 'encerradoEm', q.encerrado_em,
                                        'responsavel', q.responsavel, 'servico', q.servico) order by q.encerrado_em desc)
    from (
      select x.id, x.assunto, x.solucao_aplicada, x.encerrado_em,
             imobdesk.ch_nome_usuario(x.responsavel_id) as responsavel,
             (select s.nome from imobdesk.ch_servicos s where s.id = x.servico_id) as servico
      from imobdesk.ch_tickets x
      join imobdesk.ch_status st on st.id = x.status_id
      where x.id <> t.id and x.excluido_em is null and x.mesclado_em_id is null
        and x.solucao_aplicada is not null and st.categoria in ('resolvido', 'fechado')
        and ((t.servico_id is not null and x.servico_id = t.servico_id)
             or (t.servico_id is null and x.setor_id = t.setor_id and x.equipe_id is not distinct from t.equipe_id))
      order by x.encerrado_em desc
      limit 3
    ) q
  ), '[]'::jsonb);
end;
$$;

create or replace function imobdesk.ch_responsaveis()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not imobdesk.ch_pode_ler() then
    perform imobdesk.erro('FORBIDDEN', 'Sem acesso à Gestão de Chamados.');
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', u.id, 'nome', u.nome, 'equipes', q.equipes) order by u.nome)
    from (
      select m.usuario_id, jsonb_agg(m.equipe_id order by m.equipe_id) as equipes
      from imobdesk.at_equipe_membros m
      join imobdesk.at_equipes e on e.id = m.equipe_id and e.ativa
      group by m.usuario_id
    ) q
    join imobdesk.usuarios u on u.id = q.usuario_id and u.status = 'active'
  ), '[]'::jsonb);
end;
$$;

revoke execute on function imobdesk.ch_ticket_solucoes(bigint), imobdesk.ch_responsaveis() from public, anon;
grant execute on function imobdesk.ch_ticket_solucoes(bigint), imobdesk.ch_responsaveis() to authenticated, service_role;

notify pgrst, 'reload schema';

-- ======================================== 20261007210000_imobdesk_gatilhos.sql
-- Administração › Gatilhos (docs/PLANO-gatilhos.md, aprovado em 07/10/2026): automações do ticket por disparo,
-- condições TODAS/QUALQUER e ações, como na Movidesk. Só aditiva.
--
-- Como roda:
--   1. Triggers de linha em ch_tickets e ch_ticket_acoes só ANOTAM o que aconteceu em ch_gatilho_fila.
--   2. Um constraint trigger ADIADO (fim da transação) junta as anotações do ticket e roda os gatilhos uma vez
--      por operação, na ordem da lista, vendo o ticket já com tudo o que o agente salvou.
--   3. Enquanto um gatilho age, a variável de sessão imobdesk.gatilho fica com o nome dele: os triggers
--      não anotam nada (ação de gatilho não dispara gatilho, G2) e o histórico mostra "Gatilho: <nome>".
--   4. Gatilhos de tempo (tempo no status, SLA) rodam pelo pg_cron a cada 5 min (G3).
--   5. Erro de um gatilho fica em ch_gatilho_execucoes e no histórico; nunca desfaz a ação do agente.

-- ---------- Tabelas ----------
create table if not exists imobdesk.ch_gatilhos (
  id             bigint      generated by default as identity primary key,
  nome           text        not null check (length(btrim(nome)) between 2 and 80),
  para           text        not null default 'tickets' check (para in ('tickets')),
  disparos       jsonb       not null default '[]',   -- [{tipo, horas?}]
  todas          jsonb       not null default '[]',   -- [{campo, operador, valores}]
  qualquer       jsonb       not null default '[]',
  acoes          jsonb       not null default '[]',   -- [{tipo, ...valor}]
  execucao       text        not null default 'evento' check (execucao in ('evento', 'ticket')),
  ordem          int         not null default 0,
  ativo          boolean     not null default true,
  atualizado_em  timestamptz not null default now(),
  atualizado_por uuid
);

create table if not exists imobdesk.ch_gatilho_execucoes (
  id         bigint      generated always as identity primary key,
  gatilho_id bigint      not null references imobdesk.ch_gatilhos (id) on delete cascade,
  ticket_id  bigint      not null references imobdesk.ch_tickets (id) on delete cascade,
  chave      text        not null,                 -- evita repetir: 'ev:<fila>', 'ticket', 'tempo:<entrada>', 'slavence:<prazo>'...
  disparo    text        not null,
  resultado  text        not null check (resultado in ('executado', 'erro')),
  detalhe    text,
  criado_em  timestamptz not null default now(),
  unique (gatilho_id, ticket_id, chave)
);
create index if not exists ch_gatilho_execucoes_quando_idx on imobdesk.ch_gatilho_execucoes (criado_em desc);

create table if not exists imobdesk.ch_gatilho_fila (
  id        bigint      generated always as identity primary key,
  ticket_id bigint      not null,
  disparo   text        not null,
  txid      bigint      not null default txid_current(),
  criado_em timestamptz not null default now()
);
create index if not exists ch_gatilho_fila_idx on imobdesk.ch_gatilho_fila (ticket_id, txid);

-- Avisos do sino do portal (G4).
create table if not exists imobdesk.ch_notificacoes (
  id         bigint      generated always as identity primary key,
  usuario_id uuid        not null references imobdesk.usuarios (id) on delete cascade,
  ticket_id  bigint      references imobdesk.ch_tickets (id) on delete cascade,
  titulo     text        not null,
  texto      text        not null default '',
  lida_em    timestamptz,
  criado_em  timestamptz not null default now()
);
create index if not exists ch_notificacoes_usuario_idx on imobdesk.ch_notificacoes (usuario_id, criado_em desc);

do $$
declare
  t text;
begin
  foreach t in array array['ch_gatilhos', 'ch_gatilho_execucoes', 'ch_gatilho_fila', 'ch_notificacoes'] loop
    execute format('alter table imobdesk.%I enable row level security', t);
    execute format('revoke all on imobdesk.%I from anon, public, authenticated', t);
    execute format('grant all on imobdesk.%I to service_role', t);
  end loop;
end;
$$;

-- ---------- Avaliação ----------
/** O setor está no expediente agora? Sem horário cadastrado = sempre. */
create or replace function imobdesk.ch_dentro_expediente(p_setor bigint, p_quando timestamptz)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when not exists (select 1 from imobdesk.at_horarios x where x.setor_id = p_setor and x.aberto) then true
    else exists (select 1 from imobdesk.at_horarios x
                 where x.setor_id = p_setor and x.aberto
                   and x.dia = extract(dow from (p_quando at time zone 'America/Sao_Paulo'))::int
                   and (p_quando at time zone 'America/Sao_Paulo')::time >= x.abre
                   and (p_quando at time zone 'America/Sao_Paulo')::time < x.fecha) end;
$$;

/**
 * Uma condição de gatilho. Campos: status ("id" ou "id:justificativa"), urgencia, categoria, servico (vale o nó e os
 * de dentro), equipe, responsavel, setor, origem, tags, texto (assunto e conversa), campo:<chave>, horario
 * ("dentro"/"fora" do expediente) e autor (quem fez: solicitante, agente, sistema).
 */
create or replace function imobdesk.ch_gatilho_condicao(t imobdesk.ch_tickets, c jsonb, p_autor text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_campo text := c ->> 'campo';
  v_op text := c ->> 'operador';
  v_valores text[] := array(select jsonb_array_elements_text(coalesce(c -> 'valores', '[]')));
  v_atual text[];
begin
  if v_campo in ('servico', 'categoria', 'urgencia', 'setor', 'origem') or v_campo like 'campo:%' then
    if v_op in ('um_de', 'nao_um_de', 'preenchido', 'vazio') then
      return imobdesk.ch_regra_condicao(t, c);
    end if;
  end if;
  v_atual := case v_campo
    when 'status' then array[t.status_id::text, t.status_id::text || ':' || coalesce(t.justificativa_id::text, '')]
    when 'equipe' then array_remove(array[t.equipe_id::text], null)
    when 'responsavel' then array_remove(array[t.responsavel_id::text], null)
    when 'tags' then t.tags
    when 'texto' then array[t.assunto] || array(select a.texto from imobdesk.ch_ticket_acoes a where a.ticket_id = t.id order by a.numero desc limit 3)
    when 'horario' then array[case when imobdesk.ch_dentro_expediente(t.setor_id, now()) then 'dentro' else 'fora' end]
    when 'autor' then array[coalesce(p_autor, 'agente')]
    when 'servico' then array_remove(array[t.servico_id::text], null)
    when 'categoria' then array_remove(array[t.categoria_id::text], null)
    when 'urgencia' then array[t.urgencia_id::text]
    when 'setor' then array[t.setor_id::text]
    when 'origem' then array[t.origem]
    else case when v_campo like 'campo:%' then array_remove(array[nullif(btrim(t.campos ->> substr(v_campo, 7)), '')], null) end
  end;
  if v_atual is null then return false; end if;
  return case v_op
    when 'um_de' then v_atual && v_valores
    when 'nao_um_de' then not (v_atual && v_valores)
    when 'preenchido' then cardinality(v_atual) > 0
    when 'vazio' then cardinality(v_atual) = 0
    when 'contem' then exists (select 1 from unnest(v_atual) a, unnest(v_valores) v where v <> '' and a ilike '%' || v || '%')
    when 'nao_contem' then not exists (select 1 from unnest(v_atual) a, unnest(v_valores) v where v <> '' and a ilike '%' || v || '%')
    else false end;
end;
$$;

/** TODAS valem e (QUALQUER vazia ou pelo menos uma vale). */
create or replace function imobdesk.ch_gatilho_atende(t imobdesk.ch_tickets, p_todas jsonb, p_qualquer jsonb, p_autor text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select not exists (select 1 from jsonb_array_elements(coalesce(p_todas, '[]')) c where not imobdesk.ch_gatilho_condicao(t, c, p_autor))
     and (jsonb_array_length(coalesce(p_qualquer, '[]')) = 0
          or exists (select 1 from jsonb_array_elements(p_qualquer) c where imobdesk.ch_gatilho_condicao(t, c, p_autor)));
$$;

-- ---------- Ações ----------
/** Avisa no sino do portal. */
create or replace function imobdesk.ch_notificar(p_usuarios uuid[], p_ticket bigint, p_titulo text, p_texto text)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_n int;
begin
  insert into imobdesk.ch_notificacoes (usuario_id, ticket_id, titulo, texto)
  select distinct u, p_ticket, p_titulo, coalesce(p_texto, '')
    from unnest(p_usuarios) u
   where u is not null and exists (select 1 from imobdesk.usuarios x where x.id = u);
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;

/**
 * Aplica as ações do gatilho no ticket e devolve o resumo. Resolver ou fechar segue as mesmas regras do agente
 * (serviço, obrigatórios e solução aplicada); se faltar, levanta erro e a execução fica como "erro".
 */
create or replace function imobdesk.ch_gatilho_aplicar(p_ticket bigint, g imobdesk.ch_gatilhos)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets;
  n imobdesk.ch_tickets;
  a jsonb;
  v_feito text[] := '{}';
  v_cat text;
  v_pend text[];
  v_lider uuid;
  v_texto text;
  v_canal text;
  v_num int;
  v_quem uuid[];
begin
  select * into t from imobdesk.ch_tickets x where x.id = p_ticket for update;
  n := t;
  for a in select * from jsonb_array_elements(g.acoes) loop
    v_lider := (select e.lider_id from imobdesk.at_equipes e where e.id = n.equipe_id);
    case a ->> 'tipo'
      when 'status' then
        n.status_id := (a ->> 'statusId')::bigint;
        n.justificativa_id := nullif(a ->> 'justificativaId', '')::bigint;
        v_feito := array_append(v_feito, ('status → ' || coalesce((select s.nome from imobdesk.ch_status s where s.id = n.status_id), '?'))::text);
      when 'equipe' then
        n.equipe_id := nullif(a ->> 'equipeId', '')::bigint;
        v_feito := array_append(v_feito, ('equipe → ' || coalesce((select e.nome from imobdesk.at_equipes e where e.id = n.equipe_id), 'nenhuma'))::text);
      when 'responsavel' then
        n.responsavel_id := case a ->> 'modo'
          when 'pessoa' then nullif(a ->> 'usuarioId', '')::uuid
          when 'lider' then v_lider
          else null end;
        v_feito := array_append(v_feito, ('responsável → ' || coalesce((select u.nome from imobdesk.usuarios u where u.id = n.responsavel_id), 'ninguém'))::text);
      when 'urgencia' then
        n.urgencia_id := coalesce(nullif(a ->> 'urgenciaId', '')::bigint, n.urgencia_id);
        v_feito := array_append(v_feito, ('urgência → ' || (select u.nome from imobdesk.ch_urgencias u where u.id = n.urgencia_id))::text);
      when 'categoria' then
        n.categoria_id := nullif(a ->> 'categoriaId', '')::bigint;
        v_feito := array_append(v_feito, ('categoria → ' || coalesce((select c.nome from imobdesk.ch_categorias c where c.id = n.categoria_id), 'nenhuma'))::text);
      when 'servico' then
        n.servico_id := nullif(a ->> 'servicoId', '')::bigint;
        if n.servico_id is not null then
          n.setor_id := coalesce((select s.setor_id from imobdesk.ch_servicos s where s.id = n.servico_id and s.ativo), n.setor_id);
          n.equipe_id := null;   -- o trigger põe a equipe do serviço
        end if;
        v_feito := array_append(v_feito, ('serviço → ' || coalesce((select s.nome from imobdesk.ch_servicos s where s.id = n.servico_id), 'nenhum'))::text);
      when 'tags_adicionar' then
        n.tags := array(select distinct x from unnest(n.tags || array(select btrim(y) from jsonb_array_elements_text(coalesce(a -> 'tags', '[]')) y where btrim(y) <> '')) x);
        v_feito := array_append(v_feito, 'tags adicionadas'::text);
      when 'tags_remover' then
        n.tags := array(select x from unnest(n.tags) x where not x = any (array(select btrim(y) from jsonb_array_elements_text(coalesce(a -> 'tags', '[]')) y)));
        v_feito := array_append(v_feito, 'tags removidas'::text);
      when 'campo' then
        n.campos := n.campos || jsonb_build_object(a ->> 'chave', a -> 'valor');
        v_feito := array_append(v_feito, ('campo ' || (a ->> 'chave'))::text);
      when 'solucao' then
        if n.solucao_aplicada is null then
          n.solucao_aplicada := nullif(btrim(a ->> 'texto'), '');
          v_feito := array_append(v_feito, 'solução aplicada preenchida'::text);
        end if;
      when 'nota_interna' then
        v_num := coalesce((select max(x.numero) from imobdesk.ch_ticket_acoes x where x.ticket_id = p_ticket), 0) + 1;
        insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_nome, texto, envio_status)
        values (p_ticket, v_num, 'interna', 'portal', 'saida', 'Gatilho: ' || g.nome, coalesce(nullif(btrim(a ->> 'texto'), ''), g.nome), 'nao_se_aplica');
        v_feito := array_append(v_feito, 'nota interna'::text);
      when 'responder_macro' then
        select m.texto into v_texto from imobdesk.ch_macros m where m.id = nullif(a ->> 'macroId', '')::bigint and m.ativa;
        if v_texto is null then perform imobdesk.erro('INVALID_INPUT', 'A macro da resposta não existe ou está inativa.'); end if;
        v_texto := replace(replace(replace(v_texto,
                     '{{solicitante.nome}}', split_part(btrim(n.solicitante_nome), ' ', 1)),
                     '{{ticket.numero}}', n.id::text),
                     '{{agente.nome}}', coalesce((select u.nome from imobdesk.usuarios u where u.id = n.responsavel_id), 'Equipe de atendimento'));
        v_canal := case when n.origem in ('email', 'whatsapp') then n.origem else 'portal' end;
        v_num := coalesce((select max(x.numero) from imobdesk.ch_ticket_acoes x where x.ticket_id = p_ticket), 0) + 1;
        insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_nome, texto, envio_status)
        values (p_ticket, v_num, 'publica', v_canal, 'saida', 'Gatilho: ' || g.nome, v_texto, case when v_canal in ('email', 'whatsapp') then 'pendente' else 'nao_se_aplica' end);
        if n.primeira_resposta_em is null then n.primeira_resposta_em := now(); end if;
        v_feito := array_append(v_feito, 'resposta ao solicitante'::text);
      when 'seguidor' then
        insert into imobdesk.ch_ticket_seguidores (ticket_id, usuario_id)
        select p_ticket, u from (select case a ->> 'modo' when 'lider' then v_lider when 'responsavel' then n.responsavel_id else nullif(a ->> 'usuarioId', '')::uuid end u) s
         where u is not null
        on conflict do nothing;
        v_feito := array_append(v_feito, 'seguidor'::text);
      when 'avisar' then
        v_quem := case a ->> 'quem'
          when 'responsavel' then array[n.responsavel_id]
          when 'lider' then array[v_lider]
          when 'seguidores' then array(select s.usuario_id from imobdesk.ch_ticket_seguidores s where s.ticket_id = p_ticket)
          when 'equipe' then array(select m.usuario_id from imobdesk.at_equipe_membros m where m.equipe_id = n.equipe_id)
          when 'pessoa' then array[nullif(a ->> 'usuarioId', '')::uuid]
          else '{}'::uuid[] end;
        perform imobdesk.ch_notificar(v_quem, p_ticket, format('Ticket #%s: %s', n.id, n.assunto), coalesce(nullif(btrim(a ->> 'texto'), ''), g.nome));
        v_feito := array_append(v_feito, ('aviso (' || coalesce(a ->> 'quem', '?') || ')')::text);
      else
        perform imobdesk.erro('INVALID_INPUT', format('Ação desconhecida: %s', a ->> 'tipo'));
    end case;
  end loop;

  v_cat := (select s.categoria from imobdesk.ch_status s where s.id = n.status_id and s.ativo);
  if v_cat is null then perform imobdesk.erro('INVALID_INPUT', 'Status do gatilho inválido ou inativo.'); end if;
  if v_cat in ('resolvido', 'fechado') and t.status_id is distinct from n.status_id then
    v_pend := imobdesk.ch_campos_pendentes(n);
    if cardinality(v_pend) > 0 then perform imobdesk.erro('INVALID_INPUT', 'Para resolver falta: ' || array_to_string(v_pend, ', ') || '.'); end if;
    if n.servico_id is null then perform imobdesk.erro('INVALID_INPUT', 'Para resolver falta o serviço.'); end if;
    if n.solucao_aplicada is null then perform imobdesk.erro('INVALID_INPUT', 'Para resolver falta a "Solução aplicada".'); end if;
  end if;

  update imobdesk.ch_tickets set
    servico_id = n.servico_id, setor_id = n.setor_id, categoria_id = n.categoria_id, urgencia_id = n.urgencia_id, equipe_id = n.equipe_id,
    responsavel_id = n.responsavel_id, status_id = n.status_id, justificativa_id = n.justificativa_id, tags = n.tags, campos = n.campos,
    solucao_aplicada = n.solucao_aplicada, primeira_resposta_em = n.primeira_resposta_em
  where id = p_ticket
    and (servico_id, setor_id, categoria_id, urgencia_id, equipe_id, responsavel_id, status_id, justificativa_id, tags, campos, solucao_aplicada, primeira_resposta_em)
        is distinct from (n.servico_id, n.setor_id, n.categoria_id, n.urgencia_id, n.equipe_id, n.responsavel_id, n.status_id, n.justificativa_id, n.tags, n.campos, n.solucao_aplicada, n.primeira_resposta_em);

  return array_to_string(v_feito, '; ');
end;
$$;

/** Executa um gatilho num ticket, se as condições valem e a chave ainda não rodou. Devolve true se executou. */
create or replace function imobdesk.ch_gatilho_executar(g imobdesk.ch_gatilhos, p_ticket bigint, p_chave text, p_disparo text, p_autor text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets;
  v_chave text := case when g.execucao = 'ticket' then 'ticket' else p_chave end;
  v_res text;
begin
  select * into t from imobdesk.ch_tickets x where x.id = p_ticket;
  if t.id is null or t.excluido_em is not null or t.mesclado_em_id is not null then return false; end if;
  if not imobdesk.ch_gatilho_atende(t, g.todas, g.qualquer, p_autor) then return false; end if;
  if exists (select 1 from imobdesk.ch_gatilho_execucoes e where e.gatilho_id = g.id and e.ticket_id = p_ticket and e.chave = v_chave) then return false; end if;
  begin
    perform set_config('imobdesk.gatilho', g.nome, true);
    v_res := imobdesk.ch_gatilho_aplicar(p_ticket, g);
    perform set_config('imobdesk.gatilho', '', true);
    insert into imobdesk.ch_gatilho_execucoes (gatilho_id, ticket_id, chave, disparo, resultado, detalhe)
    values (g.id, p_ticket, v_chave, p_disparo, 'executado', v_res);
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_nome)
    values (p_ticket, 'gatilho', format('Gatilho "%s": %s', g.nome, coalesce(nullif(v_res, ''), 'executado')), 'Gatilho');
    return true;
  exception when others then
    perform set_config('imobdesk.gatilho', '', true);
    insert into imobdesk.ch_gatilho_execucoes (gatilho_id, ticket_id, chave, disparo, resultado, detalhe)
    values (g.id, p_ticket, v_chave, p_disparo, 'erro', sqlerrm);
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_nome)
    values (p_ticket, 'gatilho_erro', format('Gatilho "%s" não executou: %s', g.nome, sqlerrm), 'Gatilho');
    return false;
  end;
end;
$$;

/** Roda, na ordem da lista, os gatilhos ativos que têm algum dos disparos. */
create or replace function imobdesk.ch_gatilhos_rodar(p_ticket bigint, p_disparos text[], p_chave text, p_autor text)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  g imobdesk.ch_gatilhos;
  v_n int := 0;
begin
  for g in select * from imobdesk.ch_gatilhos x
            where x.ativo and exists (select 1 from jsonb_array_elements(x.disparos) d where d ->> 'tipo' = any (p_disparos))
            order by x.ordem, x.id loop
    if imobdesk.ch_gatilho_executar(g, p_ticket, p_chave,
         (select d ->> 'tipo' from jsonb_array_elements(g.disparos) d where d ->> 'tipo' = any (p_disparos) limit 1), p_autor) then
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end;
$$;

-- ---------- Disparos por evento ----------
create or replace function imobdesk.ch_gatilho_em_execucao()
returns boolean
language sql
stable
set search_path = ''
as $$
  select coalesce(current_setting('imobdesk.gatilho', true), '') <> '';
$$;

create or replace function imobdesk.ch_tickets_gatilho_anotar()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if imobdesk.ch_gatilho_em_execucao() then return null; end if;
  if tg_op = 'INSERT' then
    insert into imobdesk.ch_gatilho_fila (ticket_id, disparo) values (new.id, 'criado');
    return null;
  end if;
  if (new.status_id, new.justificativa_id, new.equipe_id, new.responsavel_id, new.servico_id, new.categoria_id, new.urgencia_id, new.tags, new.cc,
      new.campos, new.assunto, new.solucao_aplicada, new.sla_solucao_ate, new.solicitante_pessoa_id)
     is distinct from
     (old.status_id, old.justificativa_id, old.equipe_id, old.responsavel_id, old.servico_id, old.categoria_id, old.urgencia_id, old.tags, old.cc,
      old.campos, old.assunto, old.solucao_aplicada, old.sla_solucao_ate, old.solicitante_pessoa_id) then
    insert into imobdesk.ch_gatilho_fila (ticket_id, disparo) values (new.id, 'alterado');
  end if;
  if new.status_id is distinct from old.status_id or new.justificativa_id is distinct from old.justificativa_id then
    insert into imobdesk.ch_gatilho_fila (ticket_id, disparo) values (new.id, 'status');
  end if;
  return null;
end;
$$;

drop trigger if exists ch_tickets_gatilho_anotar on imobdesk.ch_tickets;
create trigger ch_tickets_gatilho_anotar after insert or update on imobdesk.ch_tickets
for each row execute function imobdesk.ch_tickets_gatilho_anotar();

create or replace function imobdesk.ch_acoes_gatilho_anotar()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- A ação nº 1 é a abertura (já coberta por "criado").
  if imobdesk.ch_gatilho_em_execucao() or new.numero = 1 then return null; end if;
  insert into imobdesk.ch_gatilho_fila (ticket_id, disparo)
  values (new.ticket_id, case when new.direcao = 'entrada' then 'acao_solicitante' else 'acao_agente' end);
  return null;
end;
$$;

drop trigger if exists ch_acoes_gatilho_anotar on imobdesk.ch_ticket_acoes;
create trigger ch_acoes_gatilho_anotar after insert on imobdesk.ch_ticket_acoes
for each row execute function imobdesk.ch_acoes_gatilho_anotar();

/** No fim da transação: junta as anotações do ticket e roda os gatilhos uma vez. */
create or replace function imobdesk.ch_gatilho_fila_processar()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_disp text[];
  v_min bigint;
begin
  with apagados as (
    delete from imobdesk.ch_gatilho_fila f where f.ticket_id = new.ticket_id and f.txid = new.txid returning f.id, f.disparo)
  select array_agg(distinct a.disparo), min(a.id) into v_disp, v_min from apagados a;
  if v_disp is null then return null; end if;
  perform imobdesk.ch_gatilhos_rodar(new.ticket_id, v_disp, 'ev:' || v_min,
            case when 'acao_solicitante' = any (v_disp) then 'solicitante' else 'agente' end);
  return null;
end;
$$;

drop trigger if exists ch_gatilho_fila_processar on imobdesk.ch_gatilho_fila;
create constraint trigger ch_gatilho_fila_processar after insert on imobdesk.ch_gatilho_fila
deferrable initially deferred
for each row execute function imobdesk.ch_gatilho_fila_processar();

-- Histórico: o que um gatilho muda aparece como "Gatilho: <nome>" (mesma função de antes, só o autor muda).
create or replace function imobdesk.ch_tickets_historico()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_gatilho text := coalesce(current_setting('imobdesk.gatilho', true), '');
  v_autor uuid := case when v_gatilho = '' then (select auth.uid()) end;
  v_nome text := case when v_gatilho = '' then imobdesk.ch_nome_usuario((select auth.uid())) else 'Gatilho: ' || v_gatilho end;
begin
  if tg_op = 'INSERT' then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_id, autor_nome)
    values (new.id, 'criado', format('Ticket criado (%s)', new.origem), v_autor, v_nome);
    return null;
  end if;
  if new.status_id is distinct from old.status_id or new.justificativa_id is distinct from old.justificativa_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'status', 'Status alterado',
            jsonb_build_object('statusId', old.status_id, 'justificativaId', old.justificativa_id), jsonb_build_object('statusId', new.status_id, 'justificativaId', new.justificativa_id), v_autor, v_nome);
  end if;
  if new.responsavel_id is distinct from old.responsavel_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'responsavel', format('Responsável: %s', coalesce((select u.nome from imobdesk.usuarios u where u.id = new.responsavel_id), 'ninguém')),
            to_jsonb(old.responsavel_id), to_jsonb(new.responsavel_id), v_autor, v_nome);
  end if;
  if new.equipe_id is distinct from old.equipe_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'equipe', format('Equipe: %s', coalesce((select e.nome from imobdesk.at_equipes e where e.id = new.equipe_id), 'sem equipe')), to_jsonb(old.equipe_id), to_jsonb(new.equipe_id), v_autor, v_nome);
  end if;
  if new.servico_id is distinct from old.servico_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'servico', format('Serviço: %s', coalesce((select s.nome from imobdesk.ch_servicos s where s.id = new.servico_id), '—')), to_jsonb(old.servico_id), to_jsonb(new.servico_id), v_autor, v_nome);
  end if;
  if new.categoria_id is distinct from old.categoria_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'categoria', format('Categoria: %s', coalesce((select c.nome from imobdesk.ch_categorias c where c.id = new.categoria_id), '—')), to_jsonb(old.categoria_id), to_jsonb(new.categoria_id), v_autor, v_nome);
  end if;
  if new.urgencia_id is distinct from old.urgencia_id then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'urgencia', format('Urgência: %s', (select u.nome from imobdesk.ch_urgencias u where u.id = new.urgencia_id)), to_jsonb(old.urgencia_id), to_jsonb(new.urgencia_id), v_autor, v_nome);
  end if;
  if new.campos is distinct from old.campos then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'campos', 'Campos adicionais alterados', old.campos, new.campos, v_autor, v_nome);
  end if;
  if new.tags is distinct from old.tags then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'tags', 'Tags alteradas', to_jsonb(old.tags), to_jsonb(new.tags), v_autor, v_nome);
  end if;
  if new.sla_manual and (new.sla_solucao_ate is distinct from old.sla_solucao_ate) then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, de, para, autor_id, autor_nome)
    values (new.id, 'sla', 'Previsão de solução alterada à mão', to_jsonb(old.sla_solucao_ate), to_jsonb(new.sla_solucao_ate), v_autor, v_nome);
  end if;
  return null;
end;
$$;

-- ---------- Disparos por tempo (G3) ----------
/** Chamado pelo pg_cron a cada 5 min: tempo no status, SLA vence em ≤ N h e SLA vencido. */
create or replace function imobdesk.ch_gatilhos_tempo()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  g imobdesk.ch_gatilhos;
  d jsonb;
  r record;
  v_horas numeric;
  v_n int := 0;
begin
  for g in select * from imobdesk.ch_gatilhos x
            where x.ativo and exists (select 1 from jsonb_array_elements(x.disparos) y where y ->> 'tipo' in ('tempo_status', 'sla_vence', 'sla_vencido'))
            order by x.ordem, x.id loop
    for d in select * from jsonb_array_elements(g.disparos) loop
      v_horas := nullif(d ->> 'horas', '')::numeric;
      if d ->> 'tipo' = 'tempo_status' and v_horas > 0 then
        for r in
          select t.id, coalesce((select max(e.criado_em) from imobdesk.ch_ticket_eventos e where e.ticket_id = t.id and e.tipo = 'status'), t.criado_em) as entrada, t.setor_id
            from imobdesk.ch_tickets t
           where t.encerrado_em is null and t.excluido_em is null and t.mesclado_em_id is null
        loop
          if imobdesk.ch_somar_horas_uteis(r.setor_id, r.entrada, v_horas) <= now() then
            if imobdesk.ch_gatilho_executar(g, r.id, 'tempo:' || extract(epoch from r.entrada)::bigint, 'tempo_status', 'sistema') then v_n := v_n + 1; end if;
          end if;
        end loop;
      elsif d ->> 'tipo' = 'sla_vence' and v_horas > 0 then
        for r in
          select t.id, t.sla_solucao_ate from imobdesk.ch_tickets t
           where t.encerrado_em is null and t.excluido_em is null and t.mesclado_em_id is null and t.sla_pausado_desde is null
             and t.sla_solucao_ate > now() and t.sla_solucao_ate <= now() + make_interval(secs => (v_horas * 3600)::int)
        loop
          if imobdesk.ch_gatilho_executar(g, r.id, 'slavence:' || extract(epoch from r.sla_solucao_ate)::bigint, 'sla_vence', 'sistema') then v_n := v_n + 1; end if;
        end loop;
      elsif d ->> 'tipo' = 'sla_vencido' then
        for r in
          select t.id, t.sla_solucao_ate from imobdesk.ch_tickets t
           where t.encerrado_em is null and t.excluido_em is null and t.mesclado_em_id is null and t.sla_pausado_desde is null
             and t.sla_solucao_ate <= now()
        loop
          if imobdesk.ch_gatilho_executar(g, r.id, 'slavencido:' || extract(epoch from r.sla_solucao_ate)::bigint, 'sla_vencido', 'sistema') then v_n := v_n + 1; end if;
        end loop;
      end if;
    end loop;
  end loop;
  -- Anotações órfãs (transação que caiu) não ficam para sempre.
  delete from imobdesk.ch_gatilho_fila f where f.criado_em < now() - interval '1 hour';
  return v_n;
end;
$$;

-- ---------- RPCs da tela (Admin e Super admin) ----------
create or replace function imobdesk.ch_gatilho_exigir_admin()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not imobdesk.ch_eh_admin() then
    perform imobdesk.erro('FORBIDDEN', 'Só Admin e Super admin acessam os gatilhos.');
  end if;
  return (select auth.uid());
end;
$$;

create or replace function imobdesk.ch_gatilhos_lista()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform imobdesk.ch_gatilho_exigir_admin();
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', g.id, 'nome', g.nome, 'para', g.para, 'disparos', g.disparos, 'todas', g.todas, 'qualquer', g.qualquer, 'acoes', g.acoes,
      'execucao', g.execucao, 'ordem', g.ordem, 'ativo', g.ativo, 'atualizadoEm', g.atualizado_em,
      'atualizadoPor', imobdesk.ch_nome_usuario(g.atualizado_por),
      'execucoes7d', (select count(*) from imobdesk.ch_gatilho_execucoes e where e.gatilho_id = g.id and e.resultado = 'executado' and e.criado_em > now() - interval '7 days'),
      'erros7d', (select count(*) from imobdesk.ch_gatilho_execucoes e where e.gatilho_id = g.id and e.resultado = 'erro' and e.criado_em > now() - interval '7 days'))
      order by g.ordem, g.id)
    from imobdesk.ch_gatilhos g), '[]');
end;
$$;

/** Valida e grava. Precisa de pelo menos um disparo e uma ação (como na Movidesk). */
create or replace function imobdesk.ch_gatilho_salvar(p jsonb)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := imobdesk.ch_gatilho_exigir_admin();
  v_id bigint := nullif(p ->> 'id', '')::bigint;
  v_nome text := btrim(coalesce(p ->> 'nome', ''));
  v_disp jsonb := coalesce(p -> 'disparos', '[]');
  v_todas jsonb := coalesce(p -> 'todas', '[]');
  v_qualquer jsonb := coalesce(p -> 'qualquer', '[]');
  v_acoes jsonb := coalesce(p -> 'acoes', '[]');
  v_campos text[] := array['status', 'urgencia', 'categoria', 'servico', 'equipe', 'responsavel', 'setor', 'origem', 'tags', 'texto', 'horario', 'autor'];
begin
  if length(v_nome) not between 2 and 80 then perform imobdesk.erro('INVALID_INPUT', 'Informe o nome do gatilho (2 a 80 letras).', 'nome'); end if;
  if exists (select 1 from imobdesk.ch_gatilhos g where lower(btrim(g.nome)) = lower(v_nome) and g.id is distinct from v_id) then
    perform imobdesk.erro('DUPLICATE', 'Já existe um gatilho com esse nome.', 'nome');
  end if;
  if jsonb_typeof(v_disp) <> 'array' or jsonb_array_length(v_disp) = 0 then
    perform imobdesk.erro('INVALID_INPUT', 'Marque pelo menos um disparo em "Dispara quando".', 'disparos');
  end if;
  if exists (select 1 from jsonb_array_elements(v_disp) d
             where coalesce(d ->> 'tipo', '') not in ('criado', 'alterado', 'status', 'acao_solicitante', 'acao_agente', 'tempo_status', 'sla_vence', 'sla_vencido')
                or ((d ->> 'tipo') in ('tempo_status', 'sla_vence') and coalesce(nullif(d ->> 'horas', '')::numeric, 0) not between 0.25 and 2000)) then
    perform imobdesk.erro('INVALID_INPUT', 'Revise os disparos: as horas precisam estar entre 0,25 e 2000.', 'disparos');
  end if;
  if jsonb_typeof(v_todas) <> 'array' or jsonb_typeof(v_qualquer) <> 'array'
     or exists (select 1 from jsonb_array_elements(v_todas || v_qualquer) c
                where not ((c ->> 'campo') = any (v_campos) or (c ->> 'campo') like 'campo:%')
                   or coalesce(c ->> 'operador', '') not in ('um_de', 'nao_um_de', 'preenchido', 'vazio', 'contem', 'nao_contem')
                   or ((c ->> 'operador') in ('um_de', 'nao_um_de', 'contem', 'nao_contem') and coalesce(jsonb_array_length(c -> 'valores'), 0) = 0)) then
    perform imobdesk.erro('INVALID_INPUT', 'Revise as condições: campo, operador e valores.', 'condicoes');
  end if;
  if jsonb_typeof(v_acoes) <> 'array' or jsonb_array_length(v_acoes) = 0 then
    perform imobdesk.erro('INVALID_INPUT', 'Adicione pelo menos uma ação.', 'acoes');
  end if;
  if exists (select 1 from jsonb_array_elements(v_acoes) a
             where coalesce(a ->> 'tipo', '') not in ('status', 'equipe', 'responsavel', 'urgencia', 'categoria', 'servico', 'tags_adicionar', 'tags_remover',
                                                       'campo', 'solucao', 'nota_interna', 'responder_macro', 'seguidor', 'avisar')
                or (a ->> 'tipo' = 'status' and not exists (select 1 from imobdesk.ch_status s where s.id = nullif(a ->> 'statusId', '')::bigint))
                or (a ->> 'tipo' = 'responder_macro' and not exists (select 1 from imobdesk.ch_macros m where m.id = nullif(a ->> 'macroId', '')::bigint))
                or (a ->> 'tipo' = 'campo' and not exists (select 1 from imobdesk.ch_campos c where c.chave = a ->> 'chave'))
                or (a ->> 'tipo' in ('nota_interna', 'solucao') and length(btrim(coalesce(a ->> 'texto', ''))) = 0)
                or (a ->> 'tipo' in ('tags_adicionar', 'tags_remover') and coalesce(jsonb_array_length(a -> 'tags'), 0) = 0)) then
    perform imobdesk.erro('INVALID_INPUT', 'Revise as ações: falta o valor de alguma delas.', 'acoes');
  end if;

  if v_id is null then
    insert into imobdesk.ch_gatilhos (nome, disparos, todas, qualquer, acoes, execucao, ativo, ordem, atualizado_por)
    values (v_nome, v_disp, v_todas, v_qualquer, v_acoes, coalesce(nullif(p ->> 'execucao', ''), 'evento'), coalesce((p ->> 'ativo')::boolean, true),
            coalesce((select max(ordem) from imobdesk.ch_gatilhos), 0) + 1, v_ator)
    returning id into v_id;
  else
    update imobdesk.ch_gatilhos set nome = v_nome, disparos = v_disp, todas = v_todas, qualquer = v_qualquer, acoes = v_acoes,
           execucao = coalesce(nullif(p ->> 'execucao', ''), execucao), ativo = coalesce((p ->> 'ativo')::boolean, ativo), atualizado_em = now(), atualizado_por = v_ator
     where id = v_id;
    if not found then perform imobdesk.erro('NOT_FOUND', 'Gatilho não encontrado.'); end if;
  end if;
  perform imobdesk.registrar_auditoria(v_ator, 'atendimento', 'update', format('Gatilho "%s" salvo', v_nome), null, p, v_id::text);
  return v_id;
end;
$$;

create or replace function imobdesk.ch_gatilho_ordenar(p_ids bigint[])
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := imobdesk.ch_gatilho_exigir_admin();
begin
  update imobdesk.ch_gatilhos g set ordem = o.pos, atualizado_em = now(), atualizado_por = v_ator
    from unnest(p_ids) with ordinality o(id, pos) where g.id = o.id;
end;
$$;

/** Simula o gatilho (o que está na tela, salvo ou não) num ticket: ✔/✘ por condição, sem gravar nada. */
create or replace function imobdesk.ch_gatilho_simular(p jsonb, p_ticket bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets;
  v_autor text := coalesce(nullif(p ->> 'autor', ''), 'agente');
begin
  perform imobdesk.ch_gatilho_exigir_admin();
  select * into t from imobdesk.ch_tickets x where x.id = p_ticket and x.excluido_em is null;
  if t.id is null then perform imobdesk.erro('NOT_FOUND', 'Ticket não encontrado.'); end if;
  return jsonb_build_object(
    'ticket', jsonb_build_object('id', t.id, 'assunto', t.assunto),
    'todas', coalesce((select jsonb_agg(jsonb_build_object('condicao', c, 'ok', imobdesk.ch_gatilho_condicao(t, c, v_autor)))
                       from jsonb_array_elements(coalesce(p -> 'todas', '[]')) c), '[]'),
    'qualquer', coalesce((select jsonb_agg(jsonb_build_object('condicao', c, 'ok', imobdesk.ch_gatilho_condicao(t, c, v_autor)))
                          from jsonb_array_elements(coalesce(p -> 'qualquer', '[]')) c), '[]'),
    'executaria', imobdesk.ch_gatilho_atende(t, coalesce(p -> 'todas', '[]'), coalesce(p -> 'qualquer', '[]'), v_autor),
    'jaExecutou', exists (select 1 from imobdesk.ch_gatilho_execucoes e where e.gatilho_id = nullif(p ->> 'id', '')::bigint and e.ticket_id = t.id));
end;
$$;

create or replace function imobdesk.ch_gatilho_execucoes(p_dias int, p_gatilho bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform imobdesk.ch_gatilho_exigir_admin();
  return coalesce((
    select jsonb_agg(x order by (x ->> 'criadoEm') desc) from (
      select jsonb_build_object('id', e.id, 'gatilhoId', e.gatilho_id, 'gatilho', g.nome, 'ticketId', e.ticket_id, 'disparo', e.disparo,
                                'resultado', e.resultado, 'detalhe', e.detalhe, 'criadoEm', e.criado_em) x
        from imobdesk.ch_gatilho_execucoes e join imobdesk.ch_gatilhos g on g.id = e.gatilho_id
       where e.criado_em > now() - make_interval(days => greatest(1, least(coalesce(p_dias, 30), 90)))
         and (p_gatilho is null or e.gatilho_id = p_gatilho)
       order by e.criado_em desc limit 300) s), '[]');
end;
$$;

-- ---------- Avisos (sino) ----------
create or replace function imobdesk.ch_notificacoes_lista()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'naoLidas', (select count(*) from imobdesk.ch_notificacoes n where n.usuario_id = (select auth.uid()) and n.lida_em is null),
    'itens', coalesce((select jsonb_agg(x) from (
       select jsonb_build_object('id', n.id, 'ticketId', n.ticket_id, 'titulo', n.titulo, 'texto', n.texto, 'lida', n.lida_em is not null, 'criadoEm', n.criado_em) x
         from imobdesk.ch_notificacoes n where n.usuario_id = (select auth.uid())
        order by n.criado_em desc limit 30) s), '[]'));
$$;

/** Marca como lidas (todas, se p_ids for nulo). */
create or replace function imobdesk.ch_notificacoes_ler(p_ids bigint[])
returns void
language sql
security definer
set search_path = ''
as $$
  update imobdesk.ch_notificacoes n set lida_em = now()
   where n.usuario_id = (select auth.uid()) and n.lida_em is null and (p_ids is null or n.id = any (p_ids));
$$;

-- ---------- Exemplos (G7: criados inativos para o admin revisar) ----------
insert into imobdesk.ch_macros (nome, texto, acoes, escopo, ativa)
select 'Encerramento por falta de retorno',
       E'Olá, {{solicitante.nome}}.\n\nComo não tivemos retorno, estamos encerrando o ticket #{{ticket.numero}}. Se precisar, é só responder esta mensagem que ele volta a ser atendido.\n\n{{agente.nome}}',
       '{}', 'todos', true
where not exists (select 1 from imobdesk.ch_macros m where m.nome = 'Encerramento por falta de retorno');

insert into imobdesk.ch_gatilhos (nome, disparos, todas, qualquer, acoes, execucao, ordem, ativo)
select x.nome, x.disparos, x.todas, x.qualquer, x.acoes, x.execucao, x.ordem, false
from (values
  ('Cliente respondeu → volta para Em atendimento',
   '[{"tipo": "acao_solicitante"}]'::jsonb,
   jsonb_build_array(jsonb_build_object('campo', 'status', 'operador', 'um_de', 'valores',
     (select jsonb_agg(s.id::text) from imobdesk.ch_status s where s.categoria = 'pendente'))),
   '[]'::jsonb,
   jsonb_build_array(jsonb_build_object('tipo', 'status', 'statusId', (select s.id from imobdesk.ch_status s where s.nome = 'Em atendimento'), 'justificativaId', null),
                     jsonb_build_object('tipo', 'avisar', 'quem', 'responsavel', 'texto', 'O solicitante respondeu.')),
   'evento', 1),
  ('Sem retorno do cliente em 48 h úteis → Resolvido',
   '[{"tipo": "tempo_status", "horas": 48}]'::jsonb,
   jsonb_build_array(jsonb_build_object('campo', 'status', 'operador', 'um_de', 'valores',
     jsonb_build_array((select s.id || ':' || j.id from imobdesk.ch_status s join imobdesk.ch_status_justificativas j on j.status_id = s.id
                        where s.nome = 'Aguardando' and j.nome = 'Retorno do cliente')))),
   '[]'::jsonb,
   jsonb_build_array(jsonb_build_object('tipo', 'responder_macro', 'macroId', (select m.id from imobdesk.ch_macros m where m.nome = 'Encerramento por falta de retorno')),
                     jsonb_build_object('tipo', 'solucao', 'texto', 'Encerrado por falta de retorno do solicitante.'),
                     jsonb_build_object('tipo', 'status', 'statusId', (select s.id from imobdesk.ch_status s where s.nome = 'Resolvido'), 'justificativaId', null)),
   'evento', 2),
  ('Urgência urgente → avisar a equipe',
   '[{"tipo": "criado"}, {"tipo": "alterado"}]'::jsonb,
   jsonb_build_array(jsonb_build_object('campo', 'urgencia', 'operador', 'um_de', 'valores', jsonb_build_array((select u.id::text from imobdesk.ch_urgencias u where u.nome = 'Urgente')))),
   '[]'::jsonb,
   jsonb_build_array(jsonb_build_object('tipo', 'tags_adicionar', 'tags', jsonb_build_array('urgente')),
                     jsonb_build_object('tipo', 'nota_interna', 'texto', 'Ticket urgente: a equipe foi avisada.'),
                     jsonb_build_object('tipo', 'avisar', 'quem', 'equipe', 'texto', 'Chegou um ticket urgente.')),
   'ticket', 3),
  ('SLA vence em 2 h sem responsável',
   '[{"tipo": "sla_vence", "horas": 2}]'::jsonb,
   jsonb_build_array(jsonb_build_object('campo', 'responsavel', 'operador', 'vazio', 'valores', '[]'::jsonb)),
   '[]'::jsonb,
   jsonb_build_array(jsonb_build_object('tipo', 'avisar', 'quem', 'lider', 'texto', 'O SLA vence em menos de 2 h e o ticket está sem responsável.'),
                     jsonb_build_object('tipo', 'seguidor', 'modo', 'lider')),
   'evento', 4)
) as x(nome, disparos, todas, qualquer, acoes, execucao, ordem)
where not exists (select 1 from imobdesk.ch_gatilhos);

-- ---------- Permissões e agendamento ----------
do $$
declare
  f text;
begin
  foreach f in array array[
    'ch_gatilhos_lista()', 'ch_gatilho_salvar(jsonb)', 'ch_gatilho_ordenar(bigint[])', 'ch_gatilho_simular(jsonb, bigint)',
    'ch_gatilho_execucoes(int, bigint)', 'ch_notificacoes_lista()', 'ch_notificacoes_ler(bigint[])'
  ] loop
    execute format('revoke execute on function imobdesk.%s from public, anon', f);
    execute format('grant execute on function imobdesk.%s to authenticated, service_role', f);
  end loop;
  -- Internas: só o banco chama.
  foreach f in array array[
    'ch_gatilho_condicao(imobdesk.ch_tickets, jsonb, text)', 'ch_gatilho_atende(imobdesk.ch_tickets, jsonb, jsonb, text)',
    'ch_gatilho_aplicar(bigint, imobdesk.ch_gatilhos)', 'ch_gatilho_executar(imobdesk.ch_gatilhos, bigint, text, text, text)',
    'ch_gatilhos_rodar(bigint, text[], text, text)', 'ch_gatilhos_tempo()', 'ch_notificar(uuid[], bigint, text, text)', 'ch_dentro_expediente(bigint, timestamptz)'
  ] loop
    execute format('revoke execute on function imobdesk.%s from public, anon, authenticated', f);
    execute format('grant execute on function imobdesk.%s to service_role', f);
  end loop;
end;
$$;

-- pg_cron já está instalado no projeto; cron.schedule com nome atualiza o job se ele já existir.
select cron.schedule('imobdesk-gatilhos-5min', '*/5 * * * *', 'select imobdesk.ch_gatilhos_tempo()');

notify pgrst, 'reload schema';

-- ======================================== 20261008120000_imobdesk_email_recebimento.sql
-- Etapa 4 (docs/PLANO-recebimento-email-ticket.md): e-mail recebido vira ticket ou ação, e a resposta pública
-- do ticket sai pela conta de e-mail. A Edge imobdesk-email-sync roda a cada 1 min pelo pg_cron,
-- autenticada por uma chave no Vault (sem JWT). Só aditiva.

-- ---------- Colunas de controle ----------
alter table imobdesk.at_email_recebidos add column if not exists motivo text;
alter table imobdesk.at_email_recebidos add column if not exists ticket_id bigint references imobdesk.ch_tickets (id) on delete set null;
create index if not exists at_email_recebidos_provedor_idx on imobdesk.at_email_recebidos (conta_id, provedor_id);

alter table imobdesk.ch_ticket_acoes add column if not exists envio_tentativas int not null default 0;
alter table imobdesk.ch_ticket_acoes add column if not exists enviado_em timestamptz;
create index if not exists ch_ticket_acoes_msgid_idx on imobdesk.ch_ticket_acoes (email_message_id) where email_message_id is not null;
create index if not exists ch_ticket_acoes_envio_idx on imobdesk.ch_ticket_acoes (criado_em) where envio_status = 'pendente';

-- ---------- Anexos dos e-mails (privado, 25 MB por arquivo) ----------
insert into storage.buckets (id, name, public, file_size_limit)
values ('imobdesk-atendimento-email', 'imobdesk-atendimento-email', false, 26214400)
on conflict (id) do nothing;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'atendimento-email: leitura') then
    create policy "atendimento-email: leitura" on storage.objects for select to authenticated
      using (bucket_id = 'imobdesk-atendimento-email'
             and (select imobdesk.ch_eh_admin() or imobdesk.tem_permissao('gestao_chamados_tickets')));
  end if;
end;
$$;

-- ---------- Chave do agendamento (pg_cron → Edge) ----------
do $$
begin
  if not exists (select 1 from vault.secrets where name = 'imobdesk_email_cron') then
    perform vault.create_secret(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 'imobdesk_email_cron',
      'Chave do pg_cron para a Edge imobdesk-email-sync (Imobdesk)');
  end if;
end;
$$;

create or replace function imobdesk.at_email_cron_chave()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select d.decrypted_secret from vault.decrypted_secrets d where d.name = 'imobdesk_email_cron';
$$;

-- ---------- E-mail recebido → ticket novo ou ação no ticket ----------
/**
 * Processa um e-mail de at_email_recebidos (estado pendente). Resposta ("[#n]" no assunto ou In-Reply-To/References
 * de uma ação já trocada) vira ação de entrada no ticket; senão, abre ticket no setor da conta, conforme a regra de
 * abertura da conta. Ticket Resolvido volta como "Reaberto"; Aguardando volta para "Em atendimento"; Fechado ou
 * Cancelado abre ticket novo. Devolve {estado, ticketId, motivo}.
 */
create or replace function imobdesk.ch_email_processar(p_recebido bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  r imobdesk.at_email_recebidos;
  c imobdesk.at_email_contas;
  t imobdesk.ch_tickets;
  v_ticket bigint;
  v_cat text;
  v_ids text[];
  v_pessoa bigint;
  v_num int;
  v_dominio text;
  v_motivo text;
  v_status bigint;
begin
  select * into r from imobdesk.at_email_recebidos x where x.id = p_recebido for update;
  if r.id is null or r.estado <> 'pendente' then
    return jsonb_build_object('estado', coalesce(r.estado, 'inexistente'), 'ticketId', r.ticket_id);
  end if;
  select * into c from imobdesk.at_email_contas x where x.id = r.conta_id;

  -- 1) É resposta a um ticket?
  v_ticket := nullif(substring(coalesce(r.assunto, '') from '\[#(\d{1,12})\]'), '')::bigint;
  if v_ticket is not null and not exists (select 1 from imobdesk.ch_tickets x where x.id = v_ticket and x.excluido_em is null) then
    v_ticket := null;
  end if;
  if v_ticket is null then
    v_ids := array(select m[1] from regexp_matches(coalesce(r.in_reply_to, '') || ' ' || coalesce(r.referencias, ''), '(<[^<>[:space:]]+>)', 'g') m);
    if cardinality(v_ids) > 0 then
      select a.ticket_id into v_ticket from imobdesk.ch_ticket_acoes a
       where a.email_message_id = any (v_ids) order by a.id desc limit 1;
      if v_ticket is null then
        select x.id into v_ticket from imobdesk.ch_tickets x
         where x.email_thread_id = any (v_ids) and x.excluido_em is null order by x.id desc limit 1;
      end if;
    end if;
  end if;
  -- Ticket mesclado: a resposta cai no destino.
  while v_ticket is not null loop
    select * into t from imobdesk.ch_tickets x where x.id = v_ticket;
    exit when t.mesclado_em_id is null;
    v_ticket := t.mesclado_em_id;
  end loop;

  if v_ticket is not null then
    v_cat := (select s.categoria from imobdesk.ch_status s where s.id = t.status_id);
    if v_cat in ('fechado', 'cancelado') then
      v_ticket := null;   -- encerrado de vez: abre ticket novo
    else
      perform 1 from imobdesk.ch_tickets x where x.id = v_ticket for update;
      v_num := coalesce((select max(a.numero) from imobdesk.ch_ticket_acoes a where a.ticket_id = v_ticket), 0) + 1;
      insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_nome, texto, html, anexos, envio_status, email_message_id)
      values (v_ticket, v_num, 'publica', 'email', 'entrada', coalesce(nullif(btrim(r.de_nome), ''), r.de), left(coalesce(r.texto, ''), 100000), r.html, r.anexos,
              'nao_se_aplica', r.message_id);
      if v_cat = 'resolvido' then
        v_status := coalesce((select s.id from imobdesk.ch_status s where s.categoria = 'andamento' and s.ativo and lower(s.nome) = 'reaberto' limit 1),
                             (select s.id from imobdesk.ch_status s where s.categoria = 'andamento' and s.ativo order by s.ordem limit 1));
      elsif v_cat = 'pendente' then
        v_status := (select s.id from imobdesk.ch_status s where s.categoria = 'andamento' and s.ativo order by s.ordem limit 1);
      end if;
      if v_status is not null then
        update imobdesk.ch_tickets set status_id = v_status, justificativa_id = null where id = v_ticket;
      end if;
      update imobdesk.at_email_recebidos set estado = 'virou_chamado', ticket_id = v_ticket, motivo = format('resposta no ticket #%s', v_ticket) where id = r.id;
      return jsonb_build_object('estado', 'virou_chamado', 'ticketId', v_ticket, 'motivo', 'resposta');
    end if;
  end if;

  -- 2) Ticket novo: regra de abertura da conta.
  v_dominio := split_part(r.de, '@', 2);
  if c.abrir_tickets = 'nao' then
    v_motivo := 'a conta não abre tickets novos';
  elsif c.abrir_tickets in ('cliente', 'cliente_ou_dominio')
        and not exists (select 1 from imobdesk.at_pessoa_contatos pc where pc.tipo = 'email' and pc.valor = r.de)
        and not (c.abrir_tickets = 'cliente_ou_dominio'
                 and exists (select 1 from imobdesk.at_pessoas e where e.tipo <> 'pessoa' and e.habilitada and v_dominio = any (e.dominios))) then
    v_motivo := case when c.abrir_tickets = 'cliente' then 'remetente não cadastrado em Pessoas' else 'remetente nem domínio cadastrados em Pessoas' end;
  elsif c.setor_id is null then
    v_motivo := 'a conta de e-mail não tem setor';
  end if;
  if v_motivo is not null then
    update imobdesk.at_email_recebidos set estado = 'ignorado', motivo = v_motivo where id = r.id;
    return jsonb_build_object('estado', 'ignorado', 'motivo', v_motivo);
  end if;

  v_pessoa := imobdesk.at_pessoa_identificar('email', r.de, r.de_nome, 'E-mail para ' || c.email);
  insert into imobdesk.ch_tickets (assunto, origem, recebido_em, solicitante_pessoa_id, solicitante_nome, solicitante_contato, email_conta_id,
                                             email_thread_id, setor_id, categoria_id, urgencia_id, status_id, cc)
  values (left(coalesce(nullif(btrim(r.assunto), ''), '(sem assunto)'), 300), 'email', left(c.email, 160), v_pessoa,
          left(coalesce(nullif(btrim(r.de_nome), ''), (select pe.nome from imobdesk.at_pessoas pe where pe.id = v_pessoa), r.de), 160), r.de, c.id,
          r.message_id, c.setor_id,
          (select x.id from imobdesk.ch_categorias x where x.padrao and x.ativa limit 1),
          coalesce((select u.id from imobdesk.ch_urgencias u where u.padrao and u.ativa limit 1), (select min(u.id) from imobdesk.ch_urgencias u)),
          coalesce((select s.id from imobdesk.ch_status s where s.categoria = 'novo' and s.ativo order by s.ordem limit 1), 1),
          coalesce(array(select x from unnest(r.para || r.cc) x where x <> c.email and x <> coalesce(c.oauth_email, '') and x <> r.de), '{}'))
  returning id into v_ticket;
  insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_nome, texto, html, anexos, envio_status, email_message_id)
  values (v_ticket, 1, 'publica', 'email', 'entrada', coalesce(nullif(btrim(r.de_nome), ''), r.de), left(coalesce(r.texto, ''), 100000), r.html, r.anexos,
          'nao_se_aplica', r.message_id);
  update imobdesk.at_email_recebidos set estado = 'virou_chamado', ticket_id = v_ticket, pessoa_id = v_pessoa, motivo = 'ticket novo' where id = r.id;
  return jsonb_build_object('estado', 'virou_chamado', 'ticketId', v_ticket, 'motivo', 'novo');
end;
$$;

-- ---------- Respostas públicas a enviar por e-mail ----------
/** Ações públicas pendentes de tickets de e-mail, com tudo o que a Edge precisa para montar a mensagem. */
create or replace function imobdesk.ch_email_para_enviar(p_limite int default 20)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(x order by x ->> 'criadoEm'), '[]') from (
    select jsonb_build_object(
      'acaoId', a.id, 'ticketId', t.id, 'numero', a.numero, 'texto', a.texto, 'html', a.html, 'criadoEm', a.criado_em,
      'tentativas', a.envio_tentativas, 'assunto', t.assunto, 'para', t.solicitante_contato, 'cc', to_jsonb(t.cc),
      'contaId', c.id, 'contaEmail', c.email, 'remetente', coalesce(nullif(btrim(c.nome_remetente), ''), c.nome),
      'exibirRemetente', c.exibir_no_envio, 'responderPara', c.responder_para, 'copiaOculta', c.copia_oculta, 'assinatura', c.assinatura,
      'raiz', t.email_thread_id,
      'ultimaRecebida', (select e.email_message_id from imobdesk.ch_ticket_acoes e
                          where e.ticket_id = t.id and e.direcao = 'entrada' and e.email_message_id is not null order by e.numero desc limit 1),
      'threadGmail', (select r.thread_id from imobdesk.at_email_recebidos r where r.ticket_id = t.id and r.conta_id = c.id order by r.id desc limit 1)
    ) x
    from imobdesk.ch_ticket_acoes a
    join imobdesk.ch_tickets t on t.id = a.ticket_id
    join imobdesk.at_email_contas c on c.id = t.email_conta_id
    where a.envio_status = 'pendente' and a.canal = 'email' and a.tipo = 'publica' and a.direcao = 'saida'
      and t.excluido_em is null and c.habilitada and c.modo = 'oauth_google' and c.oauth_segredo_id is not null
    order by a.criado_em
    limit greatest(1, least(p_limite, 100))
  ) s;
$$;

/** Resultado do envio: enviado (com o Message-ID, que liga a resposta do cliente ao ticket) ou falha (3 tentativas). */
create or replace function imobdesk.ch_email_envio_resultado(p_acao bigint, p_ok boolean, p_message_id text, p_erro text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_ok then
    update imobdesk.ch_ticket_acoes
       set envio_status = 'enviado', envio_erro = null, email_message_id = p_message_id, enviado_em = now(), envio_tentativas = envio_tentativas + 1
     where id = p_acao;
  else
    update imobdesk.ch_ticket_acoes
       set envio_tentativas = envio_tentativas + 1, envio_erro = left(p_erro, 1000),
           envio_status = case when envio_tentativas + 1 >= 3 then 'falhou' else 'pendente' end
     where id = p_acao;
  end if;
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array['at_email_cron_chave()', 'ch_email_processar(bigint)', 'ch_email_para_enviar(int)', 'ch_email_envio_resultado(bigint, boolean, text, text)'] loop
    execute format('revoke execute on function imobdesk.%s from public, anon, authenticated', f);
    execute format('grant execute on function imobdesk.%s to service_role', f);
  end loop;
end;
$$;

-- ---------- Agendamento: lê as caixas e envia as respostas a cada 1 min ----------
do $$
begin
  if exists (select 1 from cron.job where jobname = 'imobdesk-email-1min') then
    perform cron.unschedule('imobdesk-email-1min');
  end if;
  perform cron.schedule('imobdesk-email-1min', '* * * * *', $job$
    select net.http_post(
      url := 'https://ikvjaowvpvxojvcfwnct.supabase.co/functions/v1/imobdesk-email-sync',
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-atendimento-chave', imobdesk.at_email_cron_chave()),
      body := '{"acao": "ciclo"}'::jsonb,
      timeout_milliseconds := 55000
    );
  $job$);
end;
$$;

-- ======================================== 20261008140000_imobdesk_ia_triagem.sql
-- IA nos tickets — triagem por equipe (docs/PLANO-ia-triagem-solucoes.md, IA-1/IA-2, aprovado em 07/10/2026).
-- Ticket sem equipe num setor com IA ligada → a Edge imobdesk-ia (pg_cron, 1 min) classifica entre as
-- equipes e serviços do setor. Decisão do Wagner (08/10/2026), revendo a D4: modo AUTOMÁTICO a partir de 80% de
-- confiança na TI; abaixo disso o ticket fica sem equipe, em "Revisar classificação". Configurável por setor.
-- A parte "já existe solução?" (pgvector, base de conhecimento) fica para a próxima fase. Só aditiva.

-- ---------- Configuração por setor ----------
create table if not exists imobdesk.ch_ia_config (
  setor_id        bigint      primary key references imobdesk.at_setores (id) on delete cascade,
  ligada          boolean     not null default false,
  modo            text        not null default 'sugestao' check (modo in ('automatico', 'sugestao')),
  limiar          int         not null default 80 check (limiar between 50 and 100),
  ia_desde        timestamptz not null default now(),          -- tickets criados antes disto não são classificados
  atualizado_em   timestamptz not null default now(),
  atualizado_por  uuid
);

-- TI: as equipes Sistemas e Infraestrutura não têm padrão; a IA escolhe. Inclui os tickets de hoje.
insert into imobdesk.ch_ia_config (setor_id, ligada, modo, limiar, ia_desde)
select s.id, true, 'automatico', 80, date_trunc('day', now() at time zone 'America/Sao_Paulo') at time zone 'America/Sao_Paulo'
from imobdesk.at_setores s where lower(s.nome) = 'ti'
on conflict (setor_id) do nothing;

-- ---------- Resultado por ticket ----------
create table if not exists imobdesk.ch_ticket_ia (
  id              bigint      generated always as identity primary key,
  ticket_id       bigint      not null references imobdesk.ch_tickets (id) on delete cascade,
  situacao        text        not null check (situacao in ('aplicado', 'sugerido', 'baixa_confianca', 'erro')),
  equipe_id       bigint      references imobdesk.at_equipes (id) on delete set null,
  servico_id      bigint      references imobdesk.ch_servicos (id) on delete set null,
  confianca       int         check (confianca between 0 and 100),
  motivo          text,
  modelo          text,
  tokens_entrada  int,
  tokens_saida    int,
  ms              int,
  erro            text,
  criado_em       timestamptz not null default now()
);
create index if not exists ch_ticket_ia_ticket_idx on imobdesk.ch_ticket_ia (ticket_id, criado_em desc);

do $$
declare
  t text;
begin
  foreach t in array array['ch_ia_config', 'ch_ticket_ia'] loop
    execute format('alter table imobdesk.%I enable row level security', t);
    execute format('revoke all on imobdesk.%I from anon, public, authenticated', t);
    execute format('grant all on imobdesk.%I to service_role', t);
  end loop;
end;
$$;

-- ---------- Fila: tickets a classificar, com as candidatas do setor ----------
create or replace function imobdesk.ch_ia_pendentes(p_limite int default 10)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with recursive arvore as (
    select s.id, s.setor_id, s.nome::text as caminho from imobdesk.ch_servicos s where s.pai_id is null and s.ativo
    union all
    select f.id, f.setor_id, a.caminho || ' › ' || f.nome from imobdesk.ch_servicos f join arvore a on a.id = f.pai_id where f.ativo
  ), fila as (
    select t.id, t.setor_id, t.assunto, cfg.modo, cfg.limiar,
           coalesce((select a.texto from imobdesk.ch_ticket_acoes a where a.ticket_id = t.id order by a.numero limit 1), '') as descricao
    from imobdesk.ch_tickets t
    join imobdesk.ch_ia_config cfg on cfg.setor_id = t.setor_id and cfg.ligada
    where t.equipe_id is null and t.excluido_em is null and t.mesclado_em_id is null and t.encerrado_em is null
      and t.criado_em >= cfg.ia_desde
      and not exists (select 1 from imobdesk.ch_ticket_ia i where i.ticket_id = t.id and i.situacao <> 'erro')
      and (select count(*) from imobdesk.ch_ticket_ia i where i.ticket_id = t.id and i.situacao = 'erro') < 3
    order by t.id
    limit greatest(1, least(p_limite, 50))
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'ticketId', f.id, 'setorId', f.setor_id, 'assunto', f.assunto, 'descricao', left(f.descricao, 20000), 'modo', f.modo, 'limiar', f.limiar,
    'equipes', coalesce((select jsonb_agg(jsonb_build_object('id', e.id, 'nome', e.nome, 'descricao', e.descricao_ia) order by e.nome)
                         from imobdesk.at_equipes e where e.setor_id = f.setor_id and e.ativa), '[]'),
    'servicos', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'caminho', a.caminho, 'equipeId', imobdesk.ch_servico_equipe(a.id)) order by a.caminho)
                          from arvore a where a.setor_id = f.setor_id
                            and not exists (select 1 from imobdesk.ch_servicos x where x.pai_id = a.id and x.ativo)), '[]')
  ) order by f.id), '[]')
  from fila f;
$$;

-- ---------- Registro e aplicação ----------
/**
 * Grava o resultado da IA. Modo automático com confiança ≥ limiar e o ticket ainda sem equipe → define equipe
 * (e o serviço, se coerente com a equipe e o ticket ainda não tiver) e registra no histórico. Senão fica a sugestão.
 */
create or replace function imobdesk.ch_ia_registrar(p_ticket bigint, p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets;
  cfg imobdesk.ch_ia_config;
  v_equipe bigint := nullif(p ->> 'equipeId', '')::bigint;
  v_servico bigint := nullif(p ->> 'servicoId', '')::bigint;
  v_conf int := nullif(p ->> 'confianca', '')::int;
  v_situacao text;
  v_nome_eq text;
  v_nome_sv text;
begin
  select * into t from imobdesk.ch_tickets x where x.id = p_ticket for update;
  if t.id is null then return jsonb_build_object('situacao', 'inexistente'); end if;
  select * into cfg from imobdesk.ch_ia_config c where c.setor_id = t.setor_id;

  if nullif(p ->> 'erro', '') is not null then
    insert into imobdesk.ch_ticket_ia (ticket_id, situacao, modelo, ms, erro)
    values (p_ticket, 'erro', p ->> 'modelo', nullif(p ->> 'ms', '')::int, left(p ->> 'erro', 1000));
    return jsonb_build_object('situacao', 'erro');
  end if;

  -- Equipe precisa ser do setor; serviço do setor e da mesma equipe (senão é descartado).
  if not exists (select 1 from imobdesk.at_equipes e where e.id = v_equipe and e.setor_id = t.setor_id and e.ativa) then
    insert into imobdesk.ch_ticket_ia (ticket_id, situacao, modelo, ms, erro)
    values (p_ticket, 'erro', p ->> 'modelo', nullif(p ->> 'ms', '')::int, 'Equipe fora do setor do ticket.');
    return jsonb_build_object('situacao', 'erro');
  end if;
  if v_servico is not null and not exists (
       select 1 from imobdesk.ch_servicos s where s.id = v_servico and s.setor_id = t.setor_id and s.ativo
         and coalesce(imobdesk.ch_servico_equipe(s.id), v_equipe) = v_equipe) then
    v_servico := null;
  end if;

  v_situacao := case
    when coalesce(v_conf, 0) < coalesce(cfg.limiar, 80) then 'baixa_confianca'
    when cfg.modo = 'automatico' and t.equipe_id is null then 'aplicado'
    else 'sugerido' end;

  insert into imobdesk.ch_ticket_ia (ticket_id, situacao, equipe_id, servico_id, confianca, motivo, modelo, tokens_entrada, tokens_saida, ms)
  values (p_ticket, v_situacao, v_equipe, v_servico, v_conf, left(p ->> 'motivo', 300), p ->> 'modelo',
          nullif(p ->> 'tokensEntrada', '')::int, nullif(p ->> 'tokensSaida', '')::int, nullif(p ->> 'ms', '')::int);

  v_nome_eq := (select e.nome from imobdesk.at_equipes e where e.id = v_equipe);
  v_nome_sv := (select s.nome from imobdesk.ch_servicos s where s.id = v_servico);
  if v_situacao = 'aplicado' then
    update imobdesk.ch_tickets
       set equipe_id = v_equipe, servico_id = coalesce(servico_id, v_servico)
     where id = p_ticket;
  end if;
  insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_nome)
  values (p_ticket, 'ia',
          format('%s pela IA (%s%%): %s%s%s',
                 case v_situacao when 'aplicado' then 'Classificado' when 'sugerido' then 'Sugestão' else 'Classificação incerta' end,
                 coalesce(v_conf, 0), v_nome_eq, case when v_nome_sv is not null then ' · ' || v_nome_sv else '' end,
                 case when nullif(btrim(p ->> 'motivo'), '') is not null then ' — ' || left(btrim(p ->> 'motivo'), 200) else '' end),
          'IA');
  return jsonb_build_object('situacao', v_situacao, 'equipe', v_nome_eq, 'servico', v_nome_sv, 'confianca', v_conf);
end;
$$;

-- ---------- Chave do agendamento (pg_cron → Edge) ----------
do $$
begin
  if not exists (select 1 from vault.secrets where name = 'imobdesk_ia_cron') then
    perform vault.create_secret(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 'imobdesk_ia_cron',
      'Chave do pg_cron para a Edge imobdesk-ia (Imobdesk)');
  end if;
end;
$$;

create or replace function imobdesk.at_ia_cron_chave()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select d.decrypted_secret from vault.decrypted_secrets d where d.name = 'imobdesk_ia_cron';
$$;

do $$
declare
  f text;
begin
  foreach f in array array['ch_ia_pendentes(int)', 'ch_ia_registrar(bigint, jsonb)', 'at_ia_cron_chave()'] loop
    execute format('revoke execute on function imobdesk.%s from public, anon, authenticated', f);
    execute format('grant execute on function imobdesk.%s to service_role', f);
  end loop;
end;
$$;

do $$
begin
  if exists (select 1 from cron.job where jobname = 'imobdesk-ia-1min') then
    perform cron.unschedule('imobdesk-ia-1min');
  end if;
  perform cron.schedule('imobdesk-ia-1min', '* * * * *', $job$
    select net.http_post(
      url := 'https://ikvjaowvpvxojvcfwnct.supabase.co/functions/v1/imobdesk-ia',
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-atendimento-chave', imobdesk.at_ia_cron_chave()),
      body := '{"acao": "triagem"}'::jsonb,
      timeout_milliseconds := 55000
    );
  $job$);
end;
$$;

-- ---------- Painel: Triagem inteligente com números reais (hoje) ----------
-- Igual à de 20261007171000, só com o bloco "triage" lendo ch_ticket_ia.
create or replace function imobdesk.ch_painel()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_eu uuid := (select auth.uid());
  v_admin boolean := imobdesk.ch_eh_admin() or imobdesk.at_supervisor();
  v_agora timestamptz := now();
  v_tokens text[] := array['--ds-team-sistemas', '--ds-team-infra', '--ds-ai', '--ds-triage-ai', '--ds-warning', '--ds-success'];
begin
  if not (imobdesk.ch_eh_admin() or imobdesk.tem_permissao('gestao_chamados_visao_geral') or imobdesk.tem_permissao('gestao_chamados_tickets')) then
    perform imobdesk.erro('FORBIDDEN', 'Sem acesso à Gestão de Chamados.');
  end if;
  return (
    with vis as (
      select t.* from imobdesk.ch_tickets t
      where t.excluido_em is null and t.mesclado_em_id is null
        and (t.encerrado_em is null or t.encerrado_em >= v_agora - interval '30 days')
        and imobdesk.ch_pode_ver_ticket(t.setor_id, t.equipe_id, t.responsavel_id)
    ), eq as (
      select e.id, e.nome, row_number() over (order by e.nome) as n from imobdesk.at_equipes e where e.ativa
    )
    select jsonb_build_object(
      'generated_at', v_agora,
      'current_user', jsonb_build_object('id', v_eu, 'name', imobdesk.ch_nome_usuario(v_eu),
                        'initials', imobdesk.ch_iniciais(imobdesk.ch_nome_usuario(v_eu))),
      'my_teams', coalesce((select jsonb_agg(e.nome order by e.nome) from eq e
                            where v_admin or exists (select 1 from imobdesk.at_equipe_membros m where m.equipe_id = e.id and m.usuario_id = v_eu)), '[]'),
      'teams', coalesce((select jsonb_agg(jsonb_build_object('name', e.nome, 'color_token', v_tokens[1 + ((e.n - 1) % 6)]) order by e.nome) from eq e), '[]'),
      'services', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'name', s.nome,
                              'team', coalesce((select e.nome from imobdesk.at_equipes e where e.id = imobdesk.ch_servico_equipe(s.id)), ''),
                              'sla_hours', coalesce((select h.solucao from imobdesk.ch_sla_horas(s.id, (select u.id from imobdesk.ch_urgencias u where u.padrao), s.setor_id) h), 0)) order by s.nome)
                            from imobdesk.ch_servicos s where s.ativo and not exists (select 1 from imobdesk.ch_servicos f where f.pai_id = s.id)), '[]'),
      'tickets', coalesce((select jsonb_agg(jsonb_build_object(
          'id', t.id, 'subject', t.assunto, 'requester', t.solicitante_nome,
          'description', coalesce((select a.texto from imobdesk.ch_ticket_acoes a where a.ticket_id = t.id order by a.numero limit 1), ''),
          'service_id', t.servico_id,
          'team', coalesce((select e.nome from imobdesk.at_equipes e where e.id = t.equipe_id), ''),
          'origin', case t.origem when 'email' then 'E-mail' when 'whatsapp' then 'WhatsApp' when 'intranet' then 'Intranet' else 'Agente' end,
          'owner', case when t.responsavel_id is null then null else jsonb_build_object('id', t.responsavel_id, 'name', imobdesk.ch_nome_usuario(t.responsavel_id),
                     'initials', imobdesk.ch_iniciais(imobdesk.ch_nome_usuario(t.responsavel_id))) end,
          'status_id', t.status_id, 'status', st.nome, 'status_categoria', st.categoria,
          'justificativa_id', t.justificativa_id, 'justificativa', (select j.nome from imobdesk.ch_status_justificativas j where j.id = t.justificativa_id),
          'prioridade', (select u.nome from imobdesk.ch_urgencias u where u.id = t.urgencia_id),
          'tags', to_jsonb(t.tags), 'recebido_em', t.recebido_em, 'criado_em', t.criado_em,
          'sla_due_minutes', coalesce(round(extract(epoch from (t.sla_solucao_ate - coalesce(t.sla_pausado_desde, v_agora))) / 60), 0),
          'opened_today', (t.criado_em at time zone 'America/Sao_Paulo')::date = (v_agora at time zone 'America/Sao_Paulo')::date,
          'closed_at', t.encerrado_em) order by t.id)
        from vis t join imobdesk.ch_status st on st.id = t.status_id), '[]'),
      'triage', (
        with hoje as (
          select t.id, t.equipe_id,
                 (select i.situacao from imobdesk.ch_ticket_ia i where i.ticket_id = t.id order by i.id desc limit 1) as ia
          from vis t where (t.criado_em at time zone 'America/Sao_Paulo')::date = (v_agora at time zone 'America/Sao_Paulo')::date
        )
        select jsonb_build_object('period', 'Hoje',
          'automatic', (select count(*) from hoje where ia = 'aplicado'),
          'total', (select count(*) from hoje),
          'by_intranet_form', 0, 'by_email_rule', 0,
          'by_ai', (select count(*) from hoje where ia = 'aplicado'),
          'manual', (select count(*) from hoje where equipe_id is null),
          'pending_review', (select count(*) from hoje where equipe_id is null and ia in ('baixa_confianca', 'sugerido')))
      ),
      'sla_health', jsonb_build_object('period', '7 dias',
                  'first_response_percent', coalesce((select round(100.0 * count(*) filter (where t.primeira_resposta_em <= t.sla_resposta_ate) / nullif(count(*), 0))
                                                      from vis t where t.primeira_resposta_em >= v_agora - interval '7 days'), 100),
                  'resolution_percent', coalesce((select round(100.0 * count(*) filter (where t.encerrado_em <= t.sla_solucao_ate) / nullif(count(*), 0))
                                                  from vis t join imobdesk.ch_status st on st.id = t.status_id
                                                  where st.categoria in ('resolvido', 'fechado') and t.encerrado_em >= v_agora - interval '7 days'), 100)),
      'inbound', (select jsonb_agg(jsonb_build_object('hour', h,
                     'today', (select count(*) from vis t where (t.criado_em at time zone 'America/Sao_Paulo')::date = (v_agora at time zone 'America/Sao_Paulo')::date
                                 and extract(hour from t.criado_em at time zone 'America/Sao_Paulo') = h),
                     'yesterday', (select count(*) from vis t where (t.criado_em at time zone 'America/Sao_Paulo')::date = (v_agora at time zone 'America/Sao_Paulo')::date - 1
                                 and extract(hour from t.criado_em at time zone 'America/Sao_Paulo') = h)) order by h)
                  from generate_series(8, 18) h)
    )
  );
end;
$$;

-- ======================================== 20261008160000_imobdesk_ticket_timeline.sql
-- Linha do tempo do ticket no modelo da Movidesk (Wagner, 08/10/2026): cada ação de e-mail traz os cabeçalhos para o
-- "Visualizar e-mail" (de, para, cc, assunto, data e status do envio). Igual à de 20261007171000, só acrescenta chaves
-- em "acoes". Só aditiva.

/** Detalhe completo para a tela do ticket. */
create or replace function imobdesk.ch_ticket_detalhe(p_id bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets := imobdesk.ch_ticket_visivel(p_id);
begin
  return jsonb_build_object(
    'id', t.id, 'assunto', t.assunto, 'origem', t.origem, 'recebidoEm', t.recebido_em,
    'solicitante', jsonb_build_object('pessoaId', t.solicitante_pessoa_id, 'nome', t.solicitante_nome, 'contato', t.solicitante_contato,
       'departamento', (select d.nome from imobdesk.at_pessoa_relacoes r join imobdesk.at_pessoas d on d.id = r.empresa_id and d.tipo = 'departamento'
                        where r.pessoa_id = t.solicitante_pessoa_id limit 1)),
    'setorId', t.setor_id, 'equipeId', t.equipe_id, 'responsavelId', t.responsavel_id, 'servicoId', t.servico_id, 'categoriaId', t.categoria_id,
    'urgenciaId', t.urgencia_id, 'statusId', t.status_id, 'justificativaId', t.justificativa_id, 'tags', to_jsonb(t.tags), 'cc', to_jsonb(t.cc), 'campos', t.campos,
    'solucaoAplicada', t.solucao_aplicada, 'criadoEm', t.criado_em, 'assumidoEm', t.assumido_em, 'primeiraRespostaEm', t.primeira_resposta_em,
    'slaRespostaAte', t.sla_resposta_ate, 'slaSolucaoAte', t.sla_solucao_ate, 'slaManual', t.sla_manual, 'slaPausadoDesde', t.sla_pausado_desde,
    'encerradoEm', t.encerrado_em, 'mescladoEmId', t.mesclado_em_id, 'clonadoDeId', t.clonado_de_id, 'excluidoEm', t.excluido_em,
    'clones', coalesce((select jsonb_agg(c.id order by c.id) from imobdesk.ch_tickets c where c.clonado_de_id = t.id), '[]'),
    'mesclados', coalesce((select jsonb_agg(c.id order by c.id) from imobdesk.ch_tickets c where c.mesclado_em_id = t.id), '[]'),
    'campoEstado', coalesce((select jsonb_object_agg(e.chave, jsonb_build_object('visivel', e.visivel, 'obrigatorio', e.obrigatorio)) from imobdesk.ch_campos_estado(t) e), '{}'),
    'seguindo', exists (select 1 from imobdesk.ch_ticket_seguidores s where s.ticket_id = t.id and s.usuario_id = (select auth.uid())),
    'acoes', coalesce((select jsonb_agg(jsonb_build_object('numero', a.numero, 'tipo', a.tipo, 'canal', a.canal, 'direcao', a.direcao, 'autorId', a.autor_id, 'autorNome', a.autor_nome,
                         'texto', a.texto, 'html', a.html, 'anexos', a.anexos, 'envioStatus', a.envio_status, 'criadoEm', a.criado_em,
                         'enviadoEm', a.enviado_em, 'envioErro', a.envio_erro, 'envioTentativas', a.envio_tentativas,
                         -- "Visualizar e-mail" da linha do tempo: cabeçalhos da mensagem trocada.
                         'email', case when a.canal <> 'email' or a.tipo <> 'publica' then null
                           when a.direcao = 'saida' then jsonb_build_object(
                             'de', c.email, 'deNome', case when c.exibir_no_envio then coalesce(nullif(btrim(c.nome_remetente), ''), c.nome) end,
                             'para', jsonb_build_array(t.solicitante_contato), 'cc', to_jsonb(t.cc),
                             'assunto', 'Re: [#' || t.id || '] ' || regexp_replace(t.assunto, '\[#\d+\]\s*', '', 'g'),
                             'data', coalesce(a.enviado_em, a.criado_em))
                           else (select jsonb_build_object('de', r.de, 'deNome', r.de_nome, 'para', to_jsonb(r.para), 'cc', to_jsonb(r.cc),
                                                           'assunto', r.assunto, 'data', r.recebido_em)
                                 from imobdesk.at_email_recebidos r where r.message_id = a.email_message_id order by r.id desc limit 1) end
                         ) order by a.numero desc)
                       from imobdesk.ch_ticket_acoes a left join imobdesk.at_email_contas c on c.id = t.email_conta_id where a.ticket_id = t.id), '[]'),
    'eventos', coalesce((select jsonb_agg(jsonb_build_object('tipo', e.tipo, 'descricao', e.descricao, 'autorNome', e.autor_nome, 'criadoEm', e.criado_em) order by e.criado_em desc, e.id desc)
                         from imobdesk.ch_ticket_eventos e where e.ticket_id = t.id), '[]'),
    'podeAlterarPrazo', imobdesk.ch_eh_admin() or imobdesk.at_gestor_de(t.setor_id),
    'podeExcluir', imobdesk.eh_super_admin()
  );
end;
$$;

-- ======================================== 20261009120000_imobdesk_seguranca_login.sql
-- Segurança do login (Security Gateway) do Imobdesk — etapa 1 de 2.
--
-- Esta etapa não muda o acesso de ninguém: cria as tabelas, o gateway e a regra de sessão confiável.
-- A etapa 2 (20261009120100_..._sessao_obrigatoria.sql) é que liga a regra na RLS, depois do deploy
-- da Edge Function e do front (ordem em docs/SEGURANCA-LOGIN.md).
--
-- Divisão de responsabilidades (docs/SEGURANCA-LOGIN.md):
--   * Supabase Auth  = identidade, senha, sessão e tokens. Nada aqui guarda ou compara senha.
--   * Este arquivo   = tentativas, bloqueios, rate limit, risco e auditoria (decide se a tentativa
--                      pode chegar ao Auth). Quem chama é a Edge Function imobdesk-auth.
--   * RLS            = o que cada sessão enxerga. Sessão de senha só vale no portal se passou
--                      pelo gateway (security_sessions); assim um login feito direto na API do
--                      Auth, contornando o gateway, não lê nem grava nada do portal.
--
-- Não altera nada no schema auth (é compartilhado com os outros sistemas da WSA): só lê
-- auth.users (e-mail para o hook) e auth.sessions (sessão ainda existe?).
--
-- Atomicidade: security_auth_begin/finish travam IP e conta com pg_advisory_xact_lock (sempre na
-- ordem IP -> conta, sem deadlock) e a linha da conta com FOR UPDATE. Além disso, cada conta só tem
-- UMA tentativa em andamento por vez (inflight_until): 50 requisições simultâneas na mesma conta
-- resultam em 1 chamada ao Auth e 49 negadas.

create extension if not exists pgcrypto with schema extensions;

-- ============================================================================================
-- Tabelas (nenhuma é acessível pelo front: RLS ligada, sem policy e sem grant para anon/authenticated)
-- ============================================================================================

-- Limites ajustáveis sem deploy (update direto no SQL editor, com service_role/postgres).
create table if not exists imobdesk.security_config (
  key text primary key,
  value integer not null check (value >= 0),
  descricao text not null
);

insert into imobdesk.security_config (key, value, descricao) values
  ('account_max_failures',       5,    'Falhas consecutivas por conta até o bloqueio'),
  ('account_lock_1_min',         15,   '1º bloqueio (minutos)'),
  ('account_lock_2_min',         30,   '2º bloqueio (minutos)'),
  ('account_lock_3_min',         60,   '3º bloqueio em diante (minutos)'),
  ('account_lock_decay_hours',   24,   'Horas sem falha para o nível de bloqueio voltar a zero'),
  ('account_backoff_base_ms',    1000, 'Espera após a 1ª falha; dobra a cada falha (1s, 2s, 4s, 8s)'),
  ('account_inflight_seconds',   15,   'Reserva da conta enquanto a tentativa está no Auth'),
  ('account_attempts_15m',       20,   'Tentativas por conta em 15 min, somando todos os IPs'),
  ('ip_attempts_1m',             10,   'Tentativas por IP em 1 min'),
  ('ip_attempts_15m',            30,   'Tentativas por IP em 15 min'),
  ('ip_attempts_1h',             100,  'Tentativas por IP em 1 h'),
  ('ip_account_attempts_15m',    5,    'Tentativas do mesmo IP na mesma conta em 15 min'),
  ('spray_accounts_5m',          10,   'Contas diferentes pelo mesmo IP em 5 min (password spraying)'),
  ('spray_block_min',            30,   'Bloqueio do IP ao detectar spraying (minutos)'),
  ('distributed_ips_15m',        5,    'IPs diferentes na mesma conta em 15 min (ataque distribuído)'),
  ('velocity_window_ms',         2000, 'Janela para detectar rajada de requisições do mesmo IP'),
  ('velocity_max',               3,    'Requisições do mesmo IP dentro da janela de rajada'),
  ('risk_cooldown',              30,   'Risco a partir do qual exige intervalo mínimo entre tentativas'),
  ('risk_cooldown_seconds',      5,    'Intervalo mínimo exigido no cooldown por risco'),
  ('risk_block',                 60,   'Risco a partir do qual bloqueia o IP'),
  ('risk_block_min',             15,   'Bloqueio do IP por risco alto (minutos)'),
  ('risk_critical',              80,   'Risco crítico: bloqueio ampliado + evento crítico'),
  ('risk_critical_block_min',    60,   'Bloqueio do IP por risco crítico (minutos)'),
  ('recover_ip_15m',             5,    'Pedidos de redefinição de senha por IP em 15 min'),
  ('recover_account_1h',         3,    'Pedidos de redefinição de senha por conta em 1 h'),
  ('hook_counts_failures',       0,    '1 quando o Password Verification Hook está ligado no Auth (evita contar a falha duas vezes)'),
  ('attempts_retention_hours',   48,   'Horas que as tentativas brutas ficam guardadas'),
  ('events_retention_days',      180,  'Dias que os eventos de segurança ficam guardados')
on conflict (key) do nothing;

-- Pepper do HMAC de e-mail e IP. Gerado no banco, nunca sai dele (nem para a Edge Function).
create table if not exists imobdesk.security_secret (
  id smallint primary key default 1 check (id = 1),
  pepper bytea not null default extensions.gen_random_bytes(32),
  created_at timestamptz not null default now()
);
insert into imobdesk.security_secret (id) values (1) on conflict (id) do nothing;

-- Estado por conta. A chave é o HMAC do e-mail normalizado: vale também para e-mail inexistente,
-- então bloqueio e limites não revelam se a conta existe. Nunca guarda senha, hash de senha ou token.
create table if not exists imobdesk.security_auth_control (
  user_hash text primary key,
  user_id uuid,
  failed_attempts integer not null default 0,
  lock_level integer not null default 0,
  locked_until timestamptz,
  next_allowed_at timestamptz,
  inflight_until timestamptz,
  last_failed_at timestamptz,
  last_hook_failure_at timestamptz,
  last_success_at timestamptz,
  last_lock_at timestamptz,
  risk_score integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists security_auth_control_user_id on imobdesk.security_auth_control (user_id) where user_id is not null;

-- Toda tentativa (permitida ou negada). Base dos limites por IP, conta e IP+conta e da detecção
-- de spraying/distribuído. Vida curta (attempts_retention_hours).
create table if not exists imobdesk.security_attempts (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default clock_timestamp(),
  kind text not null check (kind in ('login', 'recover')),
  ip_hash text not null,
  user_hash text not null,
  outcome text not null check (outcome in ('pending', 'success', 'failure', 'denied', 'error')),
  reason text,
  risk_score integer not null default 0,
  request_id uuid,
  finished_at timestamptz
);
create index if not exists security_attempts_ip on imobdesk.security_attempts (ip_hash, created_at desc);
create index if not exists security_attempts_user on imobdesk.security_attempts (user_hash, created_at desc);
create index if not exists security_attempts_created on imobdesk.security_attempts (created_at);

create table if not exists imobdesk.security_ip_blocks (
  ip_hash text primary key,
  blocked_until timestamptz not null,
  reason text not null,
  block_count integer not null default 1,
  last_block_at timestamptz not null default now()
);

-- Auditoria permanente. E-mail só mascarado; IP só o prefixo (/24 ou /48) + HMAC.
create table if not exists imobdesk.security_events (
  id bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  event_type text not null,
  severity text not null default 'info' check (severity in ('info', 'warning', 'critical')),
  request_id uuid,
  ip_hash text,
  ip_prefix text,
  user_hash text,
  user_id uuid,
  email_masked text,
  reason_code text,
  risk_score integer,
  detail jsonb not null default '{}'::jsonb
);
create index if not exists security_events_created on imobdesk.security_events (created_at desc);
create index if not exists security_events_type on imobdesk.security_events (event_type, created_at desc);
create index if not exists security_events_user on imobdesk.security_events (user_id, created_at desc) where user_id is not null;

-- Sessões de senha emitidas pelo gateway. Só o id da sessão do Auth (nunca token).
create table if not exists imobdesk.security_sessions (
  session_id uuid primary key,
  user_id uuid not null,
  created_at timestamptz not null default now(),
  ip_hash text,
  revoked_at timestamptz,
  revoked_reason text
);
create index if not exists security_sessions_user on imobdesk.security_sessions (user_id);

do $$
declare
  t text;
begin
  foreach t in array array['security_config', 'security_secret', 'security_auth_control', 'security_attempts',
                           'security_ip_blocks', 'security_events', 'security_sessions'] loop
    -- RLS ligada e nenhuma policy: anon/authenticated não leem nem gravam nada, nem com grant futuro.
    execute format('alter table imobdesk.%I enable row level security', t);
    execute format('revoke all on imobdesk.%I from anon, public, authenticated', t);
    execute format('grant all on imobdesk.%I to service_role', t);
  end loop;
end;
$$;

-- ============================================================================================
-- Funções internas (sem grant para ninguém além do dono)
-- ============================================================================================

create or replace function imobdesk.security_cfg(p_key text)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v integer;
begin
  select c.value into v from imobdesk.security_config c where c.key = p_key;
  -- Fail closed: limite sem valor é erro, nunca "sem limite".
  if v is null then
    raise exception 'security_config sem a chave %', p_key;
  end if;
  return v;
end;
$$;

create or replace function imobdesk.security_hash(p_kind text, p_value text)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select encode(extensions.hmac(convert_to(p_kind || ':' || p_value, 'UTF8'), s.pepper, 'sha256'), 'hex')
  from imobdesk.security_secret s
  where s.id = 1;
$$;

create or replace function imobdesk.security_normalize_email(p_email text)
returns text
language sql
immutable
set search_path = ''
as $$
  select lower(trim(coalesce(p_email, '')));
$$;

create or replace function imobdesk.security_mask_email(p_email text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when position('@' in coalesce(p_email, '')) < 2 then null
    else left(p_email, 1) || '***' || substr(p_email, position('@' in p_email) - 1, 1) || substr(p_email, position('@' in p_email))
  end;
$$;

create or replace function imobdesk.security_ip_prefix(p_ip text)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v inet;
begin
  begin
    v := p_ip::inet;
  exception when others then
    return null;
  end;
  return host(network(set_masklen(v, case when family(v) = 4 then 24 else 48 end))) || case when family(v) = 4 then '/24' else '/48' end;
end;
$$;

create or replace function imobdesk.security_log_event(
  p_type text, p_severity text, p_request_id uuid, p_ip_hash text, p_ip text, p_user_hash text,
  p_user_id uuid, p_email text, p_reason text, p_risk integer, p_detail jsonb default '{}'::jsonb
)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into imobdesk.security_events
    (event_type, severity, request_id, ip_hash, ip_prefix, user_hash, user_id, email_masked, reason_code, risk_score, detail)
  values
    (p_type, p_severity, p_request_id, p_ip_hash, imobdesk.security_ip_prefix(p_ip), p_user_hash, p_user_id,
     imobdesk.security_mask_email(p_email), p_reason, p_risk, coalesce(p_detail, '{}'::jsonb));
$$;

create or replace function imobdesk.security_block_ip(p_ip_hash text, p_minutes integer, p_reason text)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into imobdesk.security_ip_blocks (ip_hash, blocked_until, reason, block_count, last_block_at)
  values (p_ip_hash, clock_timestamp() + make_interval(mins => p_minutes), p_reason, 1, clock_timestamp())
  on conflict (ip_hash) do update
    set blocked_until = greatest(imobdesk.security_ip_blocks.blocked_until, excluded.blocked_until),
        reason = excluded.reason,
        block_count = imobdesk.security_ip_blocks.block_count + 1,
        last_block_at = excluded.last_block_at;
$$;

-- Duração do bloqueio da conta pelo nível (1 = 15 min, 2 = 30 min, 3+ = 60 min). Nunca permanente.
create or replace function imobdesk.security_lock_minutes(p_level integer)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when p_level <= 1 then imobdesk.security_cfg('account_lock_1_min')
    when p_level = 2 then imobdesk.security_cfg('account_lock_2_min')
    else imobdesk.security_cfg('account_lock_3_min')
  end;
$$;

-- Registra uma falha de credencial na conta (linha já travada por quem chama). Devolve true se bloqueou.
create or replace function imobdesk.security_register_failure(p_user_hash text, p_from_hook boolean)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now timestamptz := clock_timestamp();
  c imobdesk.security_auth_control;
  v_level integer;
begin
  select * into c from imobdesk.security_auth_control where user_hash = p_user_hash for update;

  -- Nível de bloqueio "esquece" depois de um dia inteiro sem falhas.
  v_level := c.lock_level;
  if v_level > 0 and coalesce(c.last_failed_at, c.last_lock_at, v_now) < v_now - make_interval(hours => imobdesk.security_cfg('account_lock_decay_hours')) then
    v_level := 0;
  end if;

  if c.failed_attempts + 1 >= imobdesk.security_cfg('account_max_failures') then
    v_level := v_level + 1;
    update imobdesk.security_auth_control
    set failed_attempts = 0,
        lock_level = v_level,
        locked_until = v_now + make_interval(mins => imobdesk.security_lock_minutes(v_level)),
        next_allowed_at = null,
        inflight_until = null,
        last_failed_at = v_now,
        last_lock_at = v_now,
        last_hook_failure_at = case when p_from_hook then v_now else last_hook_failure_at end,
        updated_at = v_now
    where user_hash = p_user_hash;
    return true;
  end if;

  update imobdesk.security_auth_control
  set failed_attempts = c.failed_attempts + 1,
      lock_level = v_level,
      -- Atraso progressivo sem dormir no servidor: 1s, 2s, 4s, 8s...
      next_allowed_at = v_now + make_interval(secs => (imobdesk.security_cfg('account_backoff_base_ms') * power(2, c.failed_attempts)) / 1000.0),
      inflight_until = null,
      last_failed_at = v_now,
      last_hook_failure_at = case when p_from_hook then v_now else last_hook_failure_at end,
      updated_at = v_now
  where user_hash = p_user_hash;
  return false;
end;
$$;

-- Limpeza das tentativas brutas e eventos antigos (chamada de vez em quando pelo begin).
create or replace function imobdesk.security_cleanup()
returns void
language sql
security definer
set search_path = ''
as $$
  delete from imobdesk.security_attempts
  where created_at < clock_timestamp() - make_interval(hours => imobdesk.security_cfg('attempts_retention_hours'));
  delete from imobdesk.security_events
  where created_at < clock_timestamp() - make_interval(days => imobdesk.security_cfg('events_retention_days'));
  delete from imobdesk.security_ip_blocks
  where blocked_until < clock_timestamp() - interval '7 days';
  delete from imobdesk.security_sessions s
  where s.revoked_at < clock_timestamp() - interval '30 days'
     or (s.created_at < clock_timestamp() - interval '1 day'
         and not exists (select 1 from auth.sessions a where a.id = s.session_id));
$$;

-- ============================================================================================
-- Gateway: begin (antes do Auth) e finish (depois do Auth). Só a Edge Function (service_role) chama.
-- ============================================================================================

-- Códigos internos (nunca saem do servidor; a resposta pública é sempre a mesma):
--   SEC_AUTH_001 ACCOUNT_LOCKED          SEC_AUTH_007 RATE_LIMIT_ACCOUNT
--   SEC_AUTH_002 ACCOUNT_COOLDOWN        SEC_AUTH_008 PASSWORD_SPRAY
--   SEC_AUTH_003 ACCOUNT_BUSY (paralelo) SEC_AUTH_009 DISTRIBUTED_ATTACK
--   SEC_AUTH_004 IP_BLOCKED              SEC_AUTH_010 RISK_COOLDOWN
--   SEC_AUTH_005 RATE_LIMIT_IP           SEC_AUTH_011 RISK_BLOCK
--   SEC_AUTH_006 RATE_LIMIT_IP_ACCOUNT   SEC_AUTH_012 RISK_CRITICAL
--   SEC_AUTH_013 DOMAIN_NOT_ALLOWED      SEC_AUTH_020 RATE_LIMIT_RECOVER
create or replace function imobdesk.security_auth_begin(
  p_kind text,
  p_email text,
  p_ip text,
  p_request_id uuid,
  p_domain_allowed boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_email text := imobdesk.security_normalize_email(p_email);
  v_ip text := coalesce(nullif(trim(p_ip), ''), 'unknown');
  v_user_hash text;
  v_ip_hash text;
  c imobdesk.security_auth_control;
  v_block imobdesk.security_ip_blocks;
  v_ip_1m integer; v_ip_15m integer; v_ip_1h integer; v_ip_burst integer;
  v_ipacc_15m integer; v_acc_15m integer; v_acc_recover_1h integer; v_ip_recover_15m integer;
  v_spray integer; v_dist integer;
  v_last_ip_attempt timestamptz;
  v_last_acct_attempt timestamptz;
  v_risk integer := 0;
  v_ip_risk integer := 0;
  v_signals text[] := '{}';
  v_reason text;
  v_event text;
  v_severity text := 'warning';
  v_attempt uuid;
begin
  if p_kind not in ('login', 'recover') or v_email = '' or length(v_email) > 254 or length(v_ip) > 64 then
    raise exception 'security_auth_begin: parâmetros inválidos';
  end if;

  v_user_hash := imobdesk.security_hash('acct', v_email);
  v_ip_hash := imobdesk.security_hash('ip', v_ip);

  -- Serializa por IP e por conta (sempre nesta ordem). Fecha a corrida "todas leem 4 e passam".
  perform pg_advisory_xact_lock(hashtextextended('sec:ip:' || v_ip_hash, 0));
  perform pg_advisory_xact_lock(hashtextextended('sec:acct:' || v_user_hash, 0));

  if random() < 0.01 then
    perform imobdesk.security_cleanup();
  end if;

  insert into imobdesk.security_auth_control (user_hash) values (v_user_hash) on conflict (user_hash) do nothing;
  select * into c from imobdesk.security_auth_control where user_hash = v_user_hash for update;
  select * into v_block from imobdesk.security_ip_blocks where ip_hash = v_ip_hash;

  -- Contagens ANTES desta tentativa.
  select count(*) filter (where a.created_at > v_now - interval '1 minute' and a.kind = p_kind),
         count(*) filter (where a.created_at > v_now - interval '15 minutes' and a.kind = p_kind),
         count(*) filter (where a.kind = p_kind),
         count(*) filter (where a.created_at > v_now - make_interval(secs => imobdesk.security_cfg('velocity_window_ms') / 1000.0)),
         count(*) filter (where a.kind = 'recover' and a.created_at > v_now - interval '15 minutes'),
         max(a.created_at)
    into v_ip_1m, v_ip_15m, v_ip_1h, v_ip_burst, v_ip_recover_15m, v_last_ip_attempt
  from imobdesk.security_attempts a
  where a.ip_hash = v_ip_hash and a.created_at > v_now - interval '1 hour';

  select count(*) filter (where a.ip_hash = v_ip_hash and a.created_at > v_now - interval '15 minutes' and a.kind = 'login'),
         count(*) filter (where a.created_at > v_now - interval '15 minutes' and a.kind = 'login'),
         count(*) filter (where a.kind = 'recover'),
         max(a.created_at) filter (where a.kind = 'login')
    into v_ipacc_15m, v_acc_15m, v_acc_recover_1h, v_last_acct_attempt
  from imobdesk.security_attempts a
  where a.user_hash = v_user_hash and a.created_at > v_now - interval '1 hour';

  -- Contas distintas por este IP (5 min) e IPs distintos nesta conta (15 min), contando a atual.
  select count(distinct u) into v_spray from (
    select a.user_hash as u from imobdesk.security_attempts a
    where a.ip_hash = v_ip_hash and a.created_at > v_now - interval '5 minutes'
    union select v_user_hash
  ) x;
  select count(distinct i) into v_dist from (
    select a.ip_hash as i from imobdesk.security_attempts a
    where a.user_hash = v_user_hash and a.created_at > v_now - interval '15 minutes' and a.kind = 'login'
    union select v_ip_hash
  ) x;

  -- ---------- Risco (sinais combinados; nenhum sinal isolado decide sozinho) ----------
  -- Sinais da CONTA (falhas, muitos IPs) e sinais do IP (rajada, muitas contas, paralelismo,
  -- bloqueio recente) somam no risco; mas só os do IP podem levar a bloquear o IP — senão um
  -- usuário errando a senha bloquearia todo o escritório atrás do mesmo NAT.
  if c.failed_attempts > 0 then
    v_risk := v_risk + least(c.failed_attempts * 10, 40); v_signals := array_append(v_signals, 'senha_invalida');
  end if;
  if v_dist >= 3 then
    v_risk := v_risk + 30; v_signals := array_append(v_signals, 'muitos_ips_mesma_conta');
  end if;
  if v_ip_1m >= 5 then
    v_ip_risk := v_ip_risk + 20; v_signals := array_append(v_signals, 'muitas_tentativas');
  end if;
  if v_spray >= 4 then
    v_ip_risk := v_ip_risk + 30; v_signals := array_append(v_signals, 'muitas_contas_mesmo_ip');
  end if;
  if v_ip_burst >= imobdesk.security_cfg('velocity_max') then
    v_ip_risk := v_ip_risk + 30; v_signals := array_append(v_signals, 'velocidade_anormal');
  end if;
  if c.inflight_until > v_now then
    v_ip_risk := v_ip_risk + 40; v_signals := array_append(v_signals, 'requisicoes_paralelas');
  end if;
  if v_block.ip_hash is not null and v_block.last_block_at > v_now - interval '24 hours' then
    v_ip_risk := v_ip_risk + 40; v_signals := array_append(v_signals, 'ip_bloqueado_recentemente');
  end if;
  v_risk := least(v_risk + v_ip_risk, 100);

  -- ---------- Decisão (primeira regra que nega vence) ----------
  if not p_domain_allowed then
    v_reason := 'SEC_AUTH_013'; v_event := 'LOGIN_BLOCKED'; v_severity := 'info';
  elsif v_block.blocked_until > v_now then
    v_reason := 'SEC_AUTH_004'; v_event := 'LOGIN_BLOCKED';
  elsif p_kind = 'recover' then
    if v_ip_recover_15m >= imobdesk.security_cfg('recover_ip_15m')
       or v_acc_recover_1h >= imobdesk.security_cfg('recover_account_1h') then
      v_reason := 'SEC_AUTH_020'; v_event := 'RATE_LIMIT_RECOVER';
    end if;
  elsif v_spray > imobdesk.security_cfg('spray_accounts_5m') then
    v_reason := 'SEC_AUTH_008'; v_event := 'PASSWORD_SPRAY_DETECTED'; v_severity := 'critical';
    perform imobdesk.security_block_ip(v_ip_hash, imobdesk.security_cfg('spray_block_min'), 'PASSWORD_SPRAY');
  elsif v_ip_1m >= imobdesk.security_cfg('ip_attempts_1m')
     or v_ip_15m >= imobdesk.security_cfg('ip_attempts_15m')
     or v_ip_1h >= imobdesk.security_cfg('ip_attempts_1h') then
    v_reason := 'SEC_AUTH_005'; v_event := 'RATE_LIMIT_IP';
  elsif c.locked_until > v_now then
    -- Bloqueada continua bloqueada mesmo com a senha certa: nem chega ao Auth.
    v_reason := 'SEC_AUTH_001'; v_event := 'LOGIN_BLOCKED';
  elsif c.inflight_until > v_now then
    v_reason := 'SEC_AUTH_003'; v_event := 'BOT_PATTERN';
  elsif c.next_allowed_at > v_now then
    v_reason := 'SEC_AUTH_002'; v_event := 'LOGIN_BLOCKED'; v_severity := 'info';
  elsif v_ipacc_15m >= imobdesk.security_cfg('ip_account_attempts_15m') then
    v_reason := 'SEC_AUTH_006'; v_event := 'RATE_LIMIT_IP_ACCOUNT';
  elsif v_dist > imobdesk.security_cfg('distributed_ips_15m') then
    -- Muitos IPs na mesma conta: a conta é bloqueada (independe do IP de onde vier a próxima).
    v_reason := 'SEC_AUTH_009'; v_event := 'DISTRIBUTED_ATTACK'; v_severity := 'critical';
    update imobdesk.security_auth_control
    set lock_level = c.lock_level + 1,
        locked_until = v_now + make_interval(mins => imobdesk.security_lock_minutes(c.lock_level + 1)),
        last_lock_at = v_now, updated_at = v_now
    where user_hash = v_user_hash;
  elsif v_acc_15m >= imobdesk.security_cfg('account_attempts_15m') then
    v_reason := 'SEC_AUTH_007'; v_event := 'RATE_LIMIT_ACCOUNT';
  elsif v_risk >= imobdesk.security_cfg('risk_critical') and v_ip_risk >= 30 then
    v_reason := 'SEC_AUTH_012'; v_event := 'BOT_PATTERN'; v_severity := 'critical';
    perform imobdesk.security_block_ip(v_ip_hash, imobdesk.security_cfg('risk_critical_block_min'), 'RISK_CRITICAL');
  elsif v_risk >= imobdesk.security_cfg('risk_block') and v_ip_risk >= 30 then
    v_reason := 'SEC_AUTH_011'; v_event := 'BOT_PATTERN';
    perform imobdesk.security_block_ip(v_ip_hash, imobdesk.security_cfg('risk_block_min'), 'RISK_BLOCK');
  elsif v_risk >= imobdesk.security_cfg('risk_cooldown')
     and greatest(v_last_ip_attempt, v_last_acct_attempt) > v_now - make_interval(secs => imobdesk.security_cfg('risk_cooldown_seconds')) then
    -- Risco médio (ou alto só por sinais da conta): exige intervalo mínimo entre tentativas.
    v_reason := 'SEC_AUTH_010'; v_event := 'LOGIN_BLOCKED'; v_severity := 'info';
  end if;

  update imobdesk.security_auth_control set risk_score = v_risk, updated_at = v_now where user_hash = v_user_hash;

  if v_reason is not null then
    insert into imobdesk.security_attempts (kind, ip_hash, user_hash, outcome, reason, risk_score, request_id, finished_at)
    values (p_kind, v_ip_hash, v_user_hash, 'denied', v_reason, v_risk, p_request_id, v_now);
    perform imobdesk.security_log_event(v_event, v_severity, p_request_id, v_ip_hash, v_ip, v_user_hash, c.user_id,
      v_email, v_reason, v_risk, jsonb_build_object('kind', p_kind, 'signals', to_jsonb(v_signals)));
    return jsonb_build_object('allowed', false, 'reason', v_reason, 'risk', v_risk);
  end if;

  -- Permitida: reserva a conta (uma tentativa por vez) e registra a tentativa em andamento.
  if p_kind = 'login' then
    update imobdesk.security_auth_control
    set inflight_until = v_now + make_interval(secs => imobdesk.security_cfg('account_inflight_seconds')), updated_at = v_now
    where user_hash = v_user_hash;
  end if;
  insert into imobdesk.security_attempts (kind, ip_hash, user_hash, outcome, risk_score, request_id)
  values (p_kind, v_ip_hash, v_user_hash, 'pending', v_risk, p_request_id)
  returning id into v_attempt;

  return jsonb_build_object('allowed', true, 'attempt_id', v_attempt, 'risk', v_risk);
end;
$$;

-- p_result: SUCCESS | INVALID_CREDENTIALS | ACCOUNT_UNAVAILABLE | AUTH_RATE_LIMITED | AUTH_ERROR
-- Só INVALID_CREDENTIALS conta como falha de senha.
create or replace function imobdesk.security_auth_finish(
  p_attempt_id uuid,
  p_result text,
  p_email text,
  p_ip text,
  p_user_id uuid default null,
  p_session_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_email text := imobdesk.security_normalize_email(p_email);
  a imobdesk.security_attempts;
  c imobdesk.security_auth_control;
  v_locked boolean := false;
  v_counted_by_hook boolean;
begin
  if p_result not in ('SUCCESS', 'INVALID_CREDENTIALS', 'ACCOUNT_UNAVAILABLE', 'AUTH_RATE_LIMITED', 'AUTH_ERROR') then
    raise exception 'security_auth_finish: resultado inválido';
  end if;

  select * into a from imobdesk.security_attempts where id = p_attempt_id;
  -- Uma tentativa só fecha uma vez (sem replay) e só com o mesmo e-mail que a abriu.
  if a.id is null or a.outcome <> 'pending' or a.user_hash <> imobdesk.security_hash('acct', v_email) then
    raise exception 'security_auth_finish: tentativa inexistente ou já concluída';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('sec:ip:' || a.ip_hash, 0));
  perform pg_advisory_xact_lock(hashtextextended('sec:acct:' || a.user_hash, 0));
  select * into a from imobdesk.security_attempts where id = p_attempt_id for update;
  if a.outcome <> 'pending' then
    raise exception 'security_auth_finish: tentativa já concluída';
  end if;
  select * into c from imobdesk.security_auth_control where user_hash = a.user_hash for update;

  if a.kind = 'recover' then
    update imobdesk.security_attempts
    set outcome = case when p_result = 'SUCCESS' then 'success' else 'error' end, reason = p_result, finished_at = v_now
    where id = a.id;
    perform imobdesk.security_log_event('PASSWORD_RESET', 'info', a.request_id, a.ip_hash, p_ip, a.user_hash, c.user_id,
      v_email, p_result, a.risk_score);
    return jsonb_build_object('ok', true);
  end if;

  if p_result = 'SUCCESS' then
    if p_user_id is null or p_session_id is null then
      raise exception 'security_auth_finish: sucesso sem usuário/sessão';
    end if;
    -- Zera só as falhas consecutivas. Nível de bloqueio, eventos e bloqueios de IP continuam.
    update imobdesk.security_auth_control
    set failed_attempts = 0, next_allowed_at = null, inflight_until = null,
        last_success_at = v_now, user_id = p_user_id, updated_at = v_now
    where user_hash = a.user_hash;
    insert into imobdesk.security_sessions (session_id, user_id, ip_hash)
    values (p_session_id, p_user_id, a.ip_hash)
    on conflict (session_id) do nothing;
    update imobdesk.security_attempts set outcome = 'success', finished_at = v_now where id = a.id;
    perform imobdesk.security_log_event('LOGIN_SUCCESS', 'info', a.request_id, a.ip_hash, p_ip, a.user_hash, p_user_id,
      v_email, null, a.risk_score);
    return jsonb_build_object('ok', true);
  end if;

  if p_result = 'INVALID_CREDENTIALS' then
    -- Com o hook do Auth ligado, ele já contou esta falha (e marcou last_hook_failure_at).
    v_counted_by_hook := imobdesk.security_cfg('hook_counts_failures') = 1
                         and c.last_hook_failure_at >= a.created_at;
    if v_counted_by_hook then
      update imobdesk.security_auth_control set inflight_until = null, updated_at = v_now where user_hash = a.user_hash;
      v_locked := (select x.locked_until > v_now from imobdesk.security_auth_control x where x.user_hash = a.user_hash);
    else
      v_locked := imobdesk.security_register_failure(a.user_hash, false);
    end if;
    update imobdesk.security_attempts set outcome = 'failure', reason = p_result, finished_at = v_now where id = a.id;
    perform imobdesk.security_log_event('LOGIN_FAILED', 'info', a.request_id, a.ip_hash, p_ip, a.user_hash, c.user_id,
      v_email, p_result, a.risk_score);
    if v_locked then
      perform imobdesk.security_log_event('LOGIN_BLOCKED', 'warning', a.request_id, a.ip_hash, p_ip, a.user_hash, c.user_id,
        v_email, 'SEC_AUTH_001', a.risk_score, jsonb_build_object('lock_level', (select x.lock_level from imobdesk.security_auth_control x where x.user_hash = a.user_hash)));
    end if;
    return jsonb_build_object('ok', true);
  end if;

  -- Erro que não é de senha (Auth fora, limite do próprio Auth, conta sem confirmação): libera a
  -- reserva, não conta falha, registra.
  update imobdesk.security_auth_control set inflight_until = null, updated_at = v_now where user_hash = a.user_hash;
  update imobdesk.security_attempts set outcome = 'error', reason = p_result, finished_at = v_now where id = a.id;
  perform imobdesk.security_log_event('LOGIN_FAILED', case when p_result = 'AUTH_ERROR' then 'warning' else 'info' end,
    a.request_id, a.ip_hash, p_ip, a.user_hash, c.user_id, v_email, p_result, a.risk_score);
  return jsonb_build_object('ok', true);
end;
$$;

-- O schema dá EXECUTE a authenticated por padrão (20261006141700_..._base.sql): revogar explicitamente.
revoke all on function
  imobdesk.security_normalize_email(text),
  imobdesk.security_mask_email(text),
  imobdesk.security_ip_prefix(text),
  imobdesk.security_cfg(text),
  imobdesk.security_hash(text, text),
  imobdesk.security_log_event(text, text, uuid, text, text, text, uuid, text, text, integer, jsonb),
  imobdesk.security_block_ip(text, integer, text),
  imobdesk.security_lock_minutes(integer),
  imobdesk.security_register_failure(text, boolean),
  imobdesk.security_cleanup(),
  imobdesk.security_auth_begin(text, text, text, uuid, boolean),
  imobdesk.security_auth_finish(uuid, text, text, text, uuid, uuid)
from public, anon, authenticated;
grant execute on function
  imobdesk.security_auth_begin(text, text, text, uuid, boolean),
  imobdesk.security_auth_finish(uuid, text, text, text, uuid, uuid),
  imobdesk.security_cleanup()
to service_role;

-- ============================================================================================
-- Sessão confiável: a RLS do portal só aceita sessão de senha emitida pelo gateway
-- ============================================================================================

-- Regra para uma sessão (user_id, session_id, amr do JWT):
--   * a sessão ainda existe no Auth (logout, "encerrar sessão" e troca de senha cortam na hora,
--     sem esperar o access token expirar);
--   * se o login foi por senha (amr contém "password"), a sessão tem de estar em security_sessions;
--   * login por link de e-mail (recovery/invite/otp) não passa por senha, então vale sem vínculo.
create or replace function imobdesk.security_sessao_valida(p_user_id uuid, p_session_id uuid, p_amr jsonb)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_user_id is not null and p_session_id is not null
    and exists (select 1 from auth.sessions s where s.id = p_session_id and s.user_id = p_user_id)
    and (
      not jsonb_path_exists(coalesce(p_amr, '[]'::jsonb), '$[*] ? (@.method == "password")')
      or exists (
        select 1 from imobdesk.security_sessions b
        where b.session_id = p_session_id and b.user_id = p_user_id and b.revoked_at is null
      )
    );
$$;

create or replace function imobdesk.sessao_confiavel()
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_claims jsonb := auth.jwt();
  v_sid uuid;
begin
  -- Sem JWT = conexão interna (migrations, cron). service_role = Edge Function, que valida a sessão do chamador em portalContext.
  if v_claims is null or v_claims ->> 'role' = 'service_role' then
    return true;
  end if;
  if v_claims ->> 'role' is distinct from 'authenticated' then
    return false;
  end if;
  begin
    v_sid := (v_claims ->> 'session_id')::uuid;
  exception when others then
    return false;
  end;
  return imobdesk.security_sessao_valida(auth.uid(), v_sid, v_claims -> 'amr');
end;
$$;

-- Para o front descobrir que a sessão salva no navegador não vale mais (ex.: aberta antes desta versão).
create or replace function imobdesk.sessao_atual_confiavel()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select imobdesk.sessao_confiavel();
$$;

revoke all on function imobdesk.security_sessao_valida(uuid, uuid, jsonb), imobdesk.sessao_confiavel(),
  imobdesk.sessao_atual_confiavel() from public, anon, authenticated;
grant execute on function imobdesk.sessao_confiavel(), imobdesk.sessao_atual_confiavel() to authenticated, service_role;
grant execute on function imobdesk.security_sessao_valida(uuid, uuid, jsonb) to service_role;

-- ============================================================================================
-- Depois da troca de senha (pelo link do e-mail ou pela tela "Trocar senha")
-- ============================================================================================

-- Quem provou ser dono da conta e trocou a senha sai do bloqueio; as outras sessões de senha
-- deixam de valer no portal (o front também chama signOut({ scope: "others" }) no Auth).
create or replace function imobdesk.security_apos_troca_senha()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_sid uuid;
  v_email text;
  v_hash text;
begin
  if v_uid is null or not imobdesk.sessao_confiavel() then
    perform imobdesk.erro('UNAUTHENTICATED', 'Sua sessão expirou. Entre novamente.');
  end if;
  begin
    v_sid := (auth.jwt() ->> 'session_id')::uuid;
  exception when others then
    v_sid := null;
  end;
  select imobdesk.security_normalize_email(u.email) into v_email from auth.users u where u.id = v_uid;
  v_hash := imobdesk.security_hash('acct', v_email);

  update imobdesk.security_auth_control
  set failed_attempts = 0, locked_until = null, next_allowed_at = null, inflight_until = null,
      user_id = v_uid, updated_at = now()
  where user_hash = v_hash;

  update imobdesk.security_sessions
  set revoked_at = now(), revoked_reason = 'password_changed'
  where user_id = v_uid and revoked_at is null and session_id is distinct from v_sid;

  perform imobdesk.security_log_event('SESSION_REVOKED', 'info', null, null, null, v_hash, v_uid, v_email,
    'PASSWORD_CHANGED', null, jsonb_build_object('scope', 'others'));
end;
$$;

revoke all on function imobdesk.security_apos_troca_senha() from public, anon;
grant execute on function imobdesk.security_apos_troca_senha() to authenticated;

-- ============================================================================================
-- Password Verification Hook do Supabase Auth (OPCIONAL, desligado por padrão)
-- ============================================================================================
--
-- O endpoint público do Auth (/auth/v1/token) continua aceitando senha direto com a chave pública,
-- e o projeto é compartilhado: não dá para desligá-lo. Sem o hook, quem chama o Auth direto
-- esbarra só no limite nativo do Auth por IP; a sessão obtida assim não abre o portal (RLS acima),
-- mas a tentativa serve para adivinhar senha. Com o hook ligado, o próprio Auth consulta este
-- bloqueio em TODA verificação de senha — inclusive as diretas — e passa a contar as falhas.
--
-- Ligar (decisão do dono do projeto compartilhado: vale para todos os sistemas da WSA):
--   Dashboard > Authentication > Hooks > Password Verification Attempt > Postgres >
--   imobdesk.security_password_verification_hook
--   e depois: update imobdesk.security_config set value = 1 where key = 'hook_counts_failures';
create or replace function imobdesk.security_password_verification_hook(event jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_uid uuid;
  v_valid boolean;
  v_email text;
  v_hash text;
  c imobdesk.security_auth_control;
  v_locked boolean;
begin
  v_uid := (event ->> 'user_id')::uuid;
  v_valid := coalesce((event ->> 'valid')::boolean, false);
  select imobdesk.security_normalize_email(u.email) into v_email from auth.users u where u.id = v_uid;
  if v_email is null or v_email = '' then
    return jsonb_build_object('decision', 'continue');
  end if;
  v_hash := imobdesk.security_hash('acct', v_email);

  perform pg_advisory_xact_lock(hashtextextended('sec:acct:' || v_hash, 0));
  insert into imobdesk.security_auth_control (user_hash, user_id) values (v_hash, v_uid)
  on conflict (user_hash) do update set user_id = excluded.user_id;
  select * into c from imobdesk.security_auth_control where user_hash = v_hash for update;

  if c.locked_until > v_now or (c.next_allowed_at > v_now and c.inflight_until is null) then
    perform imobdesk.security_log_event('LOGIN_BLOCKED', 'warning', null, null, null, v_hash, v_uid, v_email,
      'SEC_AUTH_001', c.risk_score, jsonb_build_object('source', 'auth_hook', 'valid', v_valid));
    return jsonb_build_object('decision', 'reject',
      'message', 'Não foi possível realizar o acesso. Verifique os dados informados ou tente novamente mais tarde.',
      'should_logout_user', false);
  end if;

  if not v_valid then
    v_locked := imobdesk.security_register_failure(v_hash, true);
    perform imobdesk.security_log_event(case when v_locked then 'LOGIN_BLOCKED' else 'LOGIN_FAILED' end,
      case when v_locked then 'warning' else 'info' end, null, null, null, v_hash, v_uid, v_email,
      'INVALID_CREDENTIALS', c.risk_score, jsonb_build_object('source', 'auth_hook'));
  end if;
  return jsonb_build_object('decision', 'continue');
end;
$$;

revoke all on function imobdesk.security_password_verification_hook(jsonb) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'supabase_auth_admin') then
    grant usage on schema imobdesk to supabase_auth_admin;
    grant execute on function imobdesk.security_password_verification_hook(jsonb) to supabase_auth_admin;
  end if;
end;
$$;

-- ============================================================================================
-- Higiene: funções de trigger não precisam de EXECUTE para PUBLIC/anon (o disparo não confere
-- esse privilégio). Achado do teste "anon não tem privilégio em nenhuma função do schema".
-- ============================================================================================
do $$
declare
  f record;
begin
  for f in
    select p.oid::regprocedure as sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'imobdesk' and p.prorettype = 'trigger'::regtype
  loop
    execute format('revoke execute on function %s from public, anon', f.sig);
  end loop;
end;
$$;

-- Helpers internos dos gatilhos (20261007210000_..._gatilhos.sql) ficaram com EXECUTE para PUBLIC/anon.
revoke execute on function imobdesk.ch_gatilho_em_execucao(), imobdesk.ch_gatilho_exigir_admin() from public, anon;

-- ======================================== 20261009120100_imobdesk_seguranca_sessao_obrigatoria.sql
-- Segurança do login, etapa 2 de 2: a RLS do portal passa a exigir sessão confiável.
--
-- Aplicar SÓ DEPOIS de publicar a Edge Function imobdesk-auth e o front que loga por ela
-- (ordem completa em docs/SEGURANCA-LOGIN.md). Antes disso, ninguém teria sessão registrada e o
-- portal ficaria sem acesso. Desfazer: recriar as duas funções sem a linha sessao_confiavel()
-- (versão em 20261006141704_..._funcoes_acesso.sql e 20261006141707_..._rpcs_base.sql).
--
-- As duas raízes da autorização do portal passam a exigir sessão confiável. Todas as policies e RPCs
-- usam uma delas (perfil_usuario_atual -> tem_permissao/eh_super_admin/usuario_portal_ativo;
-- perfil_de -> tem_permissao_de/pode_*), então uma sessão aberta direto no Auth não tem perfil no portal.
create or replace function imobdesk.perfil_usuario_atual()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select u.perfil_key
  from imobdesk.usuarios u
  where u.id = (select auth.uid())
    and u.status <> 'inactive'
    and imobdesk.sessao_confiavel();
$$;

create or replace function imobdesk.perfil_de(p_usuario uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select u.perfil_key
  from imobdesk.usuarios u
  where u.id = p_usuario and u.status <> 'inactive'
    and imobdesk.sessao_confiavel();
$$;

-- ======================================== 20261009150000_imobdesk_forma_atendimento_canal.sql
-- Forma de atendimento pelo canal (09/10/2026, pedido do Wagner): ticket que entra por e-mail ou WhatsApp já nasce
-- com o campo adicional "forma_atendimento" preenchido (E-mail / WhatsApp). É o canal de entrada, então não depende
-- do modelo nem de confiança: a regra é determinística. Telefone, Presencial e Acesso remoto não têm canal automático
-- (o agente abre o ticket e escolhe). Só preenche se estiver vazio — escolha manual nunca é sobrescrita. Só aditiva.

create or replace function imobdesk.ch_forma_atendimento_do_canal(p_origem text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_origem when 'email' then 'E-mail' when 'whatsapp' then 'WhatsApp' end;
$$;

create or replace function imobdesk.ch_tickets_forma_atendimento()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_forma text := imobdesk.ch_forma_atendimento_do_canal(new.origem);
begin
  if v_forma is not null and coalesce(btrim(new.campos ->> 'forma_atendimento'), '') = '' then
    new.campos := coalesce(new.campos, '{}') || jsonb_build_object('forma_atendimento', v_forma);
  end if;
  return new;
end;
$$;

drop trigger if exists ch_tickets_forma_atendimento on imobdesk.ch_tickets;
create trigger ch_tickets_forma_atendimento before insert on imobdesk.ch_tickets
for each row execute function imobdesk.ch_tickets_forma_atendimento();

-- Linha do tempo: registra a classificação. Prefixo "z_" para disparar depois de ch_tickets_historico ("Ticket criado").
create or replace function imobdesk.ch_tickets_forma_atendimento_evento()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if imobdesk.ch_forma_atendimento_do_canal(new.origem) = new.campos ->> 'forma_atendimento' then
    insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_nome)
    values (new.id, 'ia', format('Forma de atendimento: %s (canal de entrada)', new.campos ->> 'forma_atendimento'), 'IA');
  end if;
  return null;
end;
$$;

drop trigger if exists ch_tickets_z_forma_atendimento_evento on imobdesk.ch_tickets;
create trigger ch_tickets_z_forma_atendimento_evento after insert on imobdesk.ch_tickets
for each row execute function imobdesk.ch_tickets_forma_atendimento_evento();

revoke execute on function imobdesk.ch_tickets_forma_atendimento() from public, anon, authenticated;
revoke execute on function imobdesk.ch_tickets_forma_atendimento_evento() from public, anon, authenticated;

-- Tickets já abertos por e-mail/WhatsApp com o campo vazio. Sem os gatilhos de histórico e automação, para não
-- gerar "Campos adicionais alterados" nem disparar regras por uma correção de dado; o evento é gravado aqui.
alter table imobdesk.ch_tickets disable trigger ch_tickets_historico;
alter table imobdesk.ch_tickets disable trigger ch_tickets_gatilho_anotar;

with corrigidos as (
  update imobdesk.ch_tickets t
     set campos = coalesce(t.campos, '{}') || jsonb_build_object('forma_atendimento', imobdesk.ch_forma_atendimento_do_canal(t.origem))
   where t.origem in ('email', 'whatsapp')
     and coalesce(btrim(t.campos ->> 'forma_atendimento'), '') = ''
  returning t.id, t.campos ->> 'forma_atendimento' as forma
)
insert into imobdesk.ch_ticket_eventos (ticket_id, tipo, descricao, autor_nome)
select c.id, 'ia', format('Forma de atendimento: %s (canal de entrada)', c.forma), 'IA' from corrigidos c;

alter table imobdesk.ch_tickets enable trigger ch_tickets_historico;
alter table imobdesk.ch_tickets enable trigger ch_tickets_gatilho_anotar;

-- ======================================== 20261009150100_imobdesk_email_so_dominio.sql
-- E-mail "Só domínio" (docs/PLANO-conversas-whatsapp-openwa.md, Fase 1; aprovado pelo Wagner em 09/10/2026).
-- TI, Administrativo e CFTV só abrem ticket por remetente do domínio da empresa. A regra "cliente_ou_dominio" aceitava
-- também qualquer pessoa cadastrada (até de fora); a nova regra "dominio" olha só o domínio do remetente.
-- Respostas a tickets que já existem continuam entrando (a checagem é só para ticket novo).
-- Só aditiva: o check de abrir_tickets ganha um valor, coluna nova e as três funções trocadas (mesma assinatura).

alter table imobdesk.at_email_contas add column if not exists dominios_permitidos text[] not null default '{}';
alter table imobdesk.at_email_contas drop constraint if exists at_email_contas_abrir_tickets_check;
alter table imobdesk.at_email_contas add constraint at_email_contas_abrir_tickets_check
  check (abrir_tickets in ('qualquer', 'cliente', 'cliente_ou_dominio', 'dominio', 'nao'));

create or replace function imobdesk.at_email_contas_lista()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id, 'nome', c.nome, 'email', c.email, 'setorId', c.setor_id, 'setorNome', s.nome,
    'nomeRemetente', c.nome_remetente, 'exibirNoEnvio', c.exibir_no_envio, 'padraoDoSetor', c.padrao_do_setor,
    'usarLogo', c.usar_logo, 'logoPath', c.logo_path, 'habilitada', c.habilitada,
    'provedor', c.provedor, 'modo', c.modo,
    'imapHost', c.imap_host, 'imapPorta', c.imap_porta, 'imapSeguranca', c.imap_seguranca,
    'smtpHost', c.smtp_host, 'smtpPorta', c.smtp_porta, 'usuario', c.usuario,
    'senhaMascara', c.senha_mascara,
    'pasta', c.pasta, 'intervaloMin', c.intervalo_min, 'lerDesde', c.ler_desde,
    'marcarLido', c.marcar_lido, 'moverPara', c.mover_para, 'juntarRespostas', c.juntar_respostas,
    'ignorarRemetentes', to_jsonb(c.ignorar_remetentes),
    'responderPara', c.responder_para, 'copiaOculta', c.copia_oculta, 'assinatura', c.assinatura,
    'receberHabilitado', c.receber_habilitado, 'apagarAposDias', c.apagar_apos_dias, 'abrirTickets', c.abrir_tickets, 'dominiosPermitidos', to_jsonb(c.dominios_permitidos),
    'oauthEmail', c.oauth_email, 'oauthAutorizadoEm', c.oauth_autorizado_em,
    'oauthAutorizadoPor', (select u.nome from imobdesk.usuarios u where u.id = c.oauth_autorizado_por),
    'status', c.status, 'ultimoErro', c.ultimo_erro, 'ultimaLeituraEm', c.ultima_leitura_em, 'verificacao', c.verificacao,
    'naFila', (select count(*) from imobdesk.at_email_recebidos r where r.conta_id = c.id and r.estado = 'pendente')
  ) order by c.email), '[]')
  from imobdesk.at_email_contas c
  left join imobdesk.at_setores s on s.id = c.setor_id
  where imobdesk.at_supervisor() or (c.setor_id is not null and imobdesk.at_gestor_de(c.setor_id));
$$;

create or replace function imobdesk.at_email_conta_salvar(p jsonb)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := auth.uid();
  v_id bigint := nullif(p ->> 'id', '')::bigint;
  v_email text := lower(btrim(coalesce(p ->> 'email', '')));
  v_setor bigint := nullif(p ->> 'setorId', '')::bigint;
  v_modo text := coalesce(p ->> 'modo', 'oauth_google');
  v_antes jsonb;
  v_ignorar text[];
  v_dominios text[];
begin
  if v_ator is null or not imobdesk.at_supervisor() then
    perform imobdesk.erro('FORBIDDEN', 'Só a supervisão geral cadastra contas de e-mail.');
  end if;
  if length(btrim(coalesce(p ->> 'nome', ''))) not between 2 and 80 then
    perform imobdesk.erro('INVALID_INPUT', 'Informe o nome da conta (2 a 80 letras).', 'nome');
  end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    perform imobdesk.erro('INVALID_INPUT', 'Endereço de e-mail inválido.', 'email');
  end if;
  if exists (select 1 from imobdesk.at_email_contas c where c.email = v_email and c.id is distinct from v_id) then
    perform imobdesk.erro('DUPLICATE', 'Já existe uma conta com esse endereço.', 'email');
  end if;
  -- Setor é opcional: a conta existe só com a autorização do Google; o vínculo com a equipe/setor vem depois.
  if v_setor is not null and not exists (select 1 from imobdesk.at_setores s where s.id = v_setor) then
    perform imobdesk.erro('INVALID_INPUT', 'Setor não encontrado.', 'setorId');
  end if;
  if v_modo not in ('oauth_google', 'api_google', 'imap_smtp') then
    perform imobdesk.erro('INVALID_INPUT', 'Modo de acesso inválido.', 'modo');
  end if;
  if v_modo in ('oauth_google', 'api_google') and coalesce(p ->> 'provedor', 'google') <> 'google' then
    perform imobdesk.erro('INVALID_INPUT', 'A autorização pelo Google só existe para contas do Google Workspace / Gmail.', 'modo');
  end if;
  if v_modo = 'imap_smtp' and (nullif(btrim(p ->> 'imapHost'), '') is null or nullif(btrim(p ->> 'smtpHost'), '') is null) then
    perform imobdesk.erro('INVALID_INPUT', 'Informe os servidores de entrada (IMAP) e de saída (SMTP).', 'imapHost');
  end if;
  if (p ->> 'smtpPorta')::int in (25, 587) then
    perform imobdesk.erro('INVALID_INPUT', 'Use a porta 465 (SSL): o servidor do portal bloqueia as portas 25 e 587.', 'smtpPorta');
  end if;
  if (p ->> 'apagarAposDias') is not null and (p ->> 'apagarAposDias')::int not between 1 and 3650 then
    perform imobdesk.erro('INVALID_INPUT', 'Informe de 1 a 3650 dias para apagar as mensagens processadas.', 'apagarAposDias');
  end if;
  select coalesce(array_agg(lower(btrim(x))) filter (where btrim(x) <> ''), '{}') into v_ignorar
  from jsonb_array_elements_text(coalesce(p -> 'ignorarRemetentes', '[]')) x;

  -- "Só domínio": domínios sem @, minúsculos; ao menos um quando a regra for essa.
  if p ? 'dominiosPermitidos' then
    select coalesce(array_agg(distinct d) filter (where d <> ''), '{}') into v_dominios
    from (select lower(btrim(ltrim(btrim(x), '@'))) d from jsonb_array_elements_text(coalesce(p -> 'dominiosPermitidos', '[]')) x) y;
    if exists (select 1 from unnest(v_dominios) d where d !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$') then
      perform imobdesk.erro('INVALID_INPUT', 'Domínio inválido. Use só o domínio, como suaempresa.com.br.', 'dominiosPermitidos');
    end if;
  end if;
  if p ->> 'abrirTickets' = 'dominio'
     and cardinality(coalesce(v_dominios, (select c.dominios_permitidos from imobdesk.at_email_contas c where c.id = v_id), '{}')) = 0 then
    perform imobdesk.erro('INVALID_INPUT', 'Informe ao menos um domínio para a regra "Só domínio".', 'dominiosPermitidos');
  end if;

  if v_setor is not null and (p ->> 'padraoDoSetor')::boolean then
    update imobdesk.at_email_contas set padrao_do_setor = false
    where setor_id = v_setor and padrao_do_setor and id is distinct from v_id;
  end if;

  begin
    if v_id is null then
      insert into imobdesk.at_email_contas (nome, email, setor_id, modo, atualizado_por) values (btrim(p ->> 'nome'), v_email, v_setor, v_modo, v_ator)
      returning id into v_id;
    else
      select to_jsonb(c) - 'senha_segredo_id' - 'oauth_segredo_id' - 'cursor' into v_antes from imobdesk.at_email_contas c where c.id = v_id;
      if v_antes is null then
        perform imobdesk.erro('NOT_FOUND', 'Conta não encontrada.');
      end if;
      -- Trocou o endereço: o token do Google era da caixa antiga e sai do Vault.
      if v_antes ->> 'email' is distinct from v_email then
        delete from vault.secrets where id = (select c.oauth_segredo_id from imobdesk.at_email_contas c where c.id = v_id);
      end if;
    end if;
    update imobdesk.at_email_contas c set
      nome = btrim(p ->> 'nome'),
      email = v_email,
      setor_id = v_setor,
      nome_remetente = nullif(btrim(p ->> 'nomeRemetente'), ''),
      exibir_no_envio = coalesce((p ->> 'exibirNoEnvio')::boolean, c.exibir_no_envio),
      padrao_do_setor = v_setor is not null and coalesce((p ->> 'padraoDoSetor')::boolean, c.padrao_do_setor),
      usar_logo = coalesce((p ->> 'usarLogo')::boolean, c.usar_logo),
      habilitada = coalesce((p ->> 'habilitada')::boolean, c.habilitada),
      provedor = coalesce(p ->> 'provedor', c.provedor),
      modo = v_modo,
      imap_host = nullif(btrim(p ->> 'imapHost'), ''),
      imap_porta = coalesce((p ->> 'imapPorta')::int, c.imap_porta),
      imap_seguranca = coalesce(p ->> 'imapSeguranca', c.imap_seguranca),
      smtp_host = nullif(btrim(p ->> 'smtpHost'), ''),
      smtp_porta = coalesce((p ->> 'smtpPorta')::int, c.smtp_porta),
      usuario = nullif(btrim(p ->> 'usuario'), ''),
      pasta = coalesce(nullif(btrim(p ->> 'pasta'), ''), 'INBOX'),
      intervalo_min = coalesce((p ->> 'intervaloMin')::int, c.intervalo_min),
      ler_desde = coalesce((p ->> 'lerDesde')::date, c.ler_desde),
      marcar_lido = coalesce((p ->> 'marcarLido')::boolean, c.marcar_lido),
      mover_para = nullif(btrim(p ->> 'moverPara'), ''),
      juntar_respostas = coalesce((p ->> 'juntarRespostas')::boolean, c.juntar_respostas),
      ignorar_remetentes = v_ignorar,
      responder_para = nullif(lower(btrim(p ->> 'responderPara')), ''),
      copia_oculta = nullif(lower(btrim(p ->> 'copiaOculta')), ''),
      assinatura = nullif(p ->> 'assinatura', ''),
      receber_habilitado = coalesce((p ->> 'receberHabilitado')::boolean, c.receber_habilitado),
      apagar_apos_dias = case when p ? 'apagarAposDias' then (p ->> 'apagarAposDias')::int else c.apagar_apos_dias end,
      abrir_tickets = coalesce(nullif(p ->> 'abrirTickets', ''), c.abrir_tickets),
      dominios_permitidos = coalesce(v_dominios, c.dominios_permitidos),
      -- Trocou o endereço: a autorização do Google era de outra caixa.
      oauth_segredo_id = case when v_antes is not null and v_antes ->> 'email' is distinct from v_email then null else c.oauth_segredo_id end,
      oauth_email = case when v_antes is not null and v_antes ->> 'email' is distinct from v_email then null else c.oauth_email end,
      status = case when v_antes is null or v_antes ->> 'modo' is distinct from v_modo
                         or v_antes ->> 'imap_host' is distinct from nullif(btrim(p ->> 'imapHost'), '')
                         or v_antes ->> 'email' is distinct from v_email then 'aguardando' else c.status end,
      atualizado_em = now(),
      atualizado_por = v_ator
    where c.id = v_id;
  exception when check_violation then
    perform imobdesk.erro('INVALID_INPUT', 'Algum valor está fora do permitido (porta, intervalo, provedor, regra de abertura ou tamanho do texto).');
  end;

  perform imobdesk.registrar_auditoria(v_ator, 'atendimento', case when v_antes is null then 'create' else 'update' end,
    format('Conta de e-mail %s %s', v_email, case when v_antes is null then 'criada' else 'alterada' end),
    v_antes, (select to_jsonb(c) - 'senha_segredo_id' - 'oauth_segredo_id' - 'cursor' from imobdesk.at_email_contas c where c.id = v_id), v_id::text);
  return v_id;
end;
$$;

create or replace function imobdesk.ch_email_processar(p_recebido bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  r imobdesk.at_email_recebidos;
  c imobdesk.at_email_contas;
  t imobdesk.ch_tickets;
  v_ticket bigint;
  v_cat text;
  v_ids text[];
  v_pessoa bigint;
  v_num int;
  v_dominio text;
  v_motivo text;
  v_status bigint;
begin
  select * into r from imobdesk.at_email_recebidos x where x.id = p_recebido for update;
  if r.id is null or r.estado <> 'pendente' then
    return jsonb_build_object('estado', coalesce(r.estado, 'inexistente'), 'ticketId', r.ticket_id);
  end if;
  select * into c from imobdesk.at_email_contas x where x.id = r.conta_id;

  -- 1) É resposta a um ticket?
  v_ticket := nullif(substring(coalesce(r.assunto, '') from '\[#(\d{1,12})\]'), '')::bigint;
  if v_ticket is not null and not exists (select 1 from imobdesk.ch_tickets x where x.id = v_ticket and x.excluido_em is null) then
    v_ticket := null;
  end if;
  if v_ticket is null then
    v_ids := array(select m[1] from regexp_matches(coalesce(r.in_reply_to, '') || ' ' || coalesce(r.referencias, ''), '(<[^<>[:space:]]+>)', 'g') m);
    if cardinality(v_ids) > 0 then
      select a.ticket_id into v_ticket from imobdesk.ch_ticket_acoes a
       where a.email_message_id = any (v_ids) order by a.id desc limit 1;
      if v_ticket is null then
        select x.id into v_ticket from imobdesk.ch_tickets x
         where x.email_thread_id = any (v_ids) and x.excluido_em is null order by x.id desc limit 1;
      end if;
    end if;
  end if;
  -- Ticket mesclado: a resposta cai no destino.
  while v_ticket is not null loop
    select * into t from imobdesk.ch_tickets x where x.id = v_ticket;
    exit when t.mesclado_em_id is null;
    v_ticket := t.mesclado_em_id;
  end loop;

  if v_ticket is not null then
    v_cat := (select s.categoria from imobdesk.ch_status s where s.id = t.status_id);
    if v_cat in ('fechado', 'cancelado') then
      v_ticket := null;   -- encerrado de vez: abre ticket novo
    else
      perform 1 from imobdesk.ch_tickets x where x.id = v_ticket for update;
      v_num := coalesce((select max(a.numero) from imobdesk.ch_ticket_acoes a where a.ticket_id = v_ticket), 0) + 1;
      insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_nome, texto, html, anexos, envio_status, email_message_id)
      values (v_ticket, v_num, 'publica', 'email', 'entrada', coalesce(nullif(btrim(r.de_nome), ''), r.de), left(coalesce(r.texto, ''), 100000), r.html, r.anexos,
              'nao_se_aplica', r.message_id);
      if v_cat = 'resolvido' then
        v_status := coalesce((select s.id from imobdesk.ch_status s where s.categoria = 'andamento' and s.ativo and lower(s.nome) = 'reaberto' limit 1),
                             (select s.id from imobdesk.ch_status s where s.categoria = 'andamento' and s.ativo order by s.ordem limit 1));
      elsif v_cat = 'pendente' then
        v_status := (select s.id from imobdesk.ch_status s where s.categoria = 'andamento' and s.ativo order by s.ordem limit 1);
      end if;
      if v_status is not null then
        update imobdesk.ch_tickets set status_id = v_status, justificativa_id = null where id = v_ticket;
      end if;
      update imobdesk.at_email_recebidos set estado = 'virou_chamado', ticket_id = v_ticket, motivo = format('resposta no ticket #%s', v_ticket) where id = r.id;
      return jsonb_build_object('estado', 'virou_chamado', 'ticketId', v_ticket, 'motivo', 'resposta');
    end if;
  end if;

  -- 2) Ticket novo: regra de abertura da conta.
  v_dominio := split_part(r.de, '@', 2);
  if c.abrir_tickets = 'nao' then
    v_motivo := 'a conta não abre tickets novos';
  elsif c.abrir_tickets = 'dominio' and not (lower(v_dominio) = any (c.dominios_permitidos)) then
    v_motivo := 'remetente fora de ' || coalesce(array_to_string(array(select '@' || d from unnest(c.dominios_permitidos) d), ', '), 'domínio permitido');
  elsif c.abrir_tickets in ('cliente', 'cliente_ou_dominio')
        and not exists (select 1 from imobdesk.at_pessoa_contatos pc where pc.tipo = 'email' and pc.valor = r.de)
        and not (c.abrir_tickets = 'cliente_ou_dominio'
                 and exists (select 1 from imobdesk.at_pessoas e where e.tipo <> 'pessoa' and e.habilitada and v_dominio = any (e.dominios))) then
    v_motivo := case when c.abrir_tickets = 'cliente' then 'remetente não cadastrado em Pessoas' else 'remetente nem domínio cadastrados em Pessoas' end;
  elsif c.setor_id is null then
    v_motivo := 'a conta de e-mail não tem setor';
  end if;
  if v_motivo is not null then
    update imobdesk.at_email_recebidos set estado = 'ignorado', motivo = v_motivo where id = r.id;
    return jsonb_build_object('estado', 'ignorado', 'motivo', v_motivo);
  end if;

  v_pessoa := imobdesk.at_pessoa_identificar('email', r.de, r.de_nome, 'E-mail para ' || c.email);
  insert into imobdesk.ch_tickets (assunto, origem, recebido_em, solicitante_pessoa_id, solicitante_nome, solicitante_contato, email_conta_id,
                                             email_thread_id, setor_id, categoria_id, urgencia_id, status_id, cc)
  values (left(coalesce(nullif(btrim(r.assunto), ''), '(sem assunto)'), 300), 'email', left(c.email, 160), v_pessoa,
          left(coalesce(nullif(btrim(r.de_nome), ''), (select pe.nome from imobdesk.at_pessoas pe where pe.id = v_pessoa), r.de), 160), r.de, c.id,
          r.message_id, c.setor_id,
          (select x.id from imobdesk.ch_categorias x where x.padrao and x.ativa limit 1),
          coalesce((select u.id from imobdesk.ch_urgencias u where u.padrao and u.ativa limit 1), (select min(u.id) from imobdesk.ch_urgencias u)),
          coalesce((select s.id from imobdesk.ch_status s where s.categoria = 'novo' and s.ativo order by s.ordem limit 1), 1),
          coalesce(array(select x from unnest(r.para || r.cc) x where x <> c.email and x <> coalesce(c.oauth_email, '') and x <> r.de), '{}'))
  returning id into v_ticket;
  insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_nome, texto, html, anexos, envio_status, email_message_id)
  values (v_ticket, 1, 'publica', 'email', 'entrada', coalesce(nullif(btrim(r.de_nome), ''), r.de), left(coalesce(r.texto, ''), 100000), r.html, r.anexos,
          'nao_se_aplica', r.message_id);
  update imobdesk.at_email_recebidos set estado = 'virou_chamado', ticket_id = v_ticket, pessoa_id = v_pessoa, motivo = 'ticket novo' where id = r.id;
  return jsonb_build_object('estado', 'virou_chamado', 'ticketId', v_ticket, 'motivo', 'novo');
end;
$$;

-- ======================================== 20261009150200_imobdesk_whatsapp_motor.sql
-- Motor do chat do WhatsApp (docs/PLANO-conversas-whatsapp-openwa.md, Fase 2; mockup aprovado em 09/10/2026).
-- Uma entrada só para a Zenvia e o OpenWA (at_whatsapp_receber), identificação do colaborador no 1º contato,
-- fila com roleta, um ticket por atendimento (abre ao entrar na fila), ações do atendente (at_conversa_acao) e o
-- ciclo do pg_cron (at_whatsapp_ciclo). Tudo o que sai fica pendente (at_mensagens / at_repasses) e a Edge
-- imobdesk-whatsapp envia pelo canal do número. Só aditiva.

-- ======================================================================= estrutura

-- Número: canal de envio. OpenWA = sessão do número do sistema + grupo interno só de atendentes (opção A).
alter table imobdesk.at_numeros add column if not exists canal text not null default 'zenvia';
alter table imobdesk.at_numeros drop constraint if exists at_numeros_canal_check;
alter table imobdesk.at_numeros add constraint at_numeros_canal_check check (canal in ('zenvia', 'openwa'));
alter table imobdesk.at_numeros add column if not exists openwa_sessao text;
alter table imobdesk.at_numeros add column if not exists grupo_interno text;          -- id do grupo (…@g.us)
alter table imobdesk.at_numeros add column if not exists grupo_interno_nome text;
create unique index if not exists at_numeros_openwa_sessao_uidx on imobdesk.at_numeros (openwa_sessao) where openwa_sessao is not null and ativo;

-- Setor: identificação do colaborador e "só linha corporativa".
alter table imobdesk.at_setores add column if not exists wa_identificar boolean not null default false;
alter table imobdesk.at_setores add column if not exists wa_so_corporativo boolean not null default false;
alter table imobdesk.at_setores add column if not exists msg_nao_corporativo text not null
  default 'Este canal atende apenas linhas corporativas da empresa. Envie sua solicitação por e-mail.'
  check (length(msg_nao_corporativo) between 1 and 1000);

-- Atendente: WhatsApp pessoal (identifica quem responde no grupo interno).
alter table imobdesk.at_atendentes add column if not exists whatsapp text check (whatsapp ~ '^\d{10,15}$');
alter table imobdesk.at_atendentes add column if not exists grupo_dica_em timestamptz;
create unique index if not exists at_atendentes_whatsapp_uidx on imobdesk.at_atendentes (whatsapp) where whatsapp is not null;

-- Domínios aceitos no e-mail informado na identificação.
alter table imobdesk.at_config add column if not exists dominios_corporativos text[] not null default '{}';

-- Linhas (números de WhatsApp) conhecidas: corporativas (planilha da operadora) e as confirmadas no 1º contato.
create table if not exists imobdesk.at_linhas (
  numero          text        primary key check (numero ~ '^\d{10,15}$'),
  pessoa_id       bigint      references imobdesk.at_pessoas (id) on delete set null,
  corporativa     boolean     not null default true,
  confirmado_em   timestamptz,                              -- o colaborador confirmou nome e e-mail
  observacao      text        check (length(observacao) <= 200),
  criado_em       timestamptz not null default now(),
  atualizado_em   timestamptz not null default now(),
  atualizado_por  uuid
);
create index if not exists at_linhas_pessoa_idx on imobdesk.at_linhas (pessoa_id);

-- Conversa: estado da identificação (modo 'robo') e controle do aviso "não é linha corporativa".
alter table imobdesk.at_conversas add column if not exists ident jsonb;
alter table imobdesk.at_conversas add column if not exists aviso_nao_corporativo_em timestamptz;

-- Atendimento ↔ ticket (um ticket por atendimento; o mesmo ticket continua se ainda estiver aberto).
alter table imobdesk.at_atendimentos add column if not exists ticket_id bigint references imobdesk.ch_tickets (id) on delete set null;
create index if not exists at_atendimentos_ticket_idx on imobdesk.at_atendimentos (ticket_id);

-- Mensagem: id no OpenWA e controle de envio (reserva contra envio duplo e tentativas).
alter table imobdesk.at_mensagens add column if not exists externo_id text;
alter table imobdesk.at_mensagens add column if not exists envio_tentativas int not null default 0;
alter table imobdesk.at_mensagens add column if not exists envio_reservado_ate timestamptz;
create unique index if not exists at_mensagens_externo_uidx on imobdesk.at_mensagens (externo_id) where externo_id is not null;
create index if not exists at_mensagens_pendentes_idx on imobdesk.at_mensagens (criado_em) where status = 'pendente';

-- Repasses para o grupo interno dos atendentes (OpenWA). A resposta que CITA um repasse vai para o colaborador.
create table if not exists imobdesk.at_repasses (
  id                   bigint      generated always as identity primary key,
  numero_id            bigint      not null references imobdesk.at_numeros (id),
  conversa_id          bigint      references imobdesk.at_conversas (id) on delete set null,
  ticket_id            bigint      references imobdesk.ch_tickets (id) on delete set null,
  tipo                 text        not null check (tipo in ('novo', 'mensagem', 'enviado', 'aviso')),
  texto                text        not null check (length(texto) between 1 and 4000),
  citar_externo_id     text,
  status               text        not null default 'pendente' check (status in ('pendente', 'enviada', 'falhou')),
  externo_id           text,
  envio_tentativas     int         not null default 0,
  envio_reservado_ate  timestamptz,
  erro                 text,
  criado_em            timestamptz not null default now()
);
create index if not exists at_repasses_pendentes_idx on imobdesk.at_repasses (criado_em) where status = 'pendente';
create index if not exists at_repasses_externo_idx on imobdesk.at_repasses (externo_id) where externo_id is not null;
create index if not exists at_repasses_conversa_idx on imobdesk.at_repasses (conversa_id);

do $$
declare
  t text;
begin
  foreach t in array array['at_linhas', 'at_repasses'] loop
    execute format('alter table imobdesk.%I enable row level security', t);
    execute format('revoke all on imobdesk.%I from anon, public, authenticated', t);
    execute format('grant all on imobdesk.%I to service_role', t);
  end loop;
end;
$$;

-- ======================================================================= utilitários

/** Status de ticket por categoria; para 'andamento', prefere o nome dado (ex.: 'Em atendimento', 'Reaberto'). */
create or replace function imobdesk.ch_status_de(p_categoria text, p_nome text default null)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select s.id from imobdesk.ch_status s
  where s.categoria = p_categoria and s.ativo
  order by (p_nome is not null and lower(s.nome) = lower(p_nome)) desc, (lower(s.nome) = 'reaberto'), s.ordem
  limit 1;
$$;

/** Setor aberto agora (horário do setor, fuso de Brasília). */
create or replace function imobdesk.at_dentro_horario(p_setor bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((
    select h.aberto and (now() at time zone 'America/Sao_Paulo')::time >= h.abre and (now() at time zone 'America/Sao_Paulo')::time < h.fecha
    from imobdesk.at_horarios h
    where h.setor_id = p_setor and h.dia = extract(dow from now() at time zone 'America/Sao_Paulo')::int
  ), false);
$$;

/** Respostas automáticas valem para este telefone? (Zenvia › "ligado" e trava do piloto.) */
create or replace function imobdesk.at_auto_permitido(p_telefone text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select c.ligado and (not c.trava_piloto or p_telefone = any (c.telefones_piloto)) from imobdesk.at_config c where c.id), false);
$$;

/** Primeiro nome para as mensagens ("Vinicius Jose De Almeida Carvalho" → "Vinicius"). */
create or replace function imobdesk.at_primeiro_nome(p_nome text)
returns text
language sql
immutable
set search_path = ''
as $$
  select nullif(split_part(btrim(coalesce(p_nome, '')), ' ', 1), '');
$$;

/** Mensagem de sistema na conversa (linha do tempo do chat; não sai para o cliente). */
create or replace function imobdesk.at_evento(p_conversa bigint, p_texto text)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into imobdesk.at_mensagens (conversa_id, atendimento_id, direcao, autor, tipo, texto, status)
  select c.id, c.atendimento_id, 'interna', 'sistema', 'evento', left(p_texto, 1000), 'recebida'
  from imobdesk.at_conversas c where c.id = p_conversa;
$$;

/** Resposta automática pendente (sai pelo despachante). Respeita "ligado" e a trava do piloto. */
create or replace function imobdesk.at_auto(p_conversa bigint, p_texto text)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  c imobdesk.at_conversas;
  v_id bigint;
begin
  select * into c from imobdesk.at_conversas x where x.id = p_conversa;
  if c.id is null or nullif(btrim(p_texto), '') is null or not imobdesk.at_auto_permitido(c.telefone) then
    return null;
  end if;
  insert into imobdesk.at_mensagens (conversa_id, atendimento_id, direcao, autor, tipo, texto, status)
  values (c.id, c.atendimento_id, 'saida', 'auto', 'texto', left(p_texto, 4000), 'pendente')
  returning id into v_id;
  return v_id;
end;
$$;

/** Repasse para o grupo interno do número (só OpenWA com grupo configurado). */
create or replace function imobdesk.at_repassar(p_conversa bigint, p_ticket bigint, p_tipo text, p_texto text, p_citar text default null)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into imobdesk.at_repasses (numero_id, conversa_id, ticket_id, tipo, texto, citar_externo_id)
  select n.id, c.id, p_ticket, p_tipo, left(p_texto, 4000), p_citar
  from imobdesk.at_conversas c
  join imobdesk.at_numeros n on n.id = c.numero_id
  where c.id = p_conversa and n.canal = 'openwa' and n.grupo_interno is not null;
$$;

/** Nome de quem fala na conversa: pessoa identificada, nome do WhatsApp ou o telefone. */
create or replace function imobdesk.at_nome_da_conversa(c imobdesk.at_conversas)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select p.nome from imobdesk.at_pessoas p where p.id = c.pessoa_id), nullif(btrim(c.nome_contato), ''), '+' || c.telefone);
$$;

/** Ticket do atendimento atual da conversa. */
create or replace function imobdesk.at_ticket_da_conversa(p_conversa bigint)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select a.ticket_id from imobdesk.at_conversas c
  join imobdesk.at_atendimentos a on a.id = c.atendimento_id
  where c.id = p_conversa;
$$;

/** Ação no ticket ligada a uma mensagem do WhatsApp (entrada do colaborador ou resposta do atendente). */
create or replace function imobdesk.at_ticket_acao(p_ticket bigint, p_direcao text, p_autor uuid, p_autor_nome text, p_texto text, p_mensagem bigint, p_envio text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_num int;
begin
  if p_ticket is null then return; end if;
  perform 1 from imobdesk.ch_tickets x where x.id = p_ticket for update;
  v_num := coalesce((select max(a.numero) from imobdesk.ch_ticket_acoes a where a.ticket_id = p_ticket), 0) + 1;
  insert into imobdesk.ch_ticket_acoes (ticket_id, numero, tipo, canal, direcao, autor_id, autor_nome, texto, envio_status, mensagem_id)
  values (p_ticket, v_num, 'publica', 'whatsapp', p_direcao, p_autor, left(coalesce(p_autor_nome, 'WhatsApp'), 160), left(coalesce(p_texto, ''), 100000), p_envio, p_mensagem);
  if p_direcao = 'saida' then
    update imobdesk.ch_tickets set primeira_resposta_em = now() where id = p_ticket and primeira_resposta_em is null;
  end if;
end;
$$;

-- ======================================================================= fila e ticket

/**
 * Conversa entra na fila: abre o atendimento, cria o ticket (ou continua o aberto da conversa), grava o pedido
 * como 1ª ação, manda boas-vindas (ou fora do horário) e repassa ao grupo interno. p_prefixo vai antes da
 * mensagem automática ("Obrigado, Vinicius!").
 */
create or replace function imobdesk.at_entrar_fila(p_conversa bigint, p_pedido text[], p_prefixo text default null, p_forcar_novo boolean default false)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  c imobdesk.at_conversas;
  s imobdesk.at_setores;
  n imobdesk.at_numeros;
  v_atend bigint;
  v_ticket bigint;
  v_cat text;
  v_nome text;
  v_pedido text := nullif(btrim(array_to_string(coalesce(p_pedido, '{}'), E'\n')), '');
  v_aberto boolean;
  v_msg text;
  v_novo boolean := false;
begin
  select * into c from imobdesk.at_conversas x where x.id = p_conversa for update;
  select * into s from imobdesk.at_setores x where x.id = c.setor_id;
  select * into n from imobdesk.at_numeros x where x.id = c.numero_id;
  v_nome := imobdesk.at_nome_da_conversa(c);
  v_aberto := imobdesk.at_dentro_horario(c.setor_id);

  -- Voltou em até 24 h depois do último encerramento: conta como reaberto (indicador do Monitor).
  update imobdesk.at_atendimentos a set reaberto_em_24h = true
  where a.id = (select x.id from imobdesk.at_atendimentos x where x.conversa_id = c.id order by x.id desc limit 1)
    and a.encerrado_em is not null and a.encerrado_em > now() - interval '24 hours';

  -- Ticket aberto desta conversa continua (fechou com "não resolvido" ou ainda pendente).
  if not p_forcar_novo then
    select t.id, st.categoria into v_ticket, v_cat
    from imobdesk.ch_tickets t join imobdesk.ch_status st on st.id = t.status_id
    where t.conversa_id = c.id and t.excluido_em is null and t.mesclado_em_id is null and st.categoria in ('novo', 'andamento', 'pendente')
    order by t.id desc limit 1;
  end if;

  if v_ticket is null then
    insert into imobdesk.ch_tickets (assunto, origem, recebido_em, solicitante_pessoa_id, solicitante_nome, solicitante_contato, numero_id, conversa_id,
                                               setor_id, categoria_id, urgencia_id, status_id)
    values (left(coalesce(nullif(btrim(split_part(coalesce(v_pedido, ''), E'\n', 1)), ''), 'WhatsApp de ' || v_nome), 300), 'whatsapp',
            left('WhatsApp +' || n.numero, 160), c.pessoa_id, left(v_nome, 160), '+' || c.telefone, n.id, c.id, c.setor_id,
            (select x.id from imobdesk.ch_categorias x where x.padrao and x.ativa limit 1),
            coalesce((select u.id from imobdesk.ch_urgencias u where u.padrao and u.ativa limit 1), (select min(u.id) from imobdesk.ch_urgencias u)),
            coalesce(imobdesk.ch_status_de('novo'), 1))
    returning id into v_ticket;
    v_novo := true;
  elsif v_cat = 'pendente' then
    update imobdesk.ch_tickets set status_id = imobdesk.ch_status_de('andamento', 'Em atendimento'), justificativa_id = null where id = v_ticket;
  end if;

  -- Atendimento anterior ainda aberto (o colaborador pediu "novo"): fecha antes de abrir outro.
  update imobdesk.at_atendimentos set encerrado_em = now(), encerramento = 'sistema'
  where id = c.atendimento_id and encerrado_em is null;

  insert into imobdesk.at_atendimentos (conversa_id, setor_id, entrou_fila_em, fora_horario, ticket_id)
  values (c.id, c.setor_id, now(),
          not v_aberto or not exists (select 1 from imobdesk.at_atendentes a where a.setor_id = c.setor_id and a.apto and not a.pausa and a.online_em > now() - interval '3 minutes'),
          v_ticket)
  returning id into v_atend;

  update imobdesk.at_conversas set modo = 'fila', ident = null, atendente_id = null, atendente_desde = null, fila_desde = now(), atendimento_id = v_atend, atualizado_em = now()
  where id = c.id;
  -- Mensagens deste ciclo ficam no atendimento novo.
  update imobdesk.at_mensagens set atendimento_id = v_atend where conversa_id = c.id and atendimento_id is null;

  if v_pedido is not null then
    perform imobdesk.at_ticket_acao(v_ticket, 'entrada', null, v_nome, v_pedido, null, 'nao_se_aplica');
  end if;
  perform imobdesk.at_evento(c.id, format('Na fila do setor %s · ticket #%s%s', s.nome, v_ticket, case when v_novo then ' aberto' else ' (continua)' end));

  v_msg := case when v_aberto then s.msg_boas_vindas else s.msg_fora_horario end;
  v_msg := replace(replace(v_msg, '{nome}', coalesce(imobdesk.at_primeiro_nome(v_nome), '')), '{ticket}', '#' || v_ticket);
  -- Com prefixo ("Obrigado, Vinicius!"), tira a saudação do início da mensagem do setor para não repetir.
  if nullif(btrim(p_prefixo), '') is not null then
    v_msg := regexp_replace(v_msg, '^\s*(olá|ola|oi)\s*[!,.]?\s*', '', 'i');
  end if;
  perform imobdesk.at_auto(c.id, concat_ws(' ', nullif(btrim(p_prefixo), ''), v_msg));

  perform imobdesk.at_repassar(c.id, v_ticket, 'novo',
    format(E'🆕 *#%s* · %s%s\n"%s"', v_ticket, v_nome, case when v_novo then '' else ' (continua)' end, left(coalesce(v_pedido, '(sem texto)'), 600))
    || E'\n\n_Responda citando esta mensagem para falar com o colaborador._');
  return v_ticket;
end;
$$;

-- ======================================================================= entrada

/**
 * Mensagem recebida (Zenvia ou OpenWA, service role). p:
 *   {canal: 'zenvia'|'openwa', para?: número de destino (Zenvia), sessao?: sessão do OpenWA, de: telefone,
 *    nome?, texto?, tipo?: texto|imagem|arquivo|audio|video, arquivo?: {nome, url?, mime}, externoId}
 * Devolve {estado, conversaId?, ticketId?}. Idempotente pelo externoId.
 */
create or replace function imobdesk.at_whatsapp_receber(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_canal text := coalesce(p ->> 'canal', 'zenvia');
  v_de text := regexp_replace(coalesce(p ->> 'de', ''), '\D', '', 'g');
  v_texto text := left(btrim(coalesce(p ->> 'texto', '')), 4000);
  v_tipo text := coalesce(nullif(p ->> 'tipo', ''), 'texto');
  v_ext text := nullif(p ->> 'externoId', '');
  n imobdesk.at_numeros;
  s imobdesk.at_setores;
  c imobdesk.at_conversas;
  l imobdesk.at_linhas;
  v_msg bigint;
  v_ticket bigint;
  v_nome text;
  v_cat text;
  v_t text;
  v_ident jsonb;
  v_tent int;
  v_pessoa bigint;
  v_email text;
begin
  if v_de !~ '^\d{10,15}$' then return jsonb_build_object('estado', 'ignorado', 'motivo', 'telefone inválido'); end if;
  if v_tipo not in ('texto', 'arquivo', 'imagem', 'audio', 'video') then v_tipo := 'arquivo'; end if;

  if v_canal = 'openwa' then
    select * into n from imobdesk.at_numeros x where x.canal = 'openwa' and x.openwa_sessao = p ->> 'sessao' and x.ativo;
  else
    select * into n from imobdesk.at_numeros x where x.numero = regexp_replace(coalesce(p ->> 'para', ''), '\D', '', 'g') and x.ativo;
  end if;
  if n.id is null then return jsonb_build_object('estado', 'ignorado', 'motivo', 'número sem setor'); end if;
  if v_ext is not null and exists (select 1 from imobdesk.at_mensagens m where m.externo_id = v_ext or m.zenvia_id = v_ext) then
    return jsonb_build_object('estado', 'duplicado');
  end if;
  select * into s from imobdesk.at_setores x where x.id = n.setor_id;

  -- Conversa (uma por número + telefone). Duas mensagens juntas: a segunda espera a primeira (for update).
  insert into imobdesk.at_conversas (setor_id, numero_id, telefone, nome_contato, modo)
  values (n.setor_id, n.id, v_de, nullif(left(btrim(p ->> 'nome'), 80), ''), 'encerrada')
  on conflict (numero_id, telefone) do nothing;
  select * into c from imobdesk.at_conversas x where x.numero_id = n.id and x.telefone = v_de for update;

  insert into imobdesk.at_mensagens (conversa_id, atendimento_id, direcao, autor, tipo, texto, arquivo, status, zenvia_id, externo_id)
  values (c.id, case when c.modo in ('fila', 'atendente') then c.atendimento_id end, 'entrada', 'cliente', v_tipo, nullif(v_texto, ''),
          case when v_tipo <> 'texto' then p -> 'arquivo' end, 'recebida',
          case when v_canal = 'zenvia' then v_ext end, case when v_canal = 'openwa' then v_ext end)
  returning id into v_msg;
  update imobdesk.at_conversas set
    nome_contato = coalesce(nome_contato, nullif(left(btrim(p ->> 'nome'), 80), '')),
    ultima_msg_cliente_em = now(), ultima_msg_em = now(), nao_lidas = nao_lidas + 1,
    ultima_previa = left(coalesce(nullif(v_texto, ''), '[' || v_tipo || ']'), 200), atualizado_em = now()
  where id = c.id
  returning * into c;
  v_texto := coalesce(nullif(v_texto, ''), '[' || v_tipo || ']');
  v_t := lower(btrim(v_texto));

  -- ---------- Em atendimento (fila ou atendente): mensagem entra no ticket ----------
  if c.modo in ('fila', 'atendente') then
    v_ticket := imobdesk.at_ticket_da_conversa(c.id);
    v_nome := imobdesk.at_nome_da_conversa(c);
    if v_t = 'novo' then
      v_ticket := imobdesk.at_entrar_fila(c.id, '{}', 'Certo, abri um ticket novo. Conte o que você precisa.', true);
      return jsonb_build_object('estado', 'ticket_novo', 'conversaId', c.id, 'ticketId', v_ticket);
    end if;
    perform imobdesk.at_ticket_acao(v_ticket, 'entrada', null, v_nome, v_texto, v_msg, 'nao_se_aplica');
    select st.categoria into v_cat from imobdesk.ch_tickets t join imobdesk.ch_status st on st.id = t.status_id where t.id = v_ticket;
    if v_cat in ('pendente', 'resolvido') then
      update imobdesk.ch_tickets
         set status_id = imobdesk.ch_status_de('andamento', case when v_cat = 'resolvido' then 'Reaberto' else 'Em atendimento' end), justificativa_id = null
       where id = v_ticket;
    end if;
    perform imobdesk.at_repassar(c.id, v_ticket, 'mensagem', format(E'💬 *#%s* · %s:\n"%s"', v_ticket, v_nome, left(v_texto, 1500)));
    return jsonb_build_object('estado', 'mensagem', 'conversaId', c.id, 'ticketId', v_ticket);
  end if;

  -- ---------- Identificando (modo robo) ----------
  if c.modo = 'robo' then
    v_ident := coalesce(c.ident, '{}');
    v_tent := coalesce((v_ident ->> 'tentativas')::int, 0);
    select * into l from imobdesk.at_linhas x where x.numero = v_de;

    if v_ident ->> 'passo' = 'confirmar' then
      if v_t ~ '^(1|1\.|sim|s|sou|sou eu|isso|confirmo|correto|yes)$' then
        update imobdesk.at_linhas set confirmado_em = now(), atualizado_em = now() where numero = v_de;
        update imobdesk.at_conversas set pessoa_id = l.pessoa_id, nome_contato = (select left(pe.nome, 80) from imobdesk.at_pessoas pe where pe.id = l.pessoa_id)
        where id = c.id returning * into c;
        perform imobdesk.at_evento(c.id, 'Contato confirmado pelo colaborador');
        v_ticket := imobdesk.at_entrar_fila(c.id, array(select jsonb_array_elements_text(coalesce(v_ident -> 'pedido', '[]'))),
                                                     format('Obrigado, %s!', imobdesk.at_primeiro_nome(imobdesk.at_nome_da_conversa(c))));
        return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
      elsif v_t ~ '^(2|2\.|n|nao|não|no|errado|não sou|nao sou)$' then
        update imobdesk.at_conversas set ident = v_ident || jsonb_build_object('passo', 'nome', 'tentativas', 0) where id = c.id;
        perform imobdesk.at_auto(c.id, 'Sem problemas! Para agilizar seus próximos atendimentos, qual é o seu nome completo?');
        return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
      end if;
    elsif v_ident ->> 'passo' = 'nome' then
      if length(v_texto) between 3 and 80 and v_texto ~ '[[:alpha:]]{2}' and v_texto !~ '@' then
        update imobdesk.at_conversas set ident = v_ident || jsonb_build_object('passo', 'email', 'tentativas', 0, 'nome', btrim(v_texto)) where id = c.id;
        perform imobdesk.at_auto(c.id, format('Obrigado, %s. Qual é o seu e-mail corporativo?', imobdesk.at_primeiro_nome(v_texto)));
        return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
      end if;
    elsif v_ident ->> 'passo' = 'email' then
      v_email := lower(btrim(v_texto));
      if v_email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'
         and split_part(v_email, '@', 2) = any (coalesce((select x.dominios_corporativos from imobdesk.at_config x where x.id), '{}')::text[]) then
        select pc.pessoa_id into v_pessoa from imobdesk.at_pessoa_contatos pc where pc.tipo = 'email' and pc.valor = v_email limit 1;
        if v_pessoa is null then
          v_pessoa := imobdesk.at_pessoa_identificar('email', v_email, v_ident ->> 'nome', 'WhatsApp ' || s.nome);
        end if;
        -- O número passa a ser desta pessoa (se estava em outra, muda).
        insert into imobdesk.at_pessoa_contatos (pessoa_id, tipo, valor, principal)
        values (v_pessoa, 'whatsapp', v_de, not exists (select 1 from imobdesk.at_pessoa_contatos x where x.pessoa_id = v_pessoa and x.tipo = 'whatsapp'))
        on conflict (tipo, valor) do update set pessoa_id = excluded.pessoa_id;
        insert into imobdesk.at_linhas (numero, pessoa_id, corporativa, confirmado_em)
        values (v_de, v_pessoa, false, now())
        on conflict (numero) do update set pessoa_id = excluded.pessoa_id, confirmado_em = now(), atualizado_em = now();
        update imobdesk.at_conversas set pessoa_id = v_pessoa, nome_contato = left(coalesce(v_ident ->> 'nome', nome_contato), 80)
        where id = c.id returning * into c;
        perform imobdesk.at_evento(c.id, format('Colaborador identificado: %s (%s)', imobdesk.at_nome_da_conversa(c), v_email));
        v_ticket := imobdesk.at_entrar_fila(c.id, array(select jsonb_array_elements_text(coalesce(v_ident -> 'pedido', '[]'))),
                                                     'Pronto! Da próxima vez eu já te reconheço.');
        return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
      end if;
      v_tent := v_tent + 1;
      if v_tent >= 2 then
        if s.wa_so_corporativo then
          -- Linha corporativa (já conferida): segue para a fila sem identificação; o atendente completa.
          perform imobdesk.at_evento(c.id, 'Identificação não concluída (e-mail inválido): segue para a fila');
          v_ticket := imobdesk.at_entrar_fila(c.id, array(select jsonb_array_elements_text(coalesce(v_ident -> 'pedido', '[]'))));
          return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
        end if;
        perform imobdesk.at_auto(c.id, s.msg_nao_corporativo);
        update imobdesk.at_conversas set modo = 'encerrada', ident = null, aviso_nao_corporativo_em = now() where id = c.id;
        perform imobdesk.at_evento(c.id, 'Não é colaborador (e-mail fora do domínio): nenhum ticket aberto');
        return jsonb_build_object('estado', 'nao_colaborador', 'conversaId', c.id);
      end if;
      update imobdesk.at_conversas set ident = v_ident || jsonb_build_object('tentativas', v_tent) where id = c.id;
      perform imobdesk.at_auto(c.id, format('Esse e-mail não é de um domínio da empresa (%s). Qual é o seu e-mail corporativo?',
        (select array_to_string(array(select '@' || d from unnest(x.dominios_corporativos) d), ', ') from imobdesk.at_config x where x.id)));
      return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
    end if;

    -- Resposta que não serve para o passo: repete a pergunta (3 vezes; depois segue para a fila).
    v_tent := v_tent + 1;
    if v_tent >= 3 then
      if l.pessoa_id is not null then update imobdesk.at_conversas set pessoa_id = l.pessoa_id where id = c.id; end if;
      perform imobdesk.at_evento(c.id, 'Identificação não concluída: segue para a fila');
      v_ticket := imobdesk.at_entrar_fila(c.id, array(select jsonb_array_elements_text(coalesce(v_ident -> 'pedido', '[]'))) || v_texto);
      return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
    end if;
    update imobdesk.at_conversas set ident = v_ident || jsonb_build_object('tentativas', v_tent) where id = c.id;
    perform imobdesk.at_auto(c.id, case v_ident ->> 'passo'
      when 'confirmar' then 'Não entendi. Responda 1 para Sim ou 2 para Não.'
      when 'nome' then 'Qual é o seu nome completo?'
      else 'Qual é o seu e-mail corporativo?' end);
    return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
  end if;

  -- ---------- Conversa nova ou encerrada: começa um atendimento ----------
  select * into l from imobdesk.at_linhas x where x.numero = v_de;
  if s.wa_so_corporativo and not coalesce(l.corporativa, false) then
    if c.aviso_nao_corporativo_em is null or c.aviso_nao_corporativo_em < now() - interval '24 hours' then
      perform imobdesk.at_auto(c.id, s.msg_nao_corporativo);
      update imobdesk.at_conversas set aviso_nao_corporativo_em = now() where id = c.id;
      perform imobdesk.at_evento(c.id, 'Número fora das linhas corporativas: nenhum ticket aberto');
    end if;
    return jsonb_build_object('estado', 'nao_corporativo', 'conversaId', c.id);
  end if;

  -- Linha já confirmada (ou da planilha com pessoa, se a identificação estiver desligada): vincula a pessoa.
  if l.pessoa_id is not null and (l.confirmado_em is not null or not s.wa_identificar) then
    update imobdesk.at_conversas set pessoa_id = l.pessoa_id where id = c.id returning * into c;
  end if;

  if s.wa_identificar and (l.confirmado_em is null or l.pessoa_id is null) and imobdesk.at_auto_permitido(v_de) then
    if l.pessoa_id is not null then
      update imobdesk.at_conversas set modo = 'robo', ident = jsonb_build_object('passo', 'confirmar', 'tentativas', 0, 'desde', now(), 'pedido', jsonb_build_array(v_texto))
      where id = c.id;
      perform imobdesk.at_auto(c.id, format('Olá! Você é %s (%s)? Responda 1 para Sim ou 2 para Não.',
        (select pe.nome from imobdesk.at_pessoas pe where pe.id = l.pessoa_id),
        coalesce((select pc.valor from imobdesk.at_pessoa_contatos pc where pc.pessoa_id = l.pessoa_id and pc.tipo = 'email' order by pc.principal desc, pc.id limit 1), 'sem e-mail')));
      return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
    else
      update imobdesk.at_conversas set modo = 'robo', ident = jsonb_build_object('passo', 'nome', 'tentativas', 0, 'desde', now(), 'pedido', jsonb_build_array(v_texto))
      where id = c.id;
      perform imobdesk.at_auto(c.id, 'Olá! Para agilizar seus próximos atendimentos, qual é o seu nome completo?');
      return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
    end if;
  elsif not s.wa_identificar and c.pessoa_id is null then
    -- Setor sem identificação: autocadastro pelo número (como antes).
    update imobdesk.at_conversas
       set pessoa_id = imobdesk.at_pessoa_identificar('whatsapp', v_de, p ->> 'nome', 'WhatsApp ' || s.nome)
     where id = c.id;
  end if;

  v_ticket := imobdesk.at_entrar_fila(c.id, array[v_texto]);
  return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
end;
$$;

-- ======================================================================= ações do atendente

/**
 * Ação na conversa por um usuário (interna: a pública at_conversa_acao confere quem chama).
 * p: {acao: assumir|devolver|transferir|enviar|encerrar, texto?, para?, resolvido?, origem?: 'portal'|'grupo'|'roleta'|'sistema'}
 */
create or replace function imobdesk.at_conversa_executar(p_conversa bigint, p_usuario uuid, p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  c imobdesk.at_conversas;
  s imobdesk.at_setores;
  v_acao text := coalesce(p ->> 'acao', '');
  v_origem text := coalesce(p ->> 'origem', 'portal');
  v_nome text := imobdesk.ch_nome_usuario(p_usuario);
  v_ticket bigint;
  v_texto text;
  v_msg bigint;
  v_para uuid;
  v_cat text;
  v_resolvido boolean := coalesce((p ->> 'resolvido')::boolean, false);
begin
  select * into c from imobdesk.at_conversas x where x.id = p_conversa for update;
  if c.id is null then perform imobdesk.erro('NOT_FOUND', 'Conversa não encontrada.'); end if;
  select * into s from imobdesk.at_setores x where x.id = c.setor_id;
  v_ticket := imobdesk.at_ticket_da_conversa(c.id);
  if c.modo in ('encerrada', 'robo') and v_acao <> 'enviar' then
    perform imobdesk.erro('INVALID_INPUT', case when c.modo = 'robo' then 'O colaborador ainda está se identificando.' else 'Conversa encerrada. Ela reabre quando o cliente escrever de novo.' end);
  end if;

  if v_acao in ('assumir', 'transferir') then
    v_para := case when v_acao = 'transferir' then nullif(p ->> 'para', '')::uuid else p_usuario end;
    if v_acao = 'transferir' and not exists (select 1 from imobdesk.at_atendentes a where a.usuario_id = v_para and a.setor_id = c.setor_id) then
      perform imobdesk.erro('INVALID_INPUT', 'Escolha um atendente do mesmo setor.', 'para');
    end if;
    if c.atendente_id is not distinct from v_para then return jsonb_build_object('ok', true); end if;
    update imobdesk.at_conversas set modo = 'atendente', atendente_id = v_para, atendente_desde = now(), ultimo_atendente_id = v_para,
           nao_lidas = case when v_origem = 'portal' and v_acao = 'assumir' then 0 else nao_lidas end, atualizado_em = now()
    where id = c.id;
    update imobdesk.at_atendimentos set atendente_id = v_para, assumido_em = coalesce(assumido_em, now()),
           transferencias = transferencias + case when c.atendente_id is not null then 1 else 0 end
    where id = c.atendimento_id;
    if v_origem = 'roleta' then
      update imobdesk.at_atendentes set ultimo_recebido_em = now() where usuario_id = v_para;
    end if;
    -- Ticket: responsável = quem atende; sai de "Novo" para "Em atendimento".
    select st.categoria into v_cat from imobdesk.ch_tickets t join imobdesk.ch_status st on st.id = t.status_id where t.id = v_ticket;
    update imobdesk.ch_tickets set responsavel_id = v_para,
           status_id = case when v_cat in ('novo', 'pendente') then imobdesk.ch_status_de('andamento', 'Em atendimento') else status_id end,
           assumido_em = coalesce(assumido_em, now())
    where id = v_ticket;
    perform imobdesk.at_evento(c.id, case
      when v_origem = 'roleta' then format('Distribuída pela roleta para %s', imobdesk.ch_nome_usuario(v_para))
      when v_acao = 'transferir' then format('Conversa transferida para %s por %s', imobdesk.ch_nome_usuario(v_para), v_nome)
      when c.atendente_id is not null then format('Conversa transferida de %s para %s', imobdesk.ch_nome_usuario(c.atendente_id), v_nome)
      when v_origem = 'grupo' then format('%s assumiu ao responder pelo WhatsApp', v_nome)
      else format('%s assumiu a conversa', v_nome) end);
    return jsonb_build_object('ok', true);
  end if;

  if v_acao = 'devolver' then
    update imobdesk.at_conversas set modo = 'fila', atendente_id = null, atendente_desde = null, fila_desde = now(), atualizado_em = now() where id = c.id;
    update imobdesk.at_atendimentos set devolvido_fila = true where id = c.atendimento_id;
    perform imobdesk.at_evento(c.id, case when v_origem = 'sistema' then format('Voltou à fila: %s sem responder há %s min', coalesce(imobdesk.ch_nome_usuario(c.atendente_id), 'atendente'), s.atendente_sem_resposta_min)
                                                    else format('%s devolveu a conversa à fila', v_nome) end);
    return jsonb_build_object('ok', true);
  end if;

  if v_acao = 'enviar' then
    v_texto := left(btrim(coalesce(p ->> 'texto', '')), 4000);
    if v_texto = '' then perform imobdesk.erro('INVALID_INPUT', 'Escreva a mensagem.', 'texto'); end if;
    if c.modo in ('encerrada', 'robo') then
      perform imobdesk.erro('INVALID_INPUT', 'Conversa encerrada. Responda pelo ticket ou espere o cliente escrever.');
    end if;
    if c.modo = 'fila' or c.atendente_id is distinct from p_usuario then
      if c.modo = 'atendente' and c.atendente_id is distinct from p_usuario and not coalesce((p ->> 'podeTomar')::boolean, false) then
        perform imobdesk.erro('FORBIDDEN', format('Esta conversa está com %s.', imobdesk.ch_nome_usuario(c.atendente_id)));
      end if;
      perform imobdesk.at_conversa_executar(c.id, p_usuario, jsonb_build_object('acao', 'assumir', 'origem', v_origem));
    end if;
    insert into imobdesk.at_mensagens (conversa_id, atendimento_id, direcao, autor, autor_id, tipo, texto, status)
    values (c.id, c.atendimento_id, 'saida', 'atendente', p_usuario, 'texto', v_texto, 'pendente')
    returning id into v_msg;
    perform imobdesk.at_ticket_acao(v_ticket, 'saida', p_usuario, v_nome, v_texto, v_msg, 'pendente');
    update imobdesk.at_conversas set ultima_msg_atendente_em = now(), ultima_msg_em = now(), ultima_previa = left('Você: ' || v_texto, 200), nao_lidas = 0, atualizado_em = now()
    where id = c.id;
    update imobdesk.at_atendimentos set primeira_resposta_em = coalesce(primeira_resposta_em, now()) where id = c.atendimento_id;
    if v_origem = 'portal' then
      perform imobdesk.at_repassar(c.id, v_ticket, 'enviado', format('✔ %s respondeu *#%s* pelo sistema:%s"%s"', v_nome, v_ticket, E'\n', left(v_texto, 500)));
    end if;
    return jsonb_build_object('ok', true, 'mensagemId', v_msg);
  end if;

  if v_acao = 'encerrar' then
    -- Ticket: resolvido (a RPC pública já validou e gravou a solução) ou continua "Em atendimento".
    if not v_resolvido then
      select st.categoria into v_cat from imobdesk.ch_tickets t join imobdesk.ch_status st on st.id = t.status_id where t.id = v_ticket;
      if v_cat in ('novo', 'pendente', 'andamento') then
        update imobdesk.ch_tickets set status_id = imobdesk.ch_status_de('andamento', 'Em atendimento'), justificativa_id = null where id = v_ticket;
      end if;
    end if;
    perform imobdesk.at_auto(c.id, s.msg_encerramento);
    update imobdesk.at_conversas set modo = 'encerrada', ultimo_atendente_id = coalesce(c.atendente_id, p_usuario, ultimo_atendente_id), atendente_id = null,
           ultima_previa = 'Atendimento encerrado', atualizado_em = now()
    where id = c.id;
    update imobdesk.at_atendimentos set encerrado_em = now(), encerrado_por = p_usuario,
           encerramento = case when v_origem = 'sistema' then 'inatividade' else 'atendente' end
    where id = c.atendimento_id;
    perform imobdesk.at_evento(c.id, case when v_origem = 'sistema' then format('Encerrada por inatividade (%s h sem mensagem do cliente) · ticket #%s em atendimento', s.encerrar_apos_horas, v_ticket)
      else format('%s encerrou a conversa · ticket #%s %s', v_nome, v_ticket, case when v_resolvido then 'resolvido' else 'continua em atendimento' end) end);
    perform imobdesk.at_repassar(c.id, v_ticket, 'aviso', format('✅ *#%s* encerrado%s · %s', v_ticket,
      case when v_origem = 'sistema' then ' por inatividade' else ' por ' || v_nome end, case when v_resolvido then 'resolvido' else 'continua em atendimento' end));
    return jsonb_build_object('ok', true, 'ticketId', v_ticket);
  end if;

  perform imobdesk.erro('INVALID_INPUT', 'Ação inválida.');
end;
$$;

/**
 * Ação do atendente pelo portal (Conversas, tela do ticket). Confere quem pode:
 *   assumir/enviar: atendente do setor (conversa na fila ou dele) ou gestão do setor;
 *   devolver: quem está com a conversa ou a gestão; transferir: só a gestão;
 *   encerrar: quem está com a conversa ou a gestão. Com {resolvido: true, solucao, servicoId?, categoriaId?}
 *   o ticket vai para Resolvido (as regras de resolver do ticket valem: serviço, solução e obrigatórios).
 */
create or replace function imobdesk.at_conversa_acao(p_conversa bigint, p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_eu uuid := auth.uid();
  c imobdesk.at_conversas;
  v_acao text := coalesce(p ->> 'acao', '');
  v_gestor boolean;
  v_ticket bigint;
  v_upd jsonb;
begin
  select * into c from imobdesk.at_conversas x where x.id = p_conversa;
  if v_eu is null or c.id is null or not (imobdesk.at_supervisor()
       or imobdesk.at_ve_conversa(c.setor_id, c.atendente_id, case when c.modo = 'encerrada' then c.ultimo_atendente_id end)) then
    perform imobdesk.erro('NOT_FOUND', 'Conversa não encontrada.');
  end if;
  v_gestor := imobdesk.at_gestor_de(c.setor_id);
  if v_acao = 'transferir' and not v_gestor then perform imobdesk.erro('FORBIDDEN', 'Só a gestão do setor transfere conversas.'); end if;
  if v_acao in ('devolver', 'encerrar') and c.atendente_id is distinct from v_eu and not v_gestor then
    perform imobdesk.erro('FORBIDDEN', 'Só quem está com a conversa ou a gestão do setor faz isso.');
  end if;
  if v_acao = 'assumir' and c.modo = 'atendente' and c.atendente_id is distinct from v_eu and not v_gestor then
    perform imobdesk.erro('FORBIDDEN', 'Outro atendente está com esta conversa.');
  end if;
  if v_acao in ('assumir', 'enviar') and not v_gestor
     and not exists (select 1 from imobdesk.at_atendentes a where a.usuario_id = v_eu and a.setor_id = c.setor_id) then
    perform imobdesk.erro('FORBIDDEN', 'Entre na equipe do setor em Fila e horários para atender.');
  end if;

  if v_acao = 'encerrar' and coalesce((p ->> 'resolvido')::boolean, false) then
    v_ticket := imobdesk.at_ticket_da_conversa(c.id);
    if v_ticket is null then perform imobdesk.erro('INVALID_INPUT', 'Esta conversa não tem ticket.'); end if;
    v_upd := jsonb_build_object('statusId', imobdesk.ch_status_de('resolvido'), 'solucaoAplicada', p ->> 'solucao')
             || case when p ? 'servicoId' then jsonb_build_object('servicoId', p -> 'servicoId') else '{}' end
             || case when p ? 'categoriaId' then jsonb_build_object('categoriaId', p -> 'categoriaId') else '{}' end
             || case when (select t.responsavel_id from imobdesk.ch_tickets t where t.id = v_ticket) is null then jsonb_build_object('responsavelId', v_eu) else '{}' end;
    -- Valida e grava como o próprio usuário (mesmas regras do botão Resolver do ticket).
    perform imobdesk.ch_ticket_atualizar(v_ticket, v_upd);
  end if;
  return imobdesk.at_conversa_executar(c.id, v_eu, (p - 'origem' - 'podeTomar') || jsonb_build_object('origem', 'portal', 'podeTomar', v_gestor));
end;
$$;

-- ======================================================================= ticket → WhatsApp

-- Resposta pública no ticket de WhatsApp (tela do ticket): vira mensagem pendente na conversa do ticket.
create or replace function imobdesk.ch_acao_para_whatsapp()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  t imobdesk.ch_tickets;
  c imobdesk.at_conversas;
  v_msg bigint;
begin
  if new.canal <> 'whatsapp' or new.tipo <> 'publica' or new.direcao <> 'saida' or new.mensagem_id is not null or new.envio_status is distinct from 'pendente' then
    return null;
  end if;
  select * into t from imobdesk.ch_tickets x where x.id = new.ticket_id;
  select * into c from imobdesk.at_conversas x where x.id = t.conversa_id;
  if c.id is null then
    update imobdesk.ch_ticket_acoes set envio_status = 'falhou', envio_erro = 'Ticket sem conversa de WhatsApp.' where id = new.id;
    return null;
  end if;
  insert into imobdesk.at_mensagens (conversa_id, atendimento_id, direcao, autor, autor_id, tipo, texto, status)
  values (c.id, c.atendimento_id, 'saida', 'atendente', new.autor_id, 'texto', left(new.texto, 4000), 'pendente')
  returning id into v_msg;
  update imobdesk.ch_ticket_acoes set mensagem_id = v_msg where id = new.id;
  update imobdesk.at_conversas set ultima_msg_atendente_em = now(), ultima_msg_em = now(), ultima_previa = left('Você: ' || new.texto, 200), atualizado_em = now()
  where id = c.id;
  perform imobdesk.at_repassar(c.id, t.id, 'enviado', format('✔ %s respondeu *#%s* pelo ticket:%s"%s"', new.autor_nome, t.id, E'\n', left(new.texto, 500)));
  return null;
end;
$$;
drop trigger if exists ch_acoes_whatsapp on imobdesk.ch_ticket_acoes;
create trigger ch_acoes_whatsapp after insert on imobdesk.ch_ticket_acoes
for each row execute function imobdesk.ch_acao_para_whatsapp();

-- Status do envio da mensagem volta para a ação do ticket.
create or replace function imobdesk.at_mensagem_status_para_acao()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status is distinct from old.status and new.direcao = 'saida' then
    update imobdesk.ch_ticket_acoes
       set envio_status = case when new.status in ('enviada', 'entregue', 'lida') then 'enviado' when new.status = 'falhou' then 'falhou' else envio_status end,
           envio_erro = case when new.status = 'falhou' then left(new.erro, 1000) else null end
     where mensagem_id = new.id and envio_status is distinct from case when new.status in ('enviada', 'entregue', 'lida') then 'enviado' when new.status = 'falhou' then 'falhou' else envio_status end;
  end if;
  return null;
end;
$$;
drop trigger if exists at_mensagens_status_acao on imobdesk.at_mensagens;
create trigger at_mensagens_status_acao after update of status on imobdesk.at_mensagens
for each row execute function imobdesk.at_mensagem_status_para_acao();

-- ======================================================================= envio (despachante)

/**
 * Reserva o que está pendente para enviar (2 min; quem não confirmar libera de novo). p_conversa limita a uma
 * conversa (envio na hora, depois de uma ação). Devolve {mensagens: [...], repasses: [...]}.
 */
create or replace function imobdesk.at_whatsapp_reservar(p_limite int default 30, p_conversa bigint default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_msgs jsonb;
  v_reps jsonb;
begin
  with alvo as (
    select m.id from imobdesk.at_mensagens m
    where m.status = 'pendente' and m.direcao = 'saida' and m.envio_tentativas < 3
      and (m.envio_reservado_ate is null or m.envio_reservado_ate < now())
      and (p_conversa is null or m.conversa_id = p_conversa)
    order by m.id limit greatest(1, least(coalesce(p_limite, 30), 100))
    for update skip locked
  ), res as (
    update imobdesk.at_mensagens m set envio_reservado_ate = now() + interval '2 minutes' from alvo where m.id = alvo.id returning m.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', r.id, 'texto', r.texto, 'autor', r.autor, 'autorNome', imobdesk.ch_nome_usuario(r.autor_id),
    'telefone', c.telefone, 'canal', n.canal, 'numero', n.numero, 'sessao', n.openwa_sessao, 'setor', s.nome,
    'arquivo', r.arquivo, 'tipo', r.tipo
  ) order by r.id), '[]') into v_msgs
  from res r
  join imobdesk.at_conversas c on c.id = r.conversa_id
  join imobdesk.at_numeros n on n.id = c.numero_id
  join imobdesk.at_setores s on s.id = c.setor_id;

  with alvo as (
    select x.id from imobdesk.at_repasses x
    where x.status = 'pendente' and x.envio_tentativas < 3 and (x.envio_reservado_ate is null or x.envio_reservado_ate < now())
      and (p_conversa is null or x.conversa_id = p_conversa)
    order by x.id limit greatest(1, least(coalesce(p_limite, 30), 100))
    for update skip locked
  ), res as (
    update imobdesk.at_repasses x set envio_reservado_ate = now() + interval '2 minutes' from alvo where x.id = alvo.id returning x.*
  )
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'texto', r.texto, 'citar', r.citar_externo_id, 'sessao', n.openwa_sessao, 'grupo', n.grupo_interno) order by r.id), '[]')
  into v_reps
  from res r join imobdesk.at_numeros n on n.id = r.numero_id;

  return jsonb_build_object('mensagens', v_msgs, 'repasses', v_reps);
end;
$$;

/** Resultado do envio. p: {tipo: 'mensagem'|'repasse', id, ok, externoId?, erro?}. 3 falhas = falhou de vez. */
create or replace function imobdesk.at_whatsapp_envio_resultado(p jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id bigint := (p ->> 'id')::bigint;
  v_ok boolean := coalesce((p ->> 'ok')::boolean, false);
begin
  if p ->> 'tipo' = 'repasse' then
    update imobdesk.at_repasses set
      envio_tentativas = envio_tentativas + 1, envio_reservado_ate = null,
      status = case when v_ok then 'enviada' when envio_tentativas + 1 >= 3 then 'falhou' else 'pendente' end,
      externo_id = case when v_ok then nullif(p ->> 'externoId', '') else externo_id end,
      erro = case when v_ok then null else left(p ->> 'erro', 1000) end
    where id = v_id;
  else
    update imobdesk.at_mensagens set
      envio_tentativas = envio_tentativas + 1, envio_reservado_ate = null,
      status = case when v_ok then 'enviada' when envio_tentativas + 1 >= 3 then 'falhou' else 'pendente' end,
      zenvia_id = case when v_ok and p ->> 'canal' = 'zenvia' then coalesce(nullif(p ->> 'externoId', ''), zenvia_id) else zenvia_id end,
      externo_id = case when v_ok and p ->> 'canal' = 'openwa' then coalesce(nullif(p ->> 'externoId', ''), externo_id) else externo_id end,
      erro = case when v_ok then null else left(p ->> 'erro', 1000) end
    where id = v_id;
  end if;
end;
$$;

-- ======================================================================= ciclo (pg_cron)

/** Roleta, inatividade e identificação parada. Chamado pela Edge a cada 1 min (service role). */
create or replace function imobdesk.at_whatsapp_ciclo()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  r record;
  v_usr uuid;
  v_ident int := 0;
  v_devolvidas int := 0;
  v_encerradas int := 0;
  v_roleta int := 0;
begin
  -- Identificação parada há 10 min: segue para a fila sem identificação.
  for r in select c.id, c.ident from imobdesk.at_conversas c
           where c.modo = 'robo' and coalesce((c.ident ->> 'desde')::timestamptz, c.atualizado_em) < now() - interval '10 minutes'
           order by c.id limit 50 loop
    perform imobdesk.at_evento(r.id, 'Sem resposta na identificação: segue para a fila');
    perform imobdesk.at_entrar_fila(r.id, array(select jsonb_array_elements_text(coalesce(r.ident -> 'pedido', '[]'))));
    v_ident := v_ident + 1;
  end loop;

  -- Cliente sem mensagem há N horas (setor): encerra; o ticket continua "Em atendimento".
  for r in select c.id from imobdesk.at_conversas c join imobdesk.at_setores s on s.id = c.setor_id
           where c.modo in ('fila', 'atendente') and coalesce(c.ultima_msg_cliente_em, c.fila_desde) < now() - make_interval(hours => s.encerrar_apos_horas)
           order by c.id limit 50 loop
    perform imobdesk.at_conversa_executar(r.id, null, jsonb_build_object('acao', 'encerrar', 'origem', 'sistema', 'resolvido', false));
    v_encerradas := v_encerradas + 1;
  end loop;

  -- Atendente sem responder ao cliente há N min (setor): volta para a fila.
  for r in select c.id from imobdesk.at_conversas c join imobdesk.at_setores s on s.id = c.setor_id
           where c.modo = 'atendente' and c.ultima_msg_cliente_em > coalesce(c.ultima_msg_atendente_em, c.atendente_desde, '-infinity')
             and c.ultima_msg_cliente_em < now() - make_interval(mins => s.atendente_sem_resposta_min)
             and coalesce(c.atendente_desde, '-infinity') < now() - make_interval(mins => s.atendente_sem_resposta_min)
           order by c.id limit 50 loop
    perform imobdesk.at_conversa_executar(r.id, null, jsonb_build_object('acao', 'devolver', 'origem', 'sistema'));
    v_devolvidas := v_devolvidas + 1;
  end loop;

  -- Roleta: dentro do horário, a fila (ordem de chegada) vai para quem está apto, online, sem pausa e abaixo do limite,
  -- começando por quem recebeu há mais tempo.
  for r in select c.id, c.setor_id from imobdesk.at_conversas c
           where c.modo = 'fila' and c.atendente_id is null and imobdesk.at_dentro_horario(c.setor_id)
           order by c.fila_desde nulls first, c.id limit 50 loop
    v_usr := null;
    select ate.usuario_id into v_usr
    from imobdesk.at_atendentes ate
    join imobdesk.at_setores s on s.id = ate.setor_id
    where ate.setor_id = r.setor_id and ate.apto and not ate.pausa and ate.online_em > now() - interval '3 minutes'
      and (select count(*) from imobdesk.at_conversas x where x.atendente_id = ate.usuario_id and x.modo = 'atendente') < s.limite_simultaneo
    order by ate.ultimo_recebido_em nulls first, ate.usuario_id
    limit 1;
    continue when v_usr is null;
    perform imobdesk.at_conversa_executar(r.id, v_usr, jsonb_build_object('acao', 'assumir', 'origem', 'roleta'));
    v_roleta := v_roleta + 1;
  end loop;

  return jsonb_build_object('identificacao', v_ident, 'encerradas', v_encerradas, 'devolvidas', v_devolvidas, 'roleta', v_roleta);
end;
$$;

-- ======================================================================= telas

-- Lista da Central: "ticket" passa a ser o ticket da Gestão de Chamados (antes era o nº do atendimento).
create or replace function imobdesk.at_conversas_lista(p_limite int default 300)
returns table (
  id bigint, setor_id bigint, numero text, telefone text, nome_contato text, modo text,
  atendente_id uuid, atendente_nome text, atendente_desde timestamptz, fila_desde timestamptz,
  ticket bigint, ultima_msg_cliente_em timestamptz, ultima_msg_atendente_em timestamptz, ultima_msg_em timestamptz,
  ultima_previa text, nao_lidas int, nota_interna text, cliente_desde timestamptz, total_atendimentos bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select c.id, c.setor_id, n.numero, c.telefone,
         coalesce((select pe.nome from imobdesk.at_pessoas pe where pe.id = c.pessoa_id), c.nome_contato), c.modo,
         c.atendente_id, coalesce(ua.nome, uu.nome), c.atendente_desde, c.fila_desde,
         (select a.ticket_id from imobdesk.at_atendimentos a where a.id = c.atendimento_id),
         c.ultima_msg_cliente_em, c.ultima_msg_atendente_em, c.ultima_msg_em,
         c.ultima_previa, c.nao_lidas, c.nota_interna, c.criado_em,
         (select count(*) from imobdesk.at_atendimentos t where t.conversa_id = c.id)
  from imobdesk.at_conversas c
  join imobdesk.at_numeros n on n.id = c.numero_id
  left join imobdesk.usuarios ua on ua.id = c.atendente_id
  left join imobdesk.usuarios uu on uu.id = c.ultimo_atendente_id
  order by c.ultima_msg_em desc nulls last
  limit least(greatest(coalesce(p_limite, 300), 1), 1000);
$$;

create or replace function imobdesk.at_monitor_conversas(p_setor bigint default null)
returns table (
  conversa_id bigint, ticket bigint, setor_id bigint, setor_nome text, nome_contato text, telefone text, numero text,
  modo text, ultima_previa text, fila_desde timestamptz, atendente_id uuid, atendente_nome text, atendente_desde timestamptz,
  ultima_msg_cliente_em timestamptz, ultima_msg_atendente_em timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_setores bigint[] := imobdesk.at_monitor_setores(p_setor);
begin
  return query
    select c.id, (select a.ticket_id from imobdesk.at_atendimentos a where a.id = c.atendimento_id), c.setor_id, s.nome,
           coalesce((select pe.nome from imobdesk.at_pessoas pe where pe.id = c.pessoa_id), c.nome_contato), c.telefone, n.numero,
           c.modo, c.ultima_previa, c.fila_desde, c.atendente_id, u.nome, c.atendente_desde,
           c.ultima_msg_cliente_em, c.ultima_msg_atendente_em
    from imobdesk.at_conversas c
    join imobdesk.at_setores s on s.id = c.setor_id
    join imobdesk.at_numeros n on n.id = c.numero_id
    left join imobdesk.usuarios u on u.id = c.atendente_id
    where c.setor_id = any (v_setores) and c.modo in ('fila', 'atendente')
    order by c.modo, coalesce(c.fila_desde, c.atendente_desde);
end;
$$;

-- ======================================================================= permissões e agendamento

do $$
declare
  f text;
begin
  foreach f in array array[
    'ch_status_de(text, text)', 'at_dentro_horario(bigint)', 'at_auto_permitido(text)', 'at_evento(bigint, text)', 'at_auto(bigint, text)',
    'at_repassar(bigint, bigint, text, text, text)', 'at_nome_da_conversa(imobdesk.at_conversas)', 'at_ticket_da_conversa(bigint)',
    'at_ticket_acao(bigint, text, uuid, text, text, bigint, text)', 'at_entrar_fila(bigint, text[], text, boolean)', 'at_whatsapp_receber(jsonb)',
    'at_conversa_executar(bigint, uuid, jsonb)', 'at_whatsapp_reservar(int, bigint)', 'at_whatsapp_envio_resultado(jsonb)', 'at_whatsapp_ciclo()',
    'ch_acao_para_whatsapp()', 'at_mensagem_status_para_acao()'
  ] loop
    execute format('revoke execute on function imobdesk.%s from public, anon, authenticated', f);
    execute format('grant execute on function imobdesk.%s to service_role', f);
  end loop;
  revoke execute on function imobdesk.at_conversa_acao(bigint, jsonb) from public, anon;
  grant execute on function imobdesk.at_conversa_acao(bigint, jsonb) to authenticated, service_role;
  revoke execute on function imobdesk.at_primeiro_nome(text) from public, anon;
  grant execute on function imobdesk.at_primeiro_nome(text) to authenticated, service_role;
end;
$$;

-- Chave do pg_cron para a Edge imobdesk-whatsapp (ciclo + envio a cada 1 min).
do $$
begin
  if not exists (select 1 from vault.secrets where name = 'imobdesk_whatsapp_cron') then
    perform vault.create_secret(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 'imobdesk_whatsapp_cron',
      'Chave do pg_cron para a Edge imobdesk-whatsapp (Imobdesk)');
  end if;
end;
$$;

create or replace function imobdesk.at_whatsapp_cron_chave()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select d.decrypted_secret from vault.decrypted_secrets d where d.name = 'imobdesk_whatsapp_cron';
$$;
revoke execute on function imobdesk.at_whatsapp_cron_chave() from public, anon, authenticated;
grant execute on function imobdesk.at_whatsapp_cron_chave() to service_role;

do $$
begin
  if exists (select 1 from cron.job where jobname = 'imobdesk-whatsapp-1min') then
    perform cron.unschedule('imobdesk-whatsapp-1min');
  end if;
  perform cron.schedule('imobdesk-whatsapp-1min', '* * * * *', $job$
    select net.http_post(
      url := 'https://ikvjaowvpvxojvcfwnct.supabase.co/functions/v1/imobdesk-whatsapp',
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-atendimento-chave', imobdesk.at_whatsapp_cron_chave()),
      body := '{"acao": "ciclo"}'::jsonb,
      timeout_milliseconds := 55000
    );
  $job$);
end;
$$;

-- ======================================== 20261009150300_imobdesk_openwa.sql
-- WhatsApp pelo OpenWA, opção A (docs/PLANO-conversas-whatsapp-openwa.md, Fase 3; aprovado em 09/10/2026).
-- O colaborador fala no privado com o número do sistema do setor; cada pedido é repassado ao grupo interno só de
-- atendentes; a resposta que CITA o repasse (no celular ou no sistema) chega ao privado do colaborador.
-- Credenciais (URL do OpenWA, API key) e o segredo do webhook ficam no Vault. Linhas corporativas (planilha da
-- operadora) e o WhatsApp de cada atendente são cadastrados aqui. Só aditiva.

-- ======================================================================= credenciais

alter table imobdesk.at_config add column if not exists openwa_url text check (openwa_url ~ '^https?://[^\s]+$');
alter table imobdesk.at_config add column if not exists openwa_chave_id uuid;
alter table imobdesk.at_config add column if not exists openwa_chave_mascara text;
alter table imobdesk.at_config add column if not exists openwa_definido_em timestamptz;
alter table imobdesk.at_config add column if not exists openwa_verificacao jsonb;

-- Segredo do webhook (HMAC-SHA256 do corpo, cabeçalho X-OpenWA-Signature). Gerado uma vez; a Edge cadastra no OpenWA.
do $$
begin
  if not exists (select 1 from vault.secrets where name = 'imobdesk_openwa_webhook') then
    perform vault.create_secret(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 'imobdesk_openwa_webhook',
      'Segredo do webhook do OpenWA (Imobdesk)');
  end if;
end;
$$;

-- Eventos crus do webhook (idempotência pelo idempotencyKey do OpenWA e diagnóstico).
create table if not exists imobdesk.at_eventos_openwa (
  id           bigint      generated always as identity primary key,
  recebido_em  timestamptz not null default now(),
  chave        text        unique,
  evento       text,
  sessao       text,
  payload      jsonb       not null,
  resultado    jsonb
);
create index if not exists at_eventos_openwa_recebido_idx on imobdesk.at_eventos_openwa (recebido_em desc);
alter table imobdesk.at_eventos_openwa enable row level security;
revoke all on imobdesk.at_eventos_openwa from anon, public, authenticated;
grant all on imobdesk.at_eventos_openwa to service_role;

/** URL do OpenWA e, se informada, a API key (Vault). Só o super admin. */
create or replace function imobdesk.at_openwa_salvar(p jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := auth.uid();
  v_url text := rtrim(btrim(coalesce(p ->> 'url', '')), '/');
  v_chave text := btrim(coalesce(p ->> 'chave', ''));
  v_id uuid;
begin
  if v_ator is null or not imobdesk.eh_super_admin() then
    perform imobdesk.erro('FORBIDDEN', 'Só o super admin altera a conexão do OpenWA.');
  end if;
  if v_url !~ '^https?://[^\s]+$' then
    perform imobdesk.erro('INVALID_INPUT', 'Informe a URL do OpenWA (ex.: https://xxxx.trycloudflare.com).', 'url');
  end if;
  if v_chave <> '' then
    if v_chave !~ '^[A-Za-z0-9_.-]+$' or length(v_chave) not between 16 and 300 then
      perform imobdesk.erro('INVALID_INPUT', 'API key inválida: copie a chave inteira do OpenWA (data/.api-key).', 'chave');
    end if;
    v_id := coalesce((select c.openwa_chave_id from imobdesk.at_config c where c.id),
                     (select s.id from vault.secrets s where s.name = ('imobdesk_openwa_chave_' || imobdesk.empresa_atual())));
    if v_id is null then
      v_id := vault.create_secret(v_chave, ('imobdesk_openwa_chave_' || imobdesk.empresa_atual()), 'API key do OpenWA (Imobdesk)');
    else
      perform vault.update_secret(v_id, v_chave);
    end if;
    update imobdesk.at_config set openwa_chave_id = v_id, openwa_chave_mascara = '••••••••' || right(v_chave, 4) where id;
  end if;
  update imobdesk.at_config set openwa_url = v_url, openwa_definido_em = now(), openwa_verificacao = null, atualizado_em = now(), atualizado_por = v_ator where id;
  perform imobdesk.registrar_auditoria(v_ator, 'atendimento', 'update', 'Conexão do OpenWA alterada', null, jsonb_build_object('url', v_url), 'at_config');
end;
$$;

/** Só para as Edge Functions. */
create or replace function imobdesk.at_ler_credencial_openwa()
returns table (url text, chave text, webhook_segredo text)
language sql
stable
security definer
set search_path = ''
as $$
  select c.openwa_url,
         (select d.decrypted_secret from vault.decrypted_secrets d where d.id = c.openwa_chave_id),
         (select d.decrypted_secret from vault.decrypted_secrets d where d.name = 'imobdesk_openwa_webhook')
  from imobdesk.at_config c where c.id;
$$;

-- ======================================================================= tela "WhatsApp OpenWA"

/** Tudo o que a tela mostra. Supervisão geral vê todos os setores; o gestor, os dele. */
create or replace function imobdesk.at_openwa_painel()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_sup boolean := imobdesk.at_supervisor();
begin
  if auth.uid() is null or not (v_sup or exists (select 1 from imobdesk.at_setores s where imobdesk.at_gestor_de(s.id))) then
    perform imobdesk.erro('FORBIDDEN', 'Só a gestão do atendimento vê esta tela.');
  end if;
  return jsonb_build_object(
    'superAdmin', imobdesk.eh_super_admin(),
    'supervisor', v_sup,
    'conexao', (select jsonb_build_object('url', c.openwa_url, 'chaveMascara', c.openwa_chave_mascara, 'definidoEm', c.openwa_definido_em,
                                          'verificacao', c.openwa_verificacao, 'autoLigado', c.ligado, 'travaPiloto', c.trava_piloto,
                                          'dominios', to_jsonb(c.dominios_corporativos))
                from imobdesk.at_config c where c.id),
    'webhookUrl', null,
    'setores', coalesce((select jsonb_agg(jsonb_build_object(
        'id', s.id, 'nome', s.nome, 'waIdentificar', s.wa_identificar, 'waSoCorporativo', s.wa_so_corporativo,
        'msgNaoCorporativo', s.msg_nao_corporativo, 'gestor', imobdesk.at_gestor_de(s.id),
        'numeros', coalesce((select jsonb_agg(jsonb_build_object('id', n.id, 'numero', n.numero, 'canal', n.canal, 'sessao', n.openwa_sessao,
                                                                  'grupo', n.grupo_interno, 'grupoNome', n.grupo_interno_nome) order by n.id)
                             from imobdesk.at_numeros n where n.setor_id = s.id and n.ativo), '[]'),
        'atendentes', coalesce((select jsonb_agg(jsonb_build_object('usuarioId', a.usuario_id, 'nome', u.nome, 'whatsapp', a.whatsapp) order by u.nome)
                                from imobdesk.at_atendentes a join imobdesk.usuarios u on u.id = a.usuario_id
                                where a.setor_id = s.id), '[]')
      ) order by s.nome)
      from imobdesk.at_setores s where s.ativo and (v_sup or imobdesk.at_gestor_de(s.id))), '[]'),
    'linhas', (select count(*) from imobdesk.at_linhas l where l.corporativa)
  );
end;
$$;

/** Número → canal (zenvia/openwa), sessão do OpenWA e grupo interno. Supervisão geral. */
create or replace function imobdesk.at_openwa_numero_salvar(p jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := auth.uid();
  v_id bigint := (p ->> 'numeroId')::bigint;
  v_canal text := coalesce(nullif(p ->> 'canal', ''), 'zenvia');
  v_sessao text := nullif(btrim(p ->> 'sessao'), '');
  v_grupo text := nullif(btrim(p ->> 'grupo'), '');
  v_antes jsonb;
begin
  if v_ator is null or not imobdesk.at_supervisor() then
    perform imobdesk.erro('FORBIDDEN', 'Só a supervisão geral configura os números.');
  end if;
  select to_jsonb(n) into v_antes from imobdesk.at_numeros n where n.id = v_id;
  if v_antes is null then perform imobdesk.erro('NOT_FOUND', 'Número não encontrado.'); end if;
  if v_canal not in ('zenvia', 'openwa') then perform imobdesk.erro('INVALID_INPUT', 'Canal inválido.', 'canal'); end if;
  if v_canal = 'openwa' and v_sessao is null then
    perform imobdesk.erro('INVALID_INPUT', 'Informe a sessão do OpenWA deste número.', 'sessao');
  end if;
  if v_grupo is not null and v_grupo !~ '@g\.us$' then
    perform imobdesk.erro('INVALID_INPUT', 'Escolha um grupo do WhatsApp (id terminando em @g.us).', 'grupo');
  end if;
  if v_sessao is not null and exists (select 1 from imobdesk.at_numeros n where n.openwa_sessao = v_sessao and n.ativo and n.id <> v_id) then
    perform imobdesk.erro('DUPLICATE', 'Esta sessão já está em outro número.', 'sessao');
  end if;
  update imobdesk.at_numeros set canal = v_canal,
    openwa_sessao = case when v_canal = 'openwa' then v_sessao end,
    grupo_interno = case when v_canal = 'openwa' then v_grupo end,
    grupo_interno_nome = case when v_canal = 'openwa' then nullif(left(btrim(p ->> 'grupoNome'), 120), '') end
  where id = v_id;
  perform imobdesk.registrar_auditoria(v_ator, 'atendimento', 'update', format('Número %s: canal %s', v_antes ->> 'numero', v_canal),
    v_antes, (select to_jsonb(n) from imobdesk.at_numeros n where n.id = v_id), v_id::text);
end;
$$;

/** Regras de WhatsApp do setor (identificação e só linha corporativa). Gestão do setor. */
create or replace function imobdesk.at_setor_whatsapp_salvar(p jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := auth.uid();
  v_setor bigint := (p ->> 'setorId')::bigint;
  v_msg text := btrim(coalesce(p ->> 'msgNaoCorporativo', ''));
begin
  if v_ator is null or not imobdesk.at_gestor_de(v_setor) then
    perform imobdesk.erro('FORBIDDEN', 'Só a gestão do setor altera estas regras.');
  end if;
  if v_msg = '' or length(v_msg) > 1000 then
    perform imobdesk.erro('INVALID_INPUT', 'Escreva a mensagem para quem não é linha corporativa (até 1.000 letras).', 'msgNaoCorporativo');
  end if;
  update imobdesk.at_setores set
    wa_identificar = coalesce((p ->> 'waIdentificar')::boolean, wa_identificar),
    wa_so_corporativo = coalesce((p ->> 'waSoCorporativo')::boolean, wa_so_corporativo),
    msg_nao_corporativo = v_msg, atualizado_em = now(), atualizado_por = v_ator
  where id = v_setor;
  perform imobdesk.registrar_auditoria(v_ator, 'atendimento', 'update', 'Regras de WhatsApp do setor alteradas', null, p, v_setor::text);
end;
$$;

/** WhatsApp pessoal do atendente (quem responde no grupo interno). Gestão do setor ou o próprio atendente. */
create or replace function imobdesk.at_atendente_whatsapp_salvar(p jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := auth.uid();
  v_usuario uuid := (p ->> 'usuarioId')::uuid;
  v_setor bigint := (select a.setor_id from imobdesk.at_atendentes a where a.usuario_id = v_usuario);
  v_num text := nullif(imobdesk.at_contato_normalizar('whatsapp', p ->> 'whatsapp'), '');
begin
  if v_setor is null then perform imobdesk.erro('NOT_FOUND', 'Atendente não encontrado.'); end if;
  if v_ator is null or not (v_ator = v_usuario or imobdesk.at_gestor_de(v_setor)) then
    perform imobdesk.erro('FORBIDDEN', 'Só a gestão do setor altera o WhatsApp de outro atendente.');
  end if;
  if v_num is not null and v_num !~ '^\d{10,15}$' then
    perform imobdesk.erro('INVALID_INPUT', 'Telefone inválido (com DDD).', 'whatsapp');
  end if;
  if v_num is not null and exists (select 1 from imobdesk.at_atendentes a where a.whatsapp = v_num and a.usuario_id <> v_usuario) then
    perform imobdesk.erro('DUPLICATE', 'Este número já está em outro atendente.', 'whatsapp');
  end if;
  update imobdesk.at_atendentes set whatsapp = v_num where usuario_id = v_usuario;
end;
$$;

-- ======================================================================= linhas corporativas

/** Linhas cadastradas (corporativas e confirmadas), com a pessoa. Gestão do atendimento. */
create or replace function imobdesk.at_linhas_lista(p_busca text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := lower(btrim(coalesce(p_busca, '')));
begin
  if auth.uid() is null or not (imobdesk.at_supervisor() or exists (select 1 from imobdesk.at_setores s where imobdesk.at_gestor_de(s.id))) then
    perform imobdesk.erro('FORBIDDEN', 'Só a gestão do atendimento vê as linhas.');
  end if;
  return coalesce((
    select jsonb_agg(x order by x ->> 'pessoa' nulls last, x ->> 'numero')
    from (
      select jsonb_build_object('numero', l.numero, 'corporativa', l.corporativa, 'confirmadoEm', l.confirmado_em, 'observacao', l.observacao,
                                'pessoaId', l.pessoa_id, 'pessoa', pe.nome,
                                'email', (select pc.valor from imobdesk.at_pessoa_contatos pc where pc.pessoa_id = l.pessoa_id and pc.tipo = 'email' order by pc.principal desc, pc.id limit 1)) x
      from imobdesk.at_linhas l
      left join imobdesk.at_pessoas pe on pe.id = l.pessoa_id
      where v_q = '' or l.numero like '%' || regexp_replace(v_q, '\D', '', 'g') || '%' and regexp_replace(v_q, '\D', '', 'g') <> ''
         or lower(coalesce(pe.nome, '')) like '%' || v_q || '%' or lower(coalesce(l.observacao, '')) like '%' || v_q || '%'
      limit 2000
    ) y
  ), '[]');
end;
$$;

/**
 * Importa/salva linhas corporativas. p: [{numero, nome?, email?, observacao?}]. Com e-mail, liga (ou cria) a
 * pessoa; o colaborador ainda confirma no 1º contato. Devolve {salvas, invalidas: [numero]}.
 */
create or replace function imobdesk.at_linhas_importar(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := auth.uid();
  r jsonb;
  v_num text;
  v_email text;
  v_pessoa bigint;
  v_salvas int := 0;
  v_invalidas text[] := '{}';
begin
  if v_ator is null or not imobdesk.at_supervisor() then
    perform imobdesk.erro('FORBIDDEN', 'Só a supervisão geral cadastra linhas corporativas.');
  end if;
  if jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 5000 then
    perform imobdesk.erro('INVALID_INPUT', 'Envie até 5.000 linhas por vez.');
  end if;
  for r in select * from jsonb_array_elements(p) loop
    v_num := imobdesk.at_contato_normalizar('whatsapp', r ->> 'numero');
    if v_num !~ '^\d{10,15}$' then
      v_invalidas := v_invalidas || left(coalesce(r ->> 'numero', ''), 30);
      continue;
    end if;
    v_pessoa := null;
    v_email := lower(btrim(coalesce(r ->> 'email', '')));
    if v_email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
      v_pessoa := imobdesk.at_pessoa_identificar('email', v_email, nullif(btrim(r ->> 'nome'), ''), 'Linhas corporativas');
      insert into imobdesk.at_pessoa_contatos (pessoa_id, tipo, valor, principal)
      values (v_pessoa, 'whatsapp', v_num, not exists (select 1 from imobdesk.at_pessoa_contatos x where x.pessoa_id = v_pessoa and x.tipo = 'whatsapp'))
      on conflict (tipo, valor) do update set pessoa_id = excluded.pessoa_id;
    end if;
    insert into imobdesk.at_linhas (numero, pessoa_id, corporativa, observacao, atualizado_por)
    values (v_num, v_pessoa, true, nullif(left(btrim(r ->> 'observacao'), 200), ''), v_ator)
    on conflict (numero) do update set corporativa = true,
      pessoa_id = coalesce(excluded.pessoa_id, imobdesk.at_linhas.pessoa_id),
      -- Mudou a pessoa da linha: precisa confirmar de novo.
      confirmado_em = case when excluded.pessoa_id is not null and excluded.pessoa_id is distinct from imobdesk.at_linhas.pessoa_id then null
                           else imobdesk.at_linhas.confirmado_em end,
      observacao = coalesce(excluded.observacao, imobdesk.at_linhas.observacao),
      atualizado_em = now(), atualizado_por = v_ator;
    v_salvas := v_salvas + 1;
  end loop;
  perform imobdesk.registrar_auditoria(v_ator, 'atendimento', 'update', format('Linhas corporativas: %s salvas, %s inválidas', v_salvas, cardinality(v_invalidas)), null, null, 'at_linhas');
  return jsonb_build_object('salvas', v_salvas, 'invalidas', to_jsonb(v_invalidas));
end;
$$;

/** Tira a linha da lista corporativa (o histórico da pessoa continua). */
create or replace function imobdesk.at_linha_remover(p_numero text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := auth.uid();
begin
  if v_ator is null or not imobdesk.at_supervisor() then
    perform imobdesk.erro('FORBIDDEN', 'Só a supervisão geral altera as linhas corporativas.');
  end if;
  delete from imobdesk.at_linhas where numero = regexp_replace(coalesce(p_numero, ''), '\D', '', 'g');
  perform imobdesk.registrar_auditoria(v_ator, 'atendimento', 'delete', 'Linha corporativa removida: ' || coalesce(p_numero, ''), null, null, 'at_linhas');
end;
$$;

-- ======================================================================= grupo interno

/**
 * Mensagem no grupo interno de atendentes (OpenWA, service role). p:
 *   {sessao, grupo, autor: telefone de quem escreveu, texto, citadoId?, externoId}
 * Resposta citando um repasse → vai ao colaborador como resposta do atendente. Sem citação → dica (1 a cada 30 min).
 */
create or replace function imobdesk.at_grupo_receber(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  n imobdesk.at_numeros;
  a imobdesk.at_atendentes;
  x imobdesk.at_repasses;
  c imobdesk.at_conversas;
  v_autor text := regexp_replace(coalesce(p ->> 'autor', ''), '\D', '', 'g');
  v_texto text := left(btrim(coalesce(p ->> 'texto', '')), 4000);
  v_cit text := nullif(p ->> 'citadoId', '');
  v_core text;
  v_res jsonb;
begin
  select * into n from imobdesk.at_numeros z where z.canal = 'openwa' and z.openwa_sessao = p ->> 'sessao' and z.grupo_interno = p ->> 'grupo' and z.ativo;
  if n.id is null then return jsonb_build_object('estado', 'ignorado', 'motivo', 'grupo não configurado'); end if;
  select * into a from imobdesk.at_atendentes z where z.whatsapp = v_autor and z.setor_id = n.setor_id;
  if a.usuario_id is null then return jsonb_build_object('estado', 'ignorado', 'motivo', 'autor não é atendente do setor'); end if;
  if v_texto = '' then return jsonb_build_object('estado', 'ignorado', 'motivo', 'sem texto'); end if;

  if v_cit is null then
    -- Conversa entre atendentes é livre; a dica sai no máximo a cada 30 min por atendente.
    if a.grupo_dica_em is null or a.grupo_dica_em < now() - interval '30 minutes' then
      update imobdesk.at_atendentes set grupo_dica_em = now() where usuario_id = a.usuario_id;
      insert into imobdesk.at_repasses (numero_id, tipo, texto, citar_externo_id)
      values (n.id, 'aviso', '💡 Para responder a um colaborador, toque e segure o pedido (🆕 ou 💬) e escolha *Responder*. Mensagens sem citação ficam só aqui no grupo.', nullif(p ->> 'externoId', ''));
    end if;
    return jsonb_build_object('estado', 'sem_citacao');
  end if;

  -- O id citado pode vir completo (true_<grupo>_<id>_<autor>) ou só o miolo: compara pelo miolo.
  v_core := case when v_cit ~ '^(true|false)_' then split_part(v_cit, '_', 3) else v_cit end;
  select * into x from imobdesk.at_repasses r
  where r.numero_id = n.id and r.externo_id is not null and r.conversa_id is not null
    and (r.externo_id = v_cit or split_part(r.externo_id, '_', 3) = v_core or r.externo_id = v_core)
  order by r.id desc limit 1;
  if x.id is null then
    insert into imobdesk.at_repasses (numero_id, tipo, texto, citar_externo_id)
    values (n.id, 'aviso', '⚠️ Não achei o pedido citado. Cite a mensagem 🆕 ou 💬 do colaborador.', nullif(p ->> 'externoId', ''));
    return jsonb_build_object('estado', 'citacao_desconhecida');
  end if;

  select * into c from imobdesk.at_conversas z where z.id = x.conversa_id;
  if c.modo in ('encerrada', 'robo') then
    insert into imobdesk.at_repasses (numero_id, conversa_id, ticket_id, tipo, texto, citar_externo_id)
    values (n.id, c.id, x.ticket_id, 'aviso', format('⚠️ O atendimento do *#%s* já foi encerrado. Para falar com o colaborador, responda pelo ticket no sistema.', x.ticket_id), nullif(p ->> 'externoId', ''));
    return jsonb_build_object('estado', 'encerrada');
  end if;
  if c.modo = 'atendente' and c.atendente_id is distinct from a.usuario_id and not exists (
       select 1 from imobdesk.at_setor_gestores g where g.setor_id = c.setor_id and g.usuario_id = a.usuario_id) then
    insert into imobdesk.at_repasses (numero_id, conversa_id, ticket_id, tipo, texto, citar_externo_id)
    values (n.id, c.id, x.ticket_id, 'aviso', format('⚠️ O *#%s* está com %s. Combine com ele(a) ou peça a transferência.', x.ticket_id, imobdesk.ch_nome_usuario(c.atendente_id)),
            nullif(p ->> 'externoId', ''));
    return jsonb_build_object('estado', 'com_outro');
  end if;

  v_res := imobdesk.at_conversa_executar(c.id, a.usuario_id, jsonb_build_object('acao', 'enviar', 'texto', v_texto, 'origem', 'grupo', 'podeTomar', true));
  insert into imobdesk.at_repasses (numero_id, conversa_id, ticket_id, tipo, texto, citar_externo_id)
  values (n.id, c.id, x.ticket_id, 'enviado', format('✔ Enviado a %s (*#%s*)', imobdesk.at_nome_da_conversa(c), x.ticket_id), nullif(p ->> 'externoId', ''));
  return jsonb_build_object('estado', 'enviada', 'conversaId', c.id, 'ticketId', x.ticket_id) || coalesce(v_res, '{}');
end;
$$;

/** Resultado do "Testar conexão" (Edge). */
create or replace function imobdesk.at_openwa_verificacao_salvar(p jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  update imobdesk.at_config set openwa_verificacao = p where id;
$$;

-- ======================================================================= permissões

do $$
declare
  f text;
begin
  foreach f in array array['at_openwa_salvar(jsonb)', 'at_openwa_painel()', 'at_openwa_numero_salvar(jsonb)', 'at_setor_whatsapp_salvar(jsonb)',
                           'at_atendente_whatsapp_salvar(jsonb)', 'at_linhas_lista(text)', 'at_linhas_importar(jsonb)', 'at_linha_remover(text)'] loop
    execute format('revoke execute on function imobdesk.%s from public, anon', f);
    execute format('grant execute on function imobdesk.%s to authenticated, service_role', f);
  end loop;
  foreach f in array array['at_ler_credencial_openwa()', 'at_grupo_receber(jsonb)', 'at_openwa_verificacao_salvar(jsonb)'] loop
    execute format('revoke execute on function imobdesk.%s from public, anon, authenticated', f);
    execute format('grant execute on function imobdesk.%s to service_role', f);
  end loop;
end;
$$;

notify pgrst, 'reload schema';

-- ======================================== 20261009150400_imobdesk_conversas_menu_metricas.sql
-- Conversas e Monitor dentro da Gestão de Chamados, tela WhatsApp OpenWA e a métrica "Quem mais abre chamados"
-- (docs/PLANO-conversas-whatsapp-openwa.md, Fases 4 e 5; aprovado em 09/10/2026). Só aditiva: só insere
-- permissões novas (copiadas de quem já tinha a equivalente) e cria uma função.

-- "Monitor de atendimento" (seção nova da Gestão de Chamados): quem já via o Monitor (gestor do setor ou supervisão).
insert into imobdesk.profile_permissions (role, permission_id, enabled)
select distinct pp.role, 'gestao_chamados_monitor', true
from imobdesk.profile_permissions pp
where pp.permission_id in ('gestao_atendimento_monitor', 'gestao_atendimento_supervisao') and pp.enabled
on conflict (role, permission_id) do nothing;

-- "WhatsApp OpenWA" (Administração): quem já configura Setores e números.
insert into imobdesk.profile_permissions (role, permission_id, enabled)
select distinct pp.role, 'gestao_atendimento_openwa', true
from imobdesk.profile_permissions pp
where pp.permission_id = 'gestao_atendimento_setores' and pp.enabled
on conflict (role, permission_id) do nothing;

/**
 * Quem mais abre chamados (Visão geral). Só os tickets que a pessoa pode ver, criados nos últimos p_dias.
 * {periodoDias, total, whatsapp, resolvidosNaConversa (%), identificados (%), top: [...], departamentos: [...]}
 */
create or replace function imobdesk.ch_top_solicitantes(p_dias int default 30)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_dias int := least(greatest(coalesce(p_dias, 30), 1), 365);
begin
  if not (imobdesk.ch_eh_admin() or imobdesk.tem_permissao('gestao_chamados_visao_geral') or imobdesk.tem_permissao('gestao_chamados_tickets')) then
    perform imobdesk.erro('FORBIDDEN', 'Sem acesso à Gestão de Chamados.');
  end if;
  return (
    with vis as (
      select t.* from imobdesk.ch_tickets t
      where t.excluido_em is null and t.mesclado_em_id is null and t.criado_em >= now() - make_interval(days => v_dias)
        and imobdesk.ch_pode_ver_ticket(t.setor_id, t.equipe_id, t.responsavel_id)
    ), wa as (
      -- Atendimentos de WhatsApp encerrados pelo atendente: resolvido na conversa = ticket resolvido/fechado.
      select a.ticket_id, (st.categoria in ('resolvido', 'fechado')) as resolvido
      from imobdesk.at_atendimentos a
      join vis t on t.id = a.ticket_id
      join imobdesk.ch_status st on st.id = t.status_id
      where a.encerramento = 'atendente'
    ), top as (
      select t.solicitante_pessoa_id as pessoa_id, max(t.solicitante_nome) as nome, count(*) as tickets,
             (select sv.nome from vis t2 join imobdesk.ch_servicos sv on sv.id = t2.servico_id
              where t2.solicitante_pessoa_id = t.solicitante_pessoa_id group by sv.nome order by count(*) desc, sv.nome limit 1) as servico
      from vis t where t.solicitante_pessoa_id is not null
      group by t.solicitante_pessoa_id
      order by count(*) desc, max(t.solicitante_nome)
      limit 10
    ), dep as (
      select e.nome, count(distinct t.id) as tickets
      from vis t
      join imobdesk.at_pessoa_relacoes r on r.pessoa_id = t.solicitante_pessoa_id
      join imobdesk.at_pessoas e on e.id = r.empresa_id and e.tipo = 'departamento'
      group by e.nome order by count(distinct t.id) desc, e.nome limit 10
    )
    select jsonb_build_object(
      'periodoDias', v_dias,
      'total', (select count(*) from vis),
      'whatsapp', (select count(*) from vis where origem = 'whatsapp'),
      'resolvidosNaConversa', (select case when count(*) = 0 then null else round(100.0 * count(*) filter (where resolvido) / count(*)) end from wa),
      'identificados', (select case when count(*) = 0 then null else round(100.0 * count(*) filter (where solicitante_pessoa_id is not null) / count(*)) end from vis),
      'top', coalesce((select jsonb_agg(jsonb_build_object('pessoaId', pessoa_id, 'nome', nome, 'tickets', tickets, 'servico', servico) order by tickets desc, nome) from top), '[]'),
      'departamentos', coalesce((select jsonb_agg(jsonb_build_object('nome', nome, 'tickets', tickets) order by tickets desc, nome) from dep), '[]')
    )
  );
end;
$$;
revoke execute on function imobdesk.ch_top_solicitantes(int) from public, anon;
grant execute on function imobdesk.ch_top_solicitantes(int) to authenticated, service_role;

notify pgrst, 'reload schema';

-- ======================================== 20261009160000_imobdesk_conversas_lista_nome.sql
-- Correção (09/10/2026): Conversas mostrava "Não foi possível carregar as conversas". A at_conversas_lista (security
-- invoker: a RLS de at_conversas decide o que entra) passou a ler o nome em at_pessoas, que não tem SELECT para
-- authenticated (pessoas só por RPC) → "permission denied for table at_pessoas" e a lista inteira falhava.
-- Agora o nome vem de at_nome_pessoa (security definer, devolve só o nome). O ticket do atendimento também vinha vazio
-- (a RLS de at_atendimentos esconde a linha do atendente): vem de at_ticket_do_atendimento. Mesma assinatura. Só aditiva.

create or replace function imobdesk.at_nome_pessoa(p_id bigint)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select p.nome from imobdesk.at_pessoas p where p.id = p_id;
$$;
revoke execute on function imobdesk.at_nome_pessoa(bigint) from public, anon;
grant execute on function imobdesk.at_nome_pessoa(bigint) to authenticated, service_role;

create or replace function imobdesk.at_ticket_do_atendimento(p_atendimento bigint)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select a.ticket_id from imobdesk.at_atendimentos a where a.id = p_atendimento;
$$;
revoke execute on function imobdesk.at_ticket_do_atendimento(bigint) from public, anon;
grant execute on function imobdesk.at_ticket_do_atendimento(bigint) to authenticated, service_role;

create or replace function imobdesk.at_conversas_lista(p_limite int default 300)
returns table (
  id bigint, setor_id bigint, numero text, telefone text, nome_contato text, modo text,
  atendente_id uuid, atendente_nome text, atendente_desde timestamptz, fila_desde timestamptz,
  ticket bigint, ultima_msg_cliente_em timestamptz, ultima_msg_atendente_em timestamptz, ultima_msg_em timestamptz,
  ultima_previa text, nao_lidas int, nota_interna text, cliente_desde timestamptz, total_atendimentos bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select c.id, c.setor_id, n.numero, c.telefone,
         coalesce(imobdesk.at_nome_pessoa(c.pessoa_id), c.nome_contato), c.modo,
         c.atendente_id, coalesce(ua.nome, uu.nome), c.atendente_desde, c.fila_desde,
         imobdesk.at_ticket_do_atendimento(c.atendimento_id),
         c.ultima_msg_cliente_em, c.ultima_msg_atendente_em, c.ultima_msg_em,
         c.ultima_previa, c.nao_lidas, c.nota_interna, c.criado_em,
         (select count(*) from imobdesk.at_atendimentos t where t.conversa_id = c.id)
  from imobdesk.at_conversas c
  join imobdesk.at_numeros n on n.id = c.numero_id
  left join imobdesk.usuarios ua on ua.id = c.atendente_id
  left join imobdesk.usuarios uu on uu.id = c.ultimo_atendente_id
  order by c.ultima_msg_em desc nulls last
  limit least(greatest(coalesce(p_limite, 300), 1), 1000);
$$;

notify pgrst, 'reload schema';

-- ======================================== 20261009170000_imobdesk_whatsapp_ajustes.sql
-- Ajustes do WhatsApp pedidos pelo Wagner no 1º teste real (09/10/2026):
--  1. Boas-vindas e identificação não saíam: as respostas automáticas dependiam da chave da Zenvia ("ligado" + trava do
--     piloto). Agora cada setor tem a sua (wa_respostas_auto, ligada por padrão) para os números do OpenWA; a Zenvia
--     continua com a regra antiga.
--  2. "Verificar se o número existe na base": a identificação procura também no cadastro de Pessoas (contato WhatsApp
--     ou telefone). Achou → confirma "Você é Fulano (e-mail)?"; não achou → pede nome e e-mail e cadastra. Pessoa com
--     e-mail de domínio da empresa conta como colaborador para "Só linhas corporativas".
--  3. "RESOLVIDO" escrito pelo atendente (portal, grupo interno ou o próprio celular do número) resolve o ticket e
--     encerra; a mensagem final ao solicitante sempre leva o número do chamado.
--  4. Resposta digitada no próprio celular do número do sistema (evento message.sent do OpenWA) entra na conversa e
--     no ticket (at_whatsapp_propria), sem duplicar o eco do que o próprio sistema enviou.
-- Só aditiva: coluna nova e funções trocadas (mesma assinatura) ou novas.

alter table imobdesk.at_setores add column if not exists wa_respostas_auto boolean not null default true;

/** Respostas automáticas valem nesta conversa? OpenWA: chave do setor. Zenvia: "ligado" + trava do piloto (como antes). */
create or replace function imobdesk.at_auto_conversa(p_conversa bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((
    select case when n.canal = 'openwa' then s.wa_respostas_auto else imobdesk.at_auto_permitido(c.telefone) end
    from imobdesk.at_conversas c
    join imobdesk.at_numeros n on n.id = c.numero_id
    join imobdesk.at_setores s on s.id = c.setor_id
    where c.id = p_conversa), false);
$$;

/** "RESOLVIDO" (com ou sem pontuação, maiúsculas ou não) = encerrar resolvendo o ticket. */
create or replace function imobdesk.at_eh_resolvido(p_texto text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select lower(btrim(coalesce(p_texto, ''), ' .!*_')) in ('resolvido', 'resolvida', '#resolvido', 'ok resolvido', 'chamado resolvido');
$$;

/** Resolve o ticket pela palavra RESOLVIDO (sem o diálogo): solução padrão se não houver; o serviço fica o da triagem. */
create or replace function imobdesk.at_ticket_resolver_direto(p_ticket bigint, p_usuario uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  update imobdesk.ch_tickets set
    status_id = imobdesk.ch_status_de('resolvido'), justificativa_id = null,
    responsavel_id = coalesce(responsavel_id, p_usuario),
    solucao_aplicada = coalesce(solucao_aplicada,
      format('Resolvido no atendimento pelo WhatsApp por %s.', coalesce(imobdesk.ch_nome_usuario(p_usuario), 'atendente')))
  where id = p_ticket and excluido_em is null;
$$;

/** Resposta automática pendente (sai pelo despachante). OpenWA: chave do setor; Zenvia: "ligado" + trava do piloto. */
create or replace function imobdesk.at_auto(p_conversa bigint, p_texto text)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  c imobdesk.at_conversas;
  v_id bigint;
begin
  select * into c from imobdesk.at_conversas x where x.id = p_conversa;
  if c.id is null or nullif(btrim(p_texto), '') is null or not imobdesk.at_auto_conversa(c.id) then
    return null;
  end if;
  insert into imobdesk.at_mensagens (conversa_id, atendimento_id, direcao, autor, tipo, texto, status)
  values (c.id, c.atendimento_id, 'saida', 'auto', 'texto', left(p_texto, 4000), 'pendente')
  returning id into v_id;
  return v_id;
end;
$$;

/**
 * Mensagem recebida (Zenvia ou OpenWA, service role). p:
 *   {canal: 'zenvia'|'openwa', para?: número de destino (Zenvia), sessao?: sessão do OpenWA, de: telefone,
 *    nome?, texto?, tipo?: texto|imagem|arquivo|audio|video, arquivo?: {nome, url?, mime}, externoId}
 * Devolve {estado, conversaId?, ticketId?}. Idempotente pelo externoId.
 */
create or replace function imobdesk.at_whatsapp_receber(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_canal text := coalesce(p ->> 'canal', 'zenvia');
  v_de text := regexp_replace(coalesce(p ->> 'de', ''), '\D', '', 'g');
  v_texto text := left(btrim(coalesce(p ->> 'texto', '')), 4000);
  v_tipo text := coalesce(nullif(p ->> 'tipo', ''), 'texto');
  v_ext text := nullif(p ->> 'externoId', '');
  n imobdesk.at_numeros;
  s imobdesk.at_setores;
  c imobdesk.at_conversas;
  l imobdesk.at_linhas;
  v_msg bigint;
  v_ticket bigint;
  v_nome text;
  v_cat text;
  v_t text;
  v_ident jsonb;
  v_tent int;
  v_pessoa bigint;
  v_email text;
  v_base bigint;   -- pessoa achada pelo número (linhas ou cadastro de Pessoas)
  v_corp boolean;
begin
  if v_de !~ '^\d{10,15}$' then return jsonb_build_object('estado', 'ignorado', 'motivo', 'telefone inválido'); end if;
  if v_tipo not in ('texto', 'arquivo', 'imagem', 'audio', 'video') then v_tipo := 'arquivo'; end if;

  if v_canal = 'openwa' then
    select * into n from imobdesk.at_numeros x where x.canal = 'openwa' and x.openwa_sessao = p ->> 'sessao' and x.ativo;
  else
    select * into n from imobdesk.at_numeros x where x.numero = regexp_replace(coalesce(p ->> 'para', ''), '\D', '', 'g') and x.ativo;
  end if;
  if n.id is null then return jsonb_build_object('estado', 'ignorado', 'motivo', 'número sem setor'); end if;
  if v_ext is not null and exists (select 1 from imobdesk.at_mensagens m where m.externo_id = v_ext or m.zenvia_id = v_ext) then
    return jsonb_build_object('estado', 'duplicado');
  end if;
  select * into s from imobdesk.at_setores x where x.id = n.setor_id;

  -- Conversa (uma por número + telefone). Duas mensagens juntas: a segunda espera a primeira (for update).
  insert into imobdesk.at_conversas (setor_id, numero_id, telefone, nome_contato, modo)
  values (n.setor_id, n.id, v_de, nullif(left(btrim(p ->> 'nome'), 80), ''), 'encerrada')
  on conflict (numero_id, telefone) do nothing;
  select * into c from imobdesk.at_conversas x where x.numero_id = n.id and x.telefone = v_de for update;

  insert into imobdesk.at_mensagens (conversa_id, atendimento_id, direcao, autor, tipo, texto, arquivo, status, zenvia_id, externo_id)
  values (c.id, case when c.modo in ('fila', 'atendente') then c.atendimento_id end, 'entrada', 'cliente', v_tipo, nullif(v_texto, ''),
          case when v_tipo <> 'texto' then p -> 'arquivo' end, 'recebida',
          case when v_canal = 'zenvia' then v_ext end, case when v_canal = 'openwa' then v_ext end)
  returning id into v_msg;
  update imobdesk.at_conversas set
    nome_contato = coalesce(nome_contato, nullif(left(btrim(p ->> 'nome'), 80), '')),
    ultima_msg_cliente_em = now(), ultima_msg_em = now(), nao_lidas = nao_lidas + 1,
    ultima_previa = left(coalesce(nullif(v_texto, ''), '[' || v_tipo || ']'), 200), atualizado_em = now()
  where id = c.id
  returning * into c;
  v_texto := coalesce(nullif(v_texto, ''), '[' || v_tipo || ']');
  v_t := lower(btrim(v_texto));

  -- ---------- Em atendimento (fila ou atendente): mensagem entra no ticket ----------
  if c.modo in ('fila', 'atendente') then
    v_ticket := imobdesk.at_ticket_da_conversa(c.id);
    v_nome := imobdesk.at_nome_da_conversa(c);
    if v_t = 'novo' then
      v_ticket := imobdesk.at_entrar_fila(c.id, '{}', 'Certo, abri um ticket novo. Conte o que você precisa.', true);
      return jsonb_build_object('estado', 'ticket_novo', 'conversaId', c.id, 'ticketId', v_ticket);
    end if;
    perform imobdesk.at_ticket_acao(v_ticket, 'entrada', null, v_nome, v_texto, v_msg, 'nao_se_aplica');
    select st.categoria into v_cat from imobdesk.ch_tickets t join imobdesk.ch_status st on st.id = t.status_id where t.id = v_ticket;
    if v_cat in ('pendente', 'resolvido') then
      update imobdesk.ch_tickets
         set status_id = imobdesk.ch_status_de('andamento', case when v_cat = 'resolvido' then 'Reaberto' else 'Em atendimento' end), justificativa_id = null
       where id = v_ticket;
    end if;
    perform imobdesk.at_repassar(c.id, v_ticket, 'mensagem', format(E'💬 *#%s* · %s:\n"%s"', v_ticket, v_nome, left(v_texto, 1500)));
    return jsonb_build_object('estado', 'mensagem', 'conversaId', c.id, 'ticketId', v_ticket);
  end if;

  -- ---------- Identificando (modo robo) ----------
  if c.modo = 'robo' then
    v_ident := coalesce(c.ident, '{}');
    v_tent := coalesce((v_ident ->> 'tentativas')::int, 0);
    select * into l from imobdesk.at_linhas x where x.numero = v_de;

    if v_ident ->> 'passo' = 'confirmar' then
      if v_t ~ '^(1|1\.|sim|s|sou|sou eu|isso|confirmo|correto|yes)$' then
        v_base := coalesce(nullif(v_ident ->> 'pessoaId', '')::bigint, l.pessoa_id);
        insert into imobdesk.at_linhas (numero, pessoa_id, corporativa, confirmado_em)
        values (v_de, v_base, false, now())
        on conflict (numero) do update set pessoa_id = excluded.pessoa_id, confirmado_em = now(), atualizado_em = now();
        insert into imobdesk.at_pessoa_contatos (pessoa_id, tipo, valor, principal)
        values (v_base, 'whatsapp', v_de, not exists (select 1 from imobdesk.at_pessoa_contatos x where x.pessoa_id = v_base and x.tipo = 'whatsapp'))
        on conflict (tipo, valor) do update set pessoa_id = excluded.pessoa_id;
        update imobdesk.at_conversas set pessoa_id = v_base, nome_contato = (select left(pe.nome, 80) from imobdesk.at_pessoas pe where pe.id = v_base)
        where id = c.id returning * into c;
        perform imobdesk.at_evento(c.id, 'Contato confirmado pelo colaborador');
        v_ticket := imobdesk.at_entrar_fila(c.id, array(select jsonb_array_elements_text(coalesce(v_ident -> 'pedido', '[]'))),
                                                     format('Obrigado, %s!', imobdesk.at_primeiro_nome(imobdesk.at_nome_da_conversa(c))));
        return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
      elsif v_t ~ '^(2|2\.|n|nao|não|no|errado|não sou|nao sou)$' then
        update imobdesk.at_conversas set ident = v_ident || jsonb_build_object('passo', 'nome', 'tentativas', 0) where id = c.id;
        perform imobdesk.at_auto(c.id, 'Sem problemas! Para cadastrar você, qual é o seu nome completo?');
        return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
      end if;
    elsif v_ident ->> 'passo' = 'nome' then
      if length(v_texto) between 3 and 80 and v_texto ~ '[[:alpha:]]{2}' and v_texto !~ '@' then
        update imobdesk.at_conversas set ident = v_ident || jsonb_build_object('passo', 'email', 'tentativas', 0, 'nome', btrim(v_texto)) where id = c.id;
        perform imobdesk.at_auto(c.id, format('Obrigado, %s. Qual é o seu e-mail corporativo?', imobdesk.at_primeiro_nome(v_texto)));
        return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
      end if;
    elsif v_ident ->> 'passo' = 'email' then
      v_email := lower(btrim(v_texto));
      if v_email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'
         and split_part(v_email, '@', 2) = any (coalesce((select x.dominios_corporativos from imobdesk.at_config x where x.id), '{}')::text[]) then
        select pc.pessoa_id into v_pessoa from imobdesk.at_pessoa_contatos pc where pc.tipo = 'email' and pc.valor = v_email limit 1;
        if v_pessoa is null then
          v_pessoa := imobdesk.at_pessoa_identificar('email', v_email, v_ident ->> 'nome', 'WhatsApp ' || s.nome);
        end if;
        -- O número passa a ser desta pessoa (se estava em outra, muda).
        insert into imobdesk.at_pessoa_contatos (pessoa_id, tipo, valor, principal)
        values (v_pessoa, 'whatsapp', v_de, not exists (select 1 from imobdesk.at_pessoa_contatos x where x.pessoa_id = v_pessoa and x.tipo = 'whatsapp'))
        on conflict (tipo, valor) do update set pessoa_id = excluded.pessoa_id;
        insert into imobdesk.at_linhas (numero, pessoa_id, corporativa, confirmado_em)
        values (v_de, v_pessoa, false, now())
        on conflict (numero) do update set pessoa_id = excluded.pessoa_id, confirmado_em = now(), atualizado_em = now();
        update imobdesk.at_conversas set pessoa_id = v_pessoa, nome_contato = left(coalesce(v_ident ->> 'nome', nome_contato), 80)
        where id = c.id returning * into c;
        perform imobdesk.at_evento(c.id, format('Colaborador identificado: %s (%s)', imobdesk.at_nome_da_conversa(c), v_email));
        v_ticket := imobdesk.at_entrar_fila(c.id, array(select jsonb_array_elements_text(coalesce(v_ident -> 'pedido', '[]'))),
                                                     'Pronto! Da próxima vez eu já te reconheço.');
        return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
      end if;
      v_tent := v_tent + 1;
      if v_tent >= 2 then
        if s.wa_so_corporativo then
          -- Linha corporativa (já conferida): segue para a fila sem identificação; o atendente completa.
          perform imobdesk.at_evento(c.id, 'Identificação não concluída (e-mail inválido): segue para a fila');
          v_ticket := imobdesk.at_entrar_fila(c.id, array(select jsonb_array_elements_text(coalesce(v_ident -> 'pedido', '[]'))));
          return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
        end if;
        perform imobdesk.at_auto(c.id, s.msg_nao_corporativo);
        update imobdesk.at_conversas set modo = 'encerrada', ident = null, aviso_nao_corporativo_em = now() where id = c.id;
        perform imobdesk.at_evento(c.id, 'Não é colaborador (e-mail fora do domínio): nenhum ticket aberto');
        return jsonb_build_object('estado', 'nao_colaborador', 'conversaId', c.id);
      end if;
      update imobdesk.at_conversas set ident = v_ident || jsonb_build_object('tentativas', v_tent) where id = c.id;
      perform imobdesk.at_auto(c.id, format('Esse e-mail não é de um domínio da empresa (%s). Qual é o seu e-mail corporativo?',
        (select array_to_string(array(select '@' || d from unnest(x.dominios_corporativos) d), ', ') from imobdesk.at_config x where x.id)));
      return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
    end if;

    -- Resposta que não serve para o passo: repete a pergunta (3 vezes; depois segue para a fila).
    v_tent := v_tent + 1;
    if v_tent >= 3 then
      v_base := coalesce(nullif(v_ident ->> 'pessoaId', '')::bigint, l.pessoa_id);
      if v_base is not null then update imobdesk.at_conversas set pessoa_id = v_base where id = c.id; end if;
      perform imobdesk.at_evento(c.id, 'Identificação não concluída: segue para a fila');
      v_ticket := imobdesk.at_entrar_fila(c.id, array(select jsonb_array_elements_text(coalesce(v_ident -> 'pedido', '[]'))) || v_texto);
      return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
    end if;
    update imobdesk.at_conversas set ident = v_ident || jsonb_build_object('tentativas', v_tent) where id = c.id;
    perform imobdesk.at_auto(c.id, case v_ident ->> 'passo'
      when 'confirmar' then 'Não entendi. Responda 1 para Sim ou 2 para Não.'
      when 'nome' then 'Qual é o seu nome completo?'
      else 'Qual é o seu e-mail corporativo?' end);
    return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
  end if;

  -- ---------- Conversa nova ou encerrada: começa um atendimento ----------
  -- A base é a lista de linhas e o cadastro de Pessoas (contato WhatsApp ou telefone com este número).
  select * into l from imobdesk.at_linhas x where x.numero = v_de;
  v_base := coalesce(l.pessoa_id,
    (select pc.pessoa_id from imobdesk.at_pessoa_contatos pc
     where pc.valor = v_de and pc.tipo in ('whatsapp', 'telefone') order by (pc.tipo = 'whatsapp') desc, pc.id limit 1));
  -- Colaborador: linha corporativa ou pessoa da base com e-mail de um domínio da empresa.
  v_corp := coalesce(l.corporativa, false) or exists (
    select 1 from imobdesk.at_pessoa_contatos pc
    where pc.pessoa_id = v_base and pc.tipo = 'email'
      and split_part(pc.valor, '@', 2) = any (coalesce((select x.dominios_corporativos from imobdesk.at_config x where x.id), '{}')::text[]));
  if s.wa_so_corporativo and not v_corp then
    if c.aviso_nao_corporativo_em is null or c.aviso_nao_corporativo_em < now() - interval '24 hours' then
      perform imobdesk.at_auto(c.id, s.msg_nao_corporativo);
      update imobdesk.at_conversas set aviso_nao_corporativo_em = now() where id = c.id;
      perform imobdesk.at_evento(c.id, 'Número fora das linhas corporativas e sem cadastro de colaborador: nenhum ticket aberto');
    end if;
    return jsonb_build_object('estado', 'nao_corporativo', 'conversaId', c.id);
  end if;

  -- Já confirmado antes (ou identificação desligada): vincula a pessoa e segue.
  if v_base is not null and (l.confirmado_em is not null or not s.wa_identificar) then
    update imobdesk.at_conversas set pessoa_id = v_base where id = c.id returning * into c;
  end if;

  if s.wa_identificar and (l.confirmado_em is null or v_base is null) and imobdesk.at_auto_conversa(c.id) then
    if v_base is not null then
      -- Achou na base: confirma uma vez ("Você é Fulano (e-mail)?").
      update imobdesk.at_conversas set modo = 'robo',
             ident = jsonb_build_object('passo', 'confirmar', 'tentativas', 0, 'desde', now(), 'pedido', jsonb_build_array(v_texto), 'pessoaId', v_base)
      where id = c.id;
      perform imobdesk.at_auto(c.id, format('Olá! Bem-vindo(a) ao suporte do setor %s. Você é %s (%s)? Responda 1 para Sim ou 2 para Não.', s.nome,
        (select pe.nome from imobdesk.at_pessoas pe where pe.id = v_base),
        coalesce((select pc.valor from imobdesk.at_pessoa_contatos pc where pc.pessoa_id = v_base and pc.tipo = 'email' order by pc.principal desc, pc.id limit 1), 'sem e-mail')));
      return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
    else
      -- Não achou: pede nome e e-mail para cadastrar.
      update imobdesk.at_conversas set modo = 'robo', ident = jsonb_build_object('passo', 'nome', 'tentativas', 0, 'desde', now(), 'pedido', jsonb_build_array(v_texto))
      where id = c.id;
      perform imobdesk.at_auto(c.id, format('Olá! Bem-vindo(a) ao suporte do setor %s. Ainda não tenho seu cadastro: qual é o seu nome completo?', s.nome));
      return jsonb_build_object('estado', 'identificando', 'conversaId', c.id);
    end if;
  elsif not s.wa_identificar and c.pessoa_id is null then
    -- Setor sem identificação: autocadastro pelo número (como antes).
    update imobdesk.at_conversas
       set pessoa_id = imobdesk.at_pessoa_identificar('whatsapp', v_de, p ->> 'nome', 'WhatsApp ' || s.nome)
     where id = c.id;
  end if;

  v_ticket := imobdesk.at_entrar_fila(c.id, array[v_texto]);
  return jsonb_build_object('estado', 'fila', 'conversaId', c.id, 'ticketId', v_ticket);
end;
$$;

/**
 * Ação na conversa por um usuário (interna: a pública at_conversa_acao confere quem chama).
 * p: {acao: assumir|devolver|transferir|enviar|encerrar, texto?, para?, resolvido?, origem?: 'portal'|'grupo'|'roleta'|'sistema'}
 */
create or replace function imobdesk.at_conversa_executar(p_conversa bigint, p_usuario uuid, p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  c imobdesk.at_conversas;
  s imobdesk.at_setores;
  v_acao text := coalesce(p ->> 'acao', '');
  v_origem text := coalesce(p ->> 'origem', 'portal');
  v_nome text := coalesce(imobdesk.ch_nome_usuario(p_usuario), 'Atendente');
  v_ticket bigint;
  v_texto text;
  v_msg bigint;
  v_para uuid;
  v_cat text;
  v_resolvido boolean := coalesce((p ->> 'resolvido')::boolean, false);
  v_fim text;
begin
  select * into c from imobdesk.at_conversas x where x.id = p_conversa for update;
  if c.id is null then perform imobdesk.erro('NOT_FOUND', 'Conversa não encontrada.'); end if;
  select * into s from imobdesk.at_setores x where x.id = c.setor_id;
  v_ticket := imobdesk.at_ticket_da_conversa(c.id);
  if c.modo in ('encerrada', 'robo') and v_acao <> 'enviar' then
    perform imobdesk.erro('INVALID_INPUT', case when c.modo = 'robo' then 'O colaborador ainda está se identificando.' else 'Conversa encerrada. Ela reabre quando o cliente escrever de novo.' end);
  end if;

  if v_acao in ('assumir', 'transferir') then
    v_para := case when v_acao = 'transferir' then nullif(p ->> 'para', '')::uuid else p_usuario end;
    if v_acao = 'transferir' and not exists (select 1 from imobdesk.at_atendentes a where a.usuario_id = v_para and a.setor_id = c.setor_id) then
      perform imobdesk.erro('INVALID_INPUT', 'Escolha um atendente do mesmo setor.', 'para');
    end if;
    if c.atendente_id is not distinct from v_para then return jsonb_build_object('ok', true); end if;
    update imobdesk.at_conversas set modo = 'atendente', atendente_id = v_para, atendente_desde = now(), ultimo_atendente_id = v_para,
           nao_lidas = case when v_origem = 'portal' and v_acao = 'assumir' then 0 else nao_lidas end, atualizado_em = now()
    where id = c.id;
    update imobdesk.at_atendimentos set atendente_id = v_para, assumido_em = coalesce(assumido_em, now()),
           transferencias = transferencias + case when c.atendente_id is not null then 1 else 0 end
    where id = c.atendimento_id;
    if v_origem = 'roleta' then
      update imobdesk.at_atendentes set ultimo_recebido_em = now() where usuario_id = v_para;
    end if;
    -- Ticket: responsável = quem atende; sai de "Novo" para "Em atendimento".
    select st.categoria into v_cat from imobdesk.ch_tickets t join imobdesk.ch_status st on st.id = t.status_id where t.id = v_ticket;
    update imobdesk.ch_tickets set responsavel_id = v_para,
           status_id = case when v_cat in ('novo', 'pendente') then imobdesk.ch_status_de('andamento', 'Em atendimento') else status_id end,
           assumido_em = coalesce(assumido_em, now())
    where id = v_ticket;
    perform imobdesk.at_evento(c.id, case
      when v_origem = 'roleta' then format('Distribuída pela roleta para %s', imobdesk.ch_nome_usuario(v_para))
      when v_acao = 'transferir' then format('Conversa transferida para %s por %s', imobdesk.ch_nome_usuario(v_para), v_nome)
      when c.atendente_id is not null then format('Conversa transferida de %s para %s', imobdesk.ch_nome_usuario(c.atendente_id), v_nome)
      when v_origem in ('grupo', 'celular') then format('%s assumiu ao responder pelo WhatsApp', v_nome)
      else format('%s assumiu a conversa', v_nome) end);
    return jsonb_build_object('ok', true);
  end if;

  if v_acao = 'devolver' then
    update imobdesk.at_conversas set modo = 'fila', atendente_id = null, atendente_desde = null, fila_desde = now(), atualizado_em = now() where id = c.id;
    update imobdesk.at_atendimentos set devolvido_fila = true where id = c.atendimento_id;
    perform imobdesk.at_evento(c.id, case when v_origem = 'sistema' then format('Voltou à fila: %s sem responder há %s min', coalesce(imobdesk.ch_nome_usuario(c.atendente_id), 'atendente'), s.atendente_sem_resposta_min)
                                                    else format('%s devolveu a conversa à fila', v_nome) end);
    return jsonb_build_object('ok', true);
  end if;

  if v_acao = 'enviar' then
    v_texto := left(btrim(coalesce(p ->> 'texto', '')), 4000);
    if v_texto = '' then perform imobdesk.erro('INVALID_INPUT', 'Escreva a mensagem.', 'texto'); end if;
    if c.modo in ('encerrada', 'robo') then
      perform imobdesk.erro('INVALID_INPUT', 'Conversa encerrada. Responda pelo ticket ou espere o cliente escrever.');
    end if;
    -- "RESOLVIDO" (no portal ou no grupo interno) não vai para o colaborador: resolve o ticket e encerra.
    if imobdesk.at_eh_resolvido(v_texto) then
      if c.modo = 'fila' or c.atendente_id is distinct from p_usuario then
        perform imobdesk.at_conversa_executar(c.id, p_usuario, jsonb_build_object('acao', 'assumir', 'origem', v_origem));
      end if;
      return imobdesk.at_conversa_executar(c.id, p_usuario, jsonb_build_object('acao', 'encerrar', 'resolvido', true, 'direto', true, 'origem', v_origem));
    end if;
    if c.modo = 'fila' or c.atendente_id is distinct from p_usuario then
      if c.modo = 'atendente' and c.atendente_id is distinct from p_usuario and not coalesce((p ->> 'podeTomar')::boolean, false) then
        perform imobdesk.erro('FORBIDDEN', format('Esta conversa está com %s.', imobdesk.ch_nome_usuario(c.atendente_id)));
      end if;
      perform imobdesk.at_conversa_executar(c.id, p_usuario, jsonb_build_object('acao', 'assumir', 'origem', v_origem));
    end if;
    insert into imobdesk.at_mensagens (conversa_id, atendimento_id, direcao, autor, autor_id, tipo, texto, status)
    values (c.id, c.atendimento_id, 'saida', 'atendente', p_usuario, 'texto', v_texto, 'pendente')
    returning id into v_msg;
    perform imobdesk.at_ticket_acao(v_ticket, 'saida', p_usuario, v_nome, v_texto, v_msg, 'pendente');
    update imobdesk.at_conversas set ultima_msg_atendente_em = now(), ultima_msg_em = now(), ultima_previa = left('Você: ' || v_texto, 200), nao_lidas = 0, atualizado_em = now()
    where id = c.id;
    update imobdesk.at_atendimentos set primeira_resposta_em = coalesce(primeira_resposta_em, now()) where id = c.atendimento_id;
    if v_origem = 'portal' then
      perform imobdesk.at_repassar(c.id, v_ticket, 'enviado', format('✔ %s respondeu *#%s* pelo sistema:%s"%s"', v_nome, v_ticket, E'\n', left(v_texto, 500)));
    end if;
    return jsonb_build_object('ok', true, 'mensagemId', v_msg);
  end if;

  if v_acao = 'encerrar' then
    -- Ticket: resolvido (pelo diálogo, a RPC pública já validou e gravou; pela palavra RESOLVIDO, resolve aqui direto)
    -- ou continua "Em atendimento".
    if v_resolvido and coalesce((p ->> 'direto')::boolean, false) then
      perform imobdesk.at_ticket_resolver_direto(v_ticket, p_usuario);
    elsif not v_resolvido then
      select st.categoria into v_cat from imobdesk.ch_tickets t join imobdesk.ch_status st on st.id = t.status_id where t.id = v_ticket;
      if v_cat in ('novo', 'pendente', 'andamento') then
        update imobdesk.ch_tickets set status_id = imobdesk.ch_status_de('andamento', 'Em atendimento'), justificativa_id = null where id = v_ticket;
      end if;
    end if;
    -- Mensagem final ao solicitante, sempre com o número do chamado.
    v_fim := replace(s.msg_encerramento, '{ticket}', '#' || coalesce(v_ticket::text, ''));
    v_fim := case
      when v_ticket is null then v_fim
      when v_resolvido then format('✅ Seu chamado *#%s* foi resolvido e encerrado. %s', v_ticket, v_fim)
      when v_origem = 'sistema' then format('Encerramos esta conversa por falta de resposta. Seu chamado *#%s* continua aberto; é só responder aqui para retomar.', v_ticket)
      else format('Seu chamado *#%s* continua em atendimento com a nossa equipe. %s', v_ticket, v_fim) end;
    perform imobdesk.at_auto(c.id, v_fim);
    update imobdesk.at_conversas set modo = 'encerrada', ultimo_atendente_id = coalesce(c.atendente_id, p_usuario, ultimo_atendente_id), atendente_id = null,
           ultima_previa = 'Atendimento encerrado', atualizado_em = now()
    where id = c.id;
    update imobdesk.at_atendimentos set encerrado_em = now(), encerrado_por = p_usuario,
           encerramento = case when v_origem = 'sistema' then 'inatividade' else 'atendente' end
    where id = c.atendimento_id;
    perform imobdesk.at_evento(c.id, case when v_origem = 'sistema' then format('Encerrada por inatividade (%s h sem mensagem do cliente) · ticket #%s em atendimento', s.encerrar_apos_horas, v_ticket)
      else format('%s encerrou a conversa · ticket #%s %s', v_nome, v_ticket, case when v_resolvido then 'resolvido' else 'continua em atendimento' end) end);
    perform imobdesk.at_repassar(c.id, v_ticket, 'aviso', format('✅ *#%s* encerrado%s · %s', v_ticket,
      case when v_origem = 'sistema' then ' por inatividade' else ' por ' || v_nome end, case when v_resolvido then 'resolvido' else 'continua em atendimento' end));
    return jsonb_build_object('ok', true, 'ticketId', v_ticket);
  end if;

  perform imobdesk.erro('INVALID_INPUT', 'Ação inválida.');
end;
$$;

/**
 * Mensagem digitada no próprio celular do número do sistema (OpenWA, evento message.sent). p:
 *   {sessao, para: telefone do colaborador, texto, externoId}
 * Só vale para conversa em atendimento; o eco do que o sistema enviou é ignorado. "RESOLVIDO" encerra resolvendo.
 */
create or replace function imobdesk.at_whatsapp_propria(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  n imobdesk.at_numeros;
  c imobdesk.at_conversas;
  v_para text := regexp_replace(coalesce(p ->> 'para', ''), '\D', '', 'g');
  v_texto text := left(btrim(coalesce(p ->> 'texto', '')), 4000);
  v_ext text := nullif(p ->> 'externoId', '');
  v_usr uuid;
  v_ticket bigint;
  v_eco bigint;
  v_msg bigint;
begin
  select * into n from imobdesk.at_numeros z where z.canal = 'openwa' and z.openwa_sessao = p ->> 'sessao' and z.ativo;
  if n.id is null or v_texto = '' then return jsonb_build_object('estado', 'ignorado', 'motivo', 'sem número ou sem texto'); end if;
  select * into c from imobdesk.at_conversas z where z.numero_id = n.id and z.telefone = v_para for update;
  if c.id is null or c.modo not in ('fila', 'atendente') then
    return jsonb_build_object('estado', 'ignorado', 'motivo', 'conversa fora de atendimento');
  end if;
  -- Eco do que o próprio sistema mandou (o id pode ainda não ter voltado do envio): mesmo texto nos últimos 10 min.
  if v_ext is not null and exists (select 1 from imobdesk.at_mensagens m where m.externo_id = v_ext) then
    return jsonb_build_object('estado', 'eco');
  end if;
  select m.id into v_eco from imobdesk.at_mensagens m
  where m.conversa_id = c.id and m.direcao = 'saida' and m.criado_em > now() - interval '10 minutes'
    and (m.texto = v_texto or v_texto like '%' || m.texto) and (m.externo_id is null or m.externo_id = v_ext)
  order by m.id desc limit 1;
  if v_eco is not null then
    update imobdesk.at_mensagens set externo_id = coalesce(externo_id, v_ext) where id = v_eco;
    return jsonb_build_object('estado', 'eco');
  end if;

  -- Quem respondeu: o atendente da conversa ou o atendente cadastrado com este número.
  v_usr := coalesce(c.atendente_id, (select a.usuario_id from imobdesk.at_atendentes a where a.whatsapp = n.numero and a.setor_id = n.setor_id));
  if v_usr is not null and c.atendente_id is distinct from v_usr then
    perform imobdesk.at_conversa_executar(c.id, v_usr, jsonb_build_object('acao', 'assumir', 'origem', 'celular'));
  end if;
  if imobdesk.at_eh_resolvido(v_texto) then
    return imobdesk.at_conversa_executar(c.id, v_usr, jsonb_build_object('acao', 'encerrar', 'resolvido', true, 'direto', true, 'origem', 'celular'))
           || jsonb_build_object('estado', 'resolvido', 'conversaId', c.id);
  end if;
  v_ticket := imobdesk.at_ticket_da_conversa(c.id);
  insert into imobdesk.at_mensagens (conversa_id, atendimento_id, direcao, autor, autor_id, tipo, texto, status, externo_id)
  values (c.id, c.atendimento_id, 'saida', 'atendente', v_usr, 'texto', v_texto, 'enviada', v_ext)
  returning id into v_msg;
  perform imobdesk.at_ticket_acao(v_ticket, 'saida', v_usr, coalesce(imobdesk.ch_nome_usuario(v_usr), 'Atendente'), v_texto, v_msg, 'enviado');
  update imobdesk.at_conversas set ultima_msg_atendente_em = now(), ultima_msg_em = now(), ultima_previa = left('Você: ' || v_texto, 200), nao_lidas = 0, atualizado_em = now()
  where id = c.id;
  update imobdesk.at_atendimentos set primeira_resposta_em = coalesce(primeira_resposta_em, now()) where id = c.atendimento_id;
  return jsonb_build_object('estado', 'registrada', 'conversaId', c.id, 'ticketId', v_ticket);
end;
$$;

/** Tudo o que a tela mostra. Supervisão geral vê todos os setores; o gestor, os dele. */
create or replace function imobdesk.at_openwa_painel()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_sup boolean := imobdesk.at_supervisor();
begin
  if auth.uid() is null or not (v_sup or exists (select 1 from imobdesk.at_setores s where imobdesk.at_gestor_de(s.id))) then
    perform imobdesk.erro('FORBIDDEN', 'Só a gestão do atendimento vê esta tela.');
  end if;
  return jsonb_build_object(
    'superAdmin', imobdesk.eh_super_admin(),
    'supervisor', v_sup,
    'conexao', (select jsonb_build_object('url', c.openwa_url, 'chaveMascara', c.openwa_chave_mascara, 'definidoEm', c.openwa_definido_em,
                                          'verificacao', c.openwa_verificacao, 'autoLigado', c.ligado, 'travaPiloto', c.trava_piloto,
                                          'dominios', to_jsonb(c.dominios_corporativos))
                from imobdesk.at_config c where c.id),
    'webhookUrl', null,
    'setores', coalesce((select jsonb_agg(jsonb_build_object(
        'id', s.id, 'nome', s.nome, 'waIdentificar', s.wa_identificar, 'waSoCorporativo', s.wa_so_corporativo, 'waRespostasAuto', s.wa_respostas_auto,
        'msgNaoCorporativo', s.msg_nao_corporativo, 'gestor', imobdesk.at_gestor_de(s.id),
        'numeros', coalesce((select jsonb_agg(jsonb_build_object('id', n.id, 'numero', n.numero, 'canal', n.canal, 'sessao', n.openwa_sessao,
                                                                  'grupo', n.grupo_interno, 'grupoNome', n.grupo_interno_nome) order by n.id)
                             from imobdesk.at_numeros n where n.setor_id = s.id and n.ativo), '[]'),
        'atendentes', coalesce((select jsonb_agg(jsonb_build_object('usuarioId', a.usuario_id, 'nome', u.nome, 'whatsapp', a.whatsapp) order by u.nome)
                                from imobdesk.at_atendentes a join imobdesk.usuarios u on u.id = a.usuario_id
                                where a.setor_id = s.id), '[]')
      ) order by s.nome)
      from imobdesk.at_setores s where s.ativo and (v_sup or imobdesk.at_gestor_de(s.id))), '[]'),
    'linhas', (select count(*) from imobdesk.at_linhas l where l.corporativa)
  );
end;
$$;

/** Regras de WhatsApp do setor (identificação e só linha corporativa). Gestão do setor. */
create or replace function imobdesk.at_setor_whatsapp_salvar(p jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := auth.uid();
  v_setor bigint := (p ->> 'setorId')::bigint;
  v_msg text := btrim(coalesce(p ->> 'msgNaoCorporativo', ''));
begin
  if v_ator is null or not imobdesk.at_gestor_de(v_setor) then
    perform imobdesk.erro('FORBIDDEN', 'Só a gestão do setor altera estas regras.');
  end if;
  if v_msg = '' or length(v_msg) > 1000 then
    perform imobdesk.erro('INVALID_INPUT', 'Escreva a mensagem para quem não é linha corporativa (até 1.000 letras).', 'msgNaoCorporativo');
  end if;
  update imobdesk.at_setores set
    wa_identificar = coalesce((p ->> 'waIdentificar')::boolean, wa_identificar),
    wa_so_corporativo = coalesce((p ->> 'waSoCorporativo')::boolean, wa_so_corporativo),
    wa_respostas_auto = coalesce((p ->> 'waRespostasAuto')::boolean, wa_respostas_auto),
    msg_nao_corporativo = v_msg, atualizado_em = now(), atualizado_por = v_ator
  where id = v_setor;
  perform imobdesk.registrar_auditoria(v_ator, 'atendimento', 'update', 'Regras de WhatsApp do setor alteradas', null, p, v_setor::text);
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array['at_auto_conversa(bigint)', 'at_ticket_resolver_direto(bigint, uuid)', 'at_whatsapp_propria(jsonb)'] loop
    execute format('revoke execute on function imobdesk.%s from public, anon, authenticated', f);
    execute format('grant execute on function imobdesk.%s to service_role', f);
  end loop;
  revoke execute on function imobdesk.at_eh_resolvido(text) from public, anon;
  grant execute on function imobdesk.at_eh_resolvido(text) to authenticated, service_role;
end;
$$;

notify pgrst, 'reload schema';

-- ======================================== 20261009180000_imobdesk_gerencial.sql
-- Gestão de Chamados › Gerencial (docs/PLANO-gerencial.md): visão gerencial e estratégica dos tickets.
-- Só aditiva: permissão nova (copiada de quem já administra), tabela de metas, a RPC de dados e os
-- alertas automáticos no sino (pg_cron, dias úteis às 8h). Nada muda nas tabelas de ticket.

-- ---------- Permissão: quem já tem o menu Gestão de Chamados e administra (admin, ti) ----------
insert into imobdesk.profile_permissions (role, permission_id, enabled)
select v.role, 'gestao_chamados_gerencial', true
from (values ('admin'), ('ti')) as v(role)
where exists (select 1 from imobdesk.perfis p where p.key = v.role)
on conflict (role, permission_id) do nothing;

create or replace function imobdesk.ch_gerencial_pode()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select imobdesk.ch_eh_admin() or imobdesk.tem_permissao('gestao_chamados_gerencial');
$$;

-- ---------- Metas e limites (semáforos, alertas e projeções) ----------
create table if not exists imobdesk.ch_gerencial_metas (
  chave          text        primary key,
  valor          numeric     not null,
  descricao      text        not null,
  atualizado_em  timestamptz not null default now(),
  atualizado_por uuid
);
alter table imobdesk.ch_gerencial_metas enable row level security;
revoke all on imobdesk.ch_gerencial_metas from anon, public, authenticated;
grant all on imobdesk.ch_gerencial_metas to service_role;

insert into imobdesk.ch_gerencial_metas (chave, valor, descricao) values
  ('sla_solucao_pct',        85, 'Meta: % de tickets resolvidos dentro do prazo de solução'),
  ('sla_resposta_pct',       90, 'Meta: % de tickets com a 1ª resposta dentro do prazo'),
  ('tmr_horas',              24, 'Meta: tempo médio de resolução (horas corridas)'),
  ('tpr_horas',               4, 'Meta: tempo médio até a 1ª resposta (horas corridas)'),
  ('reabertura_pct_max',      5, 'Limite: % de tickets reabertos depois de resolvidos'),
  ('backlog_max',            50, 'Limite: tickets abertos ao mesmo tempo'),
  ('vencidos_max',            5, 'Limite: tickets abertos com SLA vencido'),
  ('sem_responsavel_max',     5, 'Limite: tickets abertos sem responsável'),
  ('parado_dias',             7, 'Limite: dias sem nenhuma ação num ticket aberto'),
  ('crescimento_alerta_pct', 20, 'Alerta quando as entradas crescem mais que isto em relação ao período anterior')
on conflict (chave) do nothing;

create or replace function imobdesk.ch_gerencial_metas()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not imobdesk.ch_gerencial_pode() then
    perform imobdesk.erro('FORBIDDEN', 'Sem acesso à visão gerencial.');
  end if;
  return coalesce((select jsonb_object_agg(m.chave, m.valor) from imobdesk.ch_gerencial_metas m), '{}'::jsonb);
end;
$$;

/** Só Admin e Super admin mudam metas. p = {chave: valor, ...}; só chaves já cadastradas. */
create or replace function imobdesk.ch_gerencial_metas_salvar(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ator uuid := (select auth.uid());
  r record;
  v_antes jsonb;
begin
  if not imobdesk.ch_eh_admin() then
    perform imobdesk.erro('FORBIDDEN', 'Só Admin e Super admin alteram metas.');
  end if;
  if jsonb_typeof(p) is distinct from 'object' then
    perform imobdesk.erro('INVALID_INPUT', 'Metas inválidas.');
  end if;
  v_antes := imobdesk.ch_gerencial_metas();
  for r in select key, value from jsonb_each(p) loop
    if jsonb_typeof(r.value) <> 'number' or (r.value::text)::numeric < 0 then
      perform imobdesk.erro('INVALID_INPUT', format('Valor inválido para %s.', r.key), r.key);
    end if;
    update imobdesk.ch_gerencial_metas m
    set valor = (r.value::text)::numeric, atualizado_em = now(), atualizado_por = v_ator
    where m.chave = r.key;
    if not found then
      perform imobdesk.erro('INVALID_INPUT', format('Meta desconhecida: %s.', r.key), r.key);
    end if;
  end loop;
  perform imobdesk.registrar_auditoria(v_ator, 'gerencial', 'metas_alteradas', 'Metas da visão gerencial alteradas',
    v_antes, imobdesk.ch_gerencial_metas(), null);
  return imobdesk.ch_gerencial_metas();
end;
$$;

-- ---------- Dados: todos os tickets que a pessoa pode ver, enxutos, dos últimos p_meses ----------
/**
 * {generated_at, metas, tickets: [{id, criadoEm, assumidoEm, primeiraRespostaEm, encerradoEm, slaRespostaAte,
 *  slaSolucaoAte, slaManual, slaPausadoDesde, ultimaAcaoEm, status, categoriaStatus, setor, equipe, servico,
 *  categoria, urgencia, origem, responsavelId, responsavel, solicitante, departamento, reaberturas, acoesPublicas, ia}]}
 * Ficam de fora excluídos e mesclados. Tickets abertos entram sempre, mesmo que antigos.
 * Os cálculos (KPIs, séries, projeções, alertas) são feitos no front a partir destas linhas.
 */
create or replace function imobdesk.ch_gerencial(p_meses int default 13)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_meses int := least(greatest(coalesce(p_meses, 13), 1), 36);
  v_agora timestamptz := now();
  v_inicio timestamptz := date_trunc('month', (v_agora at time zone 'America/Sao_Paulo') - make_interval(months => v_meses - 1)) at time zone 'America/Sao_Paulo';
begin
  if not imobdesk.ch_gerencial_pode() then
    perform imobdesk.erro('FORBIDDEN', 'Sem acesso à visão gerencial.');
  end if;
  return (
    with encerra as (
      select s.id from imobdesk.ch_status s where s.categoria in ('resolvido', 'fechado', 'cancelado')
    ), vis as (
      select t.* from imobdesk.ch_tickets t
      where t.excluido_em is null and t.mesclado_em_id is null
        and (t.encerrado_em is null or t.criado_em >= v_inicio or t.encerrado_em >= v_inicio)
        and imobdesk.ch_pode_ver_ticket(t.setor_id, t.equipe_id, t.responsavel_id)
    )
    select jsonb_build_object(
      'generated_at', v_agora,
      'inicio', v_inicio,
      'metas', coalesce((select jsonb_object_agg(m.chave, m.valor) from imobdesk.ch_gerencial_metas m), '{}'::jsonb),
      'tickets', coalesce((select jsonb_agg(jsonb_build_object(
          'id', t.id,
          'assunto', t.assunto,
          'criadoEm', t.criado_em,
          'assumidoEm', t.assumido_em,
          'primeiraRespostaEm', t.primeira_resposta_em,
          'encerradoEm', t.encerrado_em,
          'slaRespostaAte', t.sla_resposta_ate,
          'slaSolucaoAte', t.sla_solucao_ate,
          'slaManual', t.sla_manual,
          'slaPausadoDesde', t.sla_pausado_desde,
          'ultimaAcaoEm', (select max(a.criado_em) from imobdesk.ch_ticket_acoes a where a.ticket_id = t.id),
          'status', st.nome,
          'categoriaStatus', st.categoria,
          'setor', (select s.nome from imobdesk.at_setores s where s.id = t.setor_id),
          'equipe', (select e.nome from imobdesk.at_equipes e where e.id = t.equipe_id),
          'servico', (select s.nome from imobdesk.ch_servicos s where s.id = t.servico_id),
          'categoria', (select c.nome from imobdesk.ch_categorias c where c.id = t.categoria_id),
          'urgencia', (select u.nome from imobdesk.ch_urgencias u where u.id = t.urgencia_id),
          'origem', t.origem,
          'responsavelId', t.responsavel_id,
          'responsavel', case when t.responsavel_id is null then null else imobdesk.ch_nome_usuario(t.responsavel_id) end,
          'solicitante', t.solicitante_nome,
          'departamento', (select e.nome from imobdesk.at_pessoa_relacoes r
                           join imobdesk.at_pessoas e on e.id = r.empresa_id and e.tipo = 'departamento'
                           where r.pessoa_id = t.solicitante_pessoa_id order by e.nome limit 1),
          -- Reaberto = saiu de um status encerrado para um não encerrado.
          'reaberturas', (select count(*) from imobdesk.ch_ticket_eventos ev
                          where ev.ticket_id = t.id and ev.tipo = 'status'
                            and (ev.de ->> 'statusId')::bigint in (select id from encerra)
                            and (ev.para ->> 'statusId')::bigint not in (select id from encerra)),
          'acoesPublicas', (select count(*) from imobdesk.ch_ticket_acoes a where a.ticket_id = t.id and a.tipo = 'publica'),
          'ia', (select i.situacao from imobdesk.ch_ticket_ia i where i.ticket_id = t.id order by i.id desc limit 1)
        ) order by t.id)
        from vis t join imobdesk.ch_status st on st.id = t.status_id), '[]'::jsonb)
    )
  );
end;
$$;

-- ---------- Alertas no sino: dias úteis às 8h (America/Sao_Paulo) para quem tem a visão gerencial ----------
/**
 * Confere os limites (metas) sobre os tickets abertos e avisa, no sino, cada pessoa com acesso à visão gerencial
 * (só o que ela pode ver). Um aviso por regra por dia. Devolve quantos avisos foram criados.
 */
create or replace function imobdesk.ch_gerencial_alertas_notificar()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  u record;
  v_total int := 0;
  v_vencidos int;
  v_sem_resp int;
  v_backlog int;
  v_parados int;
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_lim_vencidos numeric := (select valor from imobdesk.ch_gerencial_metas where chave = 'vencidos_max');
  v_lim_sem_resp numeric := (select valor from imobdesk.ch_gerencial_metas where chave = 'sem_responsavel_max');
  v_lim_backlog numeric := (select valor from imobdesk.ch_gerencial_metas where chave = 'backlog_max');
  v_lim_parado numeric := (select valor from imobdesk.ch_gerencial_metas where chave = 'parado_dias');
begin
  for u in
    select us.id
    from imobdesk.usuarios us
    where us.status = 'active'
      and (us.perfil_key in ('admin', 'super_admin') or imobdesk.tem_permissao_de(us.id, 'gestao_chamados_gerencial'))
  loop
    -- Só o que a pessoa pode ver: admin/supervisão vê tudo; gestor, o setor; agente com a permissão, as equipes.
    with vis as (
      select t.* from imobdesk.ch_tickets t
      join imobdesk.ch_status st on st.id = t.status_id
      where t.excluido_em is null and t.mesclado_em_id is null and t.encerrado_em is null
        and st.categoria not in ('resolvido', 'fechado', 'cancelado')
        and (imobdesk.perfil_de(u.id) in ('admin', 'super_admin')
             or imobdesk.tem_permissao_de(u.id, 'gestao_atendimento_supervisao')
             or t.responsavel_id = u.id
             or exists (select 1 from imobdesk.at_setor_gestores g where g.setor_id = t.setor_id and g.usuario_id = u.id)
             or (t.equipe_id is not null and exists (select 1 from imobdesk.at_equipe_membros m where m.equipe_id = t.equipe_id and m.usuario_id = u.id)))
    )
    select count(*) filter (where t.sla_solucao_ate < now() and t.sla_pausado_desde is null),
           count(*) filter (where t.responsavel_id is null),
           count(*),
           count(*) filter (where coalesce((select max(a.criado_em) from imobdesk.ch_ticket_acoes a where a.ticket_id = t.id), t.criado_em) < now() - make_interval(days => v_lim_parado::int))
      into v_vencidos, v_sem_resp, v_backlog, v_parados
    from vis t;

    if v_vencidos > v_lim_vencidos then
      v_total := v_total + imobdesk.ch_gerencial_aviso(u.id, v_hoje, 'Gerencial: SLA vencido acima do limite',
        format('%s tickets abertos com o prazo de solução vencido (limite: %s).', v_vencidos, v_lim_vencidos));
    end if;
    if v_sem_resp > v_lim_sem_resp then
      v_total := v_total + imobdesk.ch_gerencial_aviso(u.id, v_hoje, 'Gerencial: tickets sem responsável',
        format('%s tickets abertos sem responsável (limite: %s).', v_sem_resp, v_lim_sem_resp));
    end if;
    if v_backlog > v_lim_backlog then
      v_total := v_total + imobdesk.ch_gerencial_aviso(u.id, v_hoje, 'Gerencial: backlog acima do limite',
        format('%s tickets abertos ao mesmo tempo (limite: %s).', v_backlog, v_lim_backlog));
    end if;
    if v_parados > 0 then
      v_total := v_total + imobdesk.ch_gerencial_aviso(u.id, v_hoje, 'Gerencial: tickets parados',
        format('%s tickets abertos há mais de %s dias sem nenhuma ação.', v_parados, v_lim_parado));
    end if;
  end loop;
  return v_total;
end;
$$;

/** Um aviso por regra por dia e por pessoa (o título identifica a regra). Devolve 1 se criou. */
create or replace function imobdesk.ch_gerencial_aviso(p_usuario uuid, p_dia date, p_titulo text, p_texto text)
returns int
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from imobdesk.ch_notificacoes n
             where n.usuario_id = p_usuario and n.titulo = p_titulo and (n.criado_em at time zone 'America/Sao_Paulo')::date = p_dia) then
    return 0;
  end if;
  insert into imobdesk.ch_notificacoes (usuario_id, ticket_id, titulo, texto) values (p_usuario, null, p_titulo, p_texto);
  return 1;
end;
$$;

/** "Enviar alertas agora" (tela Alertas): só Admin e Super admin. */
create or replace function imobdesk.ch_gerencial_alertas_enviar()
returns int
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not imobdesk.ch_eh_admin() then
    perform imobdesk.erro('FORBIDDEN', 'Só Admin e Super admin disparam os alertas.');
  end if;
  return imobdesk.ch_gerencial_alertas_notificar();
end;
$$;

-- ---------- Permissões de execução ----------
do $$
declare
  f text;
begin
  foreach f in array array['ch_gerencial_pode()', 'ch_gerencial_metas()', 'ch_gerencial_metas_salvar(jsonb)', 'ch_gerencial(int)', 'ch_gerencial_alertas_enviar()'] loop
    execute format('revoke execute on function imobdesk.%s from public, anon', f);
    execute format('grant execute on function imobdesk.%s to authenticated, service_role', f);
  end loop;
  foreach f in array array['ch_gerencial_alertas_notificar()', 'ch_gerencial_aviso(uuid, date, text, text)'] loop
    execute format('revoke execute on function imobdesk.%s from public, anon, authenticated', f);
    execute format('grant execute on function imobdesk.%s to service_role', f);
  end loop;
end;
$$;

-- ---------- pg_cron: dias úteis às 8h de São Paulo (11h UTC) ----------
do $$
begin
  if to_regnamespace('cron') is null then
    return;
  end if;
  if exists (select 1 from cron.job where jobname = 'imobdesk-gerencial-alertas') then
    perform cron.unschedule('imobdesk-gerencial-alertas');
  end if;
  perform cron.schedule('imobdesk-gerencial-alertas', '0 11 * * 1-5', 'select imobdesk.ch_gerencial_alertas_notificar()');
end;
$$;

notify pgrst, 'reload schema';

commit;
